def _valid_pin_counts(rolls):
    """Return True when every entry is an integer in the range 0..10."""
    # A non-list argument cannot describe a game at all.
    if not isinstance(rolls, (list, tuple)):
        return False
    for pins in rolls:
        # Booleans are integers in Python, so they are rejected explicitly.
        if isinstance(pins, bool) or not isinstance(pins, int):
            return False
        if pins < 0 or pins > 10:
            return False
    return True


def _score_tenth(rem):
    """Score the final frame, returning (points, ok) for the remaining rolls."""
    if not rem:
        return 0, False
    if rem[0] == 10:
        # A strike in the tenth frame earns exactly two extra rolls.
        if len(rem) != 3:
            return 0, False
        if rem[1] != 10 and rem[1] + rem[2] > 10:
            return 0, False
        return sum(rem), True
    if len(rem) < 2:
        return 0, False
    if rem[0] + rem[1] > 10:
        return 0, False
    if rem[0] + rem[1] == 10:
        # A spare in the tenth frame earns exactly one extra roll.
        if len(rem) != 3:
            return 0, False
        return sum(rem), True
    # An open tenth frame ends the game with no bonus roll.
    if len(rem) != 2:
        return 0, False
    return sum(rem), True


def score(rolls):
    if not _valid_pin_counts(rolls):
        return -1
    rolls = list(rolls)
    total = 0
    index = 0
    for frame in range(9):
        if index >= len(rolls):
            return -1
        first = rolls[index]
        if first == 10:
            # Strikes advance one roll and borrow the next two for the bonus.
            if index + 2 >= len(rolls):
                return -1
            total += 10 + rolls[index + 1] + rolls[index + 2]
            index += 1
            continue
        if index + 1 >= len(rolls):
            return -1
        second = rolls[index + 1]
        if first + second > 10:
            return -1
        if first + second == 10:
            # Spares borrow only the single roll that follows them.
            if index + 2 >= len(rolls):
                return -1
            total += 10 + rolls[index + 2]
        else:
            total += first + second
        index += 2
    tenth, ok = _score_tenth(rolls[index:])
    if not ok:
        return -1
    return total + tenth


def report(name, rolls):
    """Format one game as a single human readable line."""
    result = score(rolls)
    # A negative one signals that the roll list was not a legal game.
    label = "invalid" if result < 0 else str(result)
    return "{0}: {1} -> {2}".format(name, rolls, label)


def main():
    games = [
        ("perfect", [10] * 12),
        ("all spares", [5] * 21),
        ("open game", [3, 4] * 10),
        ("too short", [10] * 11),
    ]
    for name, rolls in games:
        print(report(name, rolls))


if __name__ == "__main__":
    main()

