import re
import sys

MIN_LENGTH = 12
BASE_SCORE = 3
MAX_SCORE = 5


def character_classes(password):
    """Return a dict telling which character families occur in the password."""
    # Each flag is evaluated independently so mixed passwords score once per family.
    return {
        "upper": any(c.isupper() for c in password),
        "lower": any(c.islower() for c in password),
        "digit": any(c.isdigit() for c in password),
        "symbol": any(not c.isalnum() for c in password),
    }


def has_long_run(password):
    """True when three or more identical characters appear back to back."""
    # A backreference matches any character repeated twice more in a row.
    return re.search(r"(.)\1{2}", password) is not None


def analyze(password):
    """Score a password from 0 (weak) to 5 (strong)."""
    if not isinstance(password, str):
        raise TypeError("password must be a string")

    score = BASE_SCORE

    # Short passwords lose ground before any bonus is granted.
    if len(password) < MIN_LENGTH:
        score -= 2

    classes = character_classes(password)
    score += sum(1 for present in classes.values() if present)

    # A password built from a single family is trivial to brute force.
    if password.isdigit() or password.isalpha():
        score -= 2

    if has_long_run(password):
        score -= 1

    # Clamp the result so callers always see a value inside the documented range.
    return max(0, min(MAX_SCORE, score))


def describe(password):
    """Build a one-line human readable verdict for a password."""
    score = analyze(password)
    labels = ["very weak", "weak", "fair", "decent", "strong", "excellent"]
    details = []

    # List the missing character families so the user knows what to add.
    for name, present in character_classes(password).items():
        if not present:
            details.append("no " + name)

    if len(password) < MIN_LENGTH:
        details.append("under %d chars" % MIN_LENGTH)
    if has_long_run(password):
        details.append("repeated run")

    suffix = " (" + ", ".join(details) + ")" if details else ""
    return "%d/5 %s%s" % (score, labels[score], suffix)


def main(argv):
    # Passwords come from the command line; fall back to reading standard input.
    candidates = argv[1:]
    if not candidates:
        candidates = [line.strip() for line in sys.stdin if line.strip()]

    for candidate in candidates:
        print("%-24s %s" % (candidate, describe(candidate)))

    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

