"""Library overdue fine calculator."""

GRACE_DAYS = 3
MAX_FINE = 15.00
REPLACEMENT_FEE = 20.00
REPLACEMENT_THRESHOLD = 30

# Each tier is (last day covered by the tier, daily rate in dollars).
TIERS = ((3, 0.00), (10, 0.50), (20, 1.00), (None, 2.00))


def _validate(days):
    """Return days as an int, rejecting anything that is not a whole count."""
    # Booleans are ints in Python, but "True days overdue" is meaningless.
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an integer")
    if days < 0:
        raise ValueError("days cannot be negative")
    return days


def tier_breakdown(days):
    """Split the overdue period into (count, rate, subtotal) chunks."""
    days = _validate(days)
    breakdown = []
    previous = 0
    for limit, rate in TIERS:
        # An open-ended final tier absorbs every remaining day.
        upper = days if limit is None else min(days, limit)
        count = upper - previous
        if count > 0 and rate > 0:
            breakdown.append((count, rate, count * rate))
        previous = upper
        if previous >= days:
            break
    return breakdown


def fines(days):
    """Total fine for a book returned `days` late, in dollars."""
    days = _validate(days)
    if days <= GRACE_DAYS:
        return 0.0
    total = sum(subtotal for _, _, subtotal in tier_breakdown(days))
    # The graduated portion of the fine never exceeds fifteen dollars.
    total = min(total, MAX_FINE)
    if days > REPLACEMENT_THRESHOLD:
        total += REPLACEMENT_FEE
    return float(total)


def format_receipt(days):
    """Build a human readable, multi-line receipt for one overdue book."""
    lines = ["%d day(s) overdue" % days]
    for count, rate, subtotal in tier_breakdown(days):
        lines.append("  %2d day(s) @ $%.2f = $%5.2f" % (count, rate, subtotal))
    total = fines(days)
    # Show the replacement fee separately so the cap stays understandable.
    if days > REPLACEMENT_THRESHOLD:
        lines.append("  replacement fee  = $%5.2f" % REPLACEMENT_FEE)
    lines.append("  TOTAL            = $%5.2f" % total)
    return "\n".join(lines)


def main():
    for days in (0, 3, 5, 10, 15, 20, 25, 31, 60):
        print(format_receipt(days))
        print()


if __name__ == "__main__":
    main()

