def _time_adjusted_fare(base_fare, days_until_departure):
    """Apply the advance-purchase discount or the last-minute premium."""
    # Bookings made well ahead of time earn a ten percent reduction.
    if days_until_departure > 30:
        return base_fare * 0.90
    # Travel booked inside a week carries a twenty percent premium.
    if days_until_departure <= 7:
        return base_fare * 1.20
    return base_fare


def _baggage_fees(baggage_count, tier):
    """Total the per-bag charges, honouring any waived bags for the tier."""
    # Gold waives one bag, platinum waives two, everyone else pays for all.
    if tier == "gold":
        waived = 1
    elif tier == "platinum":
        waived = 2
    else:
        waived = 0

    fees = 0.0
    for position in range(1, baggage_count + 1):
        # Waived bags are the cheapest slots, which are the first ones.
        if position <= waived:
            continue
        if position == 1:
            fees += 25
        elif position == 2:
            fees += 40
        else:
            fees += 50
    return fees


def quote(details):
    """Return the integer price for (base fare, days out, bags, tier)."""
    base_fare, days_until_departure, baggage_count, tier = details

    # Normalise the tier so that casing and padding do not change the result.
    tier = tier.strip().lower()
    if base_fare < 0 or days_until_departure < 0 or baggage_count < 0:
        raise ValueError("fare, days and baggage count must be non-negative")

    total = _time_adjusted_fare(base_fare, days_until_departure)
    total += _baggage_fees(baggage_count, tier)

    # Platinum members also receive five percent off the whole booking.
    if tier == "platinum":
        total *= 0.95

    return round(total)


def describe(details):
    """Build a one-line summary of a booking and its quoted price."""
    base_fare, days_until_departure, baggage_count, tier = details
    price = quote(details)
    bag_word = "bag" if baggage_count == 1 else "bags"
    return (
        f"${base_fare:.0f} fare, {days_until_departure} days out, "
        f"{baggage_count} {bag_word}, {tier} tier -> ${price}"
    )


def main():
    bookings = [
        (200, 40, 1, "plain"),
        (200, 5, 3, "plain"),
        (350, 60, 2, "gold"),
        (500, 14, 4, "Platinum"),
    ]
    # The driver prints each booking in the order it was received.
    for booking in bookings:
        print(describe(booking))


if __name__ == "__main__":
    main()

