DENOMINATIONS = (
    ("quarters", 25),
    ("dimes", 10),
    ("nickels", 5),
    ("pennies", 1),
)


def vend(payment):
    """Return (quarters, dimes, nickels, pennies) of change for (price, amount)."""
    price, amount = payment
    # Refuse the sale outright when the customer has underpaid.
    if amount < price:
        raise ValueError("insufficient payment: {} cents for a {} cent item".format(amount, price))
    change = amount - price
    counts = []
    # Greedy descent works because each denomination divides the larger ones.
    for _name, value in DENOMINATIONS:
        counts.append(change // value)
        change %= value
    return tuple(counts)


def parse_payment(text):
    """Turn a 'price,amount' string of whole cents into a tuple of ints."""
    parts = [piece.strip() for piece in text.split(",")]
    if len(parts) != 2:
        raise ValueError("expected exactly two comma-separated values, got {!r}".format(text))
    numbers = []
    for part in parts:
        # Negative money and fractional cents are both meaningless here.
        if not part.isdigit():
            raise ValueError("{!r} is not a whole number of cents".format(part))
        numbers.append(int(part))
    return tuple(numbers)


def format_change(counts):
    """Describe a change tuple in words, e.g. '2 quarters, 1 penny'."""
    pieces = []
    for (name, _value), count in zip(DENOMINATIONS, counts):
        if count == 0:
            continue
        label = name
        # Singular forms need the irregular plural of 'pennies' undone.
        if count == 1:
            label = "penny" if name == "pennies" else name[:-1]
        pieces.append("{} {}".format(count, label))
    if not pieces:
        return "no change"
    return ", ".join(pieces)


def report(text):
    """Process one 'price,amount' request and return a printable line."""
    try:
        payment = parse_payment(text)
        counts = vend(payment)
    except ValueError as exc:
        # Bad requests are reported inline rather than crashing the machine.
        return "{}: error - {}".format(text, exc)
    return "{}: {} -> {}".format(text, counts, format_change(counts))


def main():
    requests = ["50,100", "133,200", "99,100", "75,75", "120,100", "10,7.5"]
    for request in requests:
        print(report(request))
    # The audit total tells the operator how many coins to load.
    total_coins = 0
    for request in requests:
        try:
            total_coins += sum(vend(parse_payment(request)))
        except ValueError:
            continue
    print("coins dispensed:", total_coins)


if __name__ == "__main__":
    main()

