def split_segments(address):
    """Split a dotted address into its segments, rejecting wrong arity."""
    # Reject anything that is not a string outright, since indexing would fail later.
    if not isinstance(address, str):
        return None
    parts = address.split(".")
    # An address must have exactly four dot-separated segments.
    if len(parts) != 4:
        return None
    return parts


def parse_octet(segment):
    """Return the integer value of one segment, or None if it is malformed."""
    # Empty segments and segments with signs, spaces or letters are all rejected here.
    if not segment.isdigit():
        return None
    # Leading zeros are ambiguous, so only a bare "0" may start with a zero.
    if len(segment) > 1 and segment[0] == "0":
        return None
    value = int(segment)
    # Each octet has to fit in the inclusive range 0..255.
    if value < 0 or value > 255:
        return None
    return value


def classify(octets):
    """Name the address family described by four validated octets."""
    first = octets[0]
    # Anything in 127.x.x.x is reserved for loopback traffic.
    if first == 127:
        return "loopback"
    # The multicast block begins at 224 and runs to the top of the space.
    if first >= 224:
        return "multicast"
    return "valid"


def verify(address):
    """Describe the address type, or report that the address is invalid."""
    segments = split_segments(address)
    if segments is None:
        return "invalid"
    octets = []
    for segment in segments:
        value = parse_octet(segment)
        # A single bad segment invalidates the whole address.
        if value is None:
            return "invalid"
        octets.append(value)
    return classify(octets)


def report(addresses):
    """Build aligned "address -> type" lines for a batch of addresses."""
    # Pad to the longest input so the arrows line up in the output.
    width = max(len(str(a)) for a in addresses)
    lines = []
    for address in addresses:
        lines.append("{:<{w}} -> {}".format(str(address), verify(address), w=width))
    return lines


def main():
    samples = [
        "1.1.1.1",
        "0.0.0.0",
        "127.0.0.1",
        "239.255.255.250",
        "192.168.01.1",
        "256.1.1.1",
        "10.0.0",
        "10.0.0.-1",
    ]
    for line in report(samples):
        print(line)


if __name__ == "__main__":
    main()

