def validate_grid(grid):
    # The board must be exactly three rows of three cells each.
    if not isinstance(grid, (list, tuple)) or len(grid) != 3:
        return False
    for row in grid:
        if not isinstance(row, str) or len(row) != 3:
            return False
        # Only player marks and empty cells are legal characters.
        if any(cell not in "xo." for cell in row):
            return False
    return True


def count_marks(grid):
    # Players alternate, so the two totals are needed to check the turn order.
    flat = "".join(grid)
    return flat.count("x"), flat.count("o")


def turns_are_plausible(x_count, o_count):
    # Whoever moved first may be ahead by a single mark, never more.
    return abs(x_count - o_count) <= 1


def lines_of(grid):
    rows = [grid[0], grid[1], grid[2]]
    # Columns are read by taking the same index from each row.
    cols = ["".join(grid[r][c] for r in range(3)) for c in range(3)]
    diagonals = [
        "".join(grid[i][i] for i in range(3)),
        "".join(grid[i][2 - i] for i in range(3)),
    ]
    return rows + cols + diagonals


def winners(grid):
    found = set()
    for line in lines_of(grid):
        # A line wins when all three cells hold the same player's mark.
        if line[0] != "." and line[0] == line[1] == line[2]:
            found.add(line[0])
    return found


def evaluate(grid):
    if not validate_grid(grid):
        return "invalid"

    x_count, o_count = count_marks(grid)
    if not turns_are_plausible(x_count, o_count):
        return "invalid"

    champions = winners(grid)
    # Two simultaneous winners cannot occur in a real game.
    if len(champions) == 2:
        return "invalid"
    if champions:
        return champions.pop()

    # With no winner, a completely filled board is a draw.
    if x_count + o_count == 9:
        return "draw"
    return "pending"


def describe(grid):
    result = evaluate(grid)
    # Report the rows joined by slashes so a board reads on one line.
    return "{} -> {}".format("/".join(grid) if validate_grid(grid) else grid, result)


def main():
    boards = [
        ["xxx", "oo.", "..."],
        ["xo.", "xo.", "x.o"],
        ["xoo", "oxx", "xxo"],
        ["x..", ".o.", "..x"],
        ["xxx", "ooo", "..."],
        ["xx", "oo", ".."],
    ]
    for board in boards:
        print(describe(board))


if __name__ == "__main__":
    main()

