ROMAN_VALUES = {
    "I": 1,
    "V": 5,
    "X": 10,
    "L": 50,
    "C": 100,
    "D": 500,
    "M": 1000,
}


def normalize(numeral):
    # Roman numerals are case insensitive, so work on a single canonical case.
    if not isinstance(numeral, str):
        return ""
    return numeral.strip().upper()


def has_illegal_repeat(letters):
    # Four identical letters in a row is never a valid numeral.
    run = 0
    previous = None
    for letter in letters:
        if letter == previous:
            run += 1
        else:
            run = 1
            previous = letter
        if run >= 4:
            return True
    return False


def decode(numeral):
    letters = normalize(numeral)
    # An empty string carries no value at all.
    if not letters:
        return 0
    # Any character outside the table makes the whole numeral invalid.
    for letter in letters:
        if letter not in ROMAN_VALUES:
            return 0
    if has_illegal_repeat(letters):
        return 0

    total = 0
    last_index = len(letters) - 1
    for index, letter in enumerate(letters):
        value = ROMAN_VALUES[letter]
        # The final character has no successor, so it always adds.
        if index == last_index:
            total += value
            continue
        next_value = ROMAN_VALUES[letters[index + 1]]
        if value < next_value:
            # Subtractive notation such as IV or IX.
            total -= value
        else:
            total += value
    return total


def report(numeral):
    result = decode(numeral)
    # Zero is the agreed signal for a numeral we could not decode.
    if result == 0:
        return "{0!r} -> invalid".format(numeral)
    return "{0!r} -> {1}".format(numeral, result)


def main():
    samples = ["XIV", "MCMXC", "iii", "MMXXIV", "IIII", "XQ", "", "XLII"]
    for sample in samples:
        print(report(sample))


if __name__ == "__main__":
    main()

