def normalize(card):
    """Remove spaces and hyphens from a raw card number string."""
    # Separators are common in printed card numbers and carry no value.
    return card.replace(" ", "").replace("-", "")


def is_well_formed(digits):
    """Check that the normalized string is all digits and of plausible length."""
    if not digits.isdigit():
        return False
    # Issuer identification standards allow 13 to 19 digits.
    return 13 <= len(digits) <= 19


def checksum(digits):
    """Compute the Luhn checksum of a string of digits."""
    total = 0
    # Processing right to left makes the doubling positions unambiguous.
    for index, char in enumerate(reversed(digits)):
        value = int(char)
        if index % 2 == 1:
            value *= 2
            # Doubling can produce a two digit number; folding it is the same as subtracting nine.
            if value > 9:
                value -= 9
        total += value
    return total


def network_of(digits):
    """Map the leading digit onto a card network name."""
    first = digits[0]
    if first == "4":
        return "visa"
    if first == "5":
        return "mastercard"
    # Any other prefix belongs to a network this task does not identify.
    return "unknown"


def luhn(card):
    """Validate a card number and report its network."""
    digits = normalize(card)
    if not is_well_formed(digits):
        # Malformed input cannot be attributed to any network.
        return (False, "unknown")
    valid = checksum(digits) % 10 == 0
    return (valid, network_of(digits))


def describe(card):
    """Build a human readable one line report for a card number."""
    valid, network = luhn(card)
    verdict = "valid" if valid else "invalid"
    # Show the input exactly as supplied so the report stays traceable.
    return "{}: {} ({})".format(card, verdict, network)


def main():
    samples = [
        "4539 1488 0343 6467",
        "4539-1488-0343-6466",
        "5555 5555 5555 4444",
        "6011 1111 1111 1117",
        "4539 148",
        "4539 1488 034A 6467",
    ]
    for sample in samples:
        print(describe(sample))
    # Summarise how many of the samples passed the checksum.
    accepted = sum(1 for sample in samples if luhn(sample)[0])
    print("{} of {} accepted".format(accepted, len(samples)))


