import re

TOKEN_RE = re.compile(r"\d+\.\d+|\d+|[-+*/()]|\s+")

PRECEDENCE = {"+": 1, "-": 1, "*": 2, "/": 2}


def tokenize(expression):
    """Split an infix expression into numbers, operators and parenthesis."""
    tokens = []
    position = 0
    while position < len(expression):
        match = TOKEN_RE.match(expression, position)
        if match is None:
            raise ValueError("invalid character at index %d" % position)
        text = match.group(0)
        position = match.end()
        # Whitespace carries no meaning for the evaluator, so drop it.
        if not text.strip():
            continue
        tokens.append(text)
    return tokens


def normalize_unary(tokens):
    """Rewrite unary plus/minus into signed numbers so the parser sees operands."""
    result = []
    for token in tokens:
        unary_position = not result or result[-1] in PRECEDENCE or result[-1] == "("
        if token in ("+", "-") and unary_position:
            # A sign at an operand position must be folded into the next number.
            result.append("u" + token)
            continue
        if result and result[-1] in ("u+", "u-"):
            sign = result.pop()
            if token == "(":
                # Negating a parenthesised group becomes (-1) * (group).
                result.extend(["-1" if sign == "u-" else "1", "*", "("])
                continue
            token = ("-" + token) if sign == "u-" else token
        result.append(token)
    return result


def to_postfix(tokens):
    """Shunting yard: convert the infix token list into postfix order."""
    output = []
    operators = []
    for token in tokens:
        if token in PRECEDENCE:
            # Pop every operator of greater or equal precedence first.
            while operators and operators[-1] in PRECEDENCE and PRECEDENCE[operators[-1]] >= PRECEDENCE[token]:
                output.append(operators.pop())
            operators.append(token)
        elif token == "(":
            operators.append(token)
        elif token == ")":
            while operators and operators[-1] != "(":
                output.append(operators.pop())
            if not operators:
                raise ValueError("unbalanced parenthesis")
            operators.pop()
        else:
            output.append(token)
    while operators:
        # Any leftover "(" means the expression was never closed.
        if operators[-1] == "(":
            raise ValueError("unbalanced parenthesis")
        output.append(operators.pop())
    return output


def evaluate_postfix(postfix):
    """Reduce a postfix token list with a dedicated evaluation stack."""
    stack = []
    for token in postfix:
        if token not in PRECEDENCE:
            stack.append(float(token))
            continue
        if len(stack) < 2:
            raise ValueError("missing operand for '%s'" % token)
        right = stack.pop()
        left = stack.pop()
        if token == "+":
            stack.append(left + right)
        elif token == "-":
            stack.append(left - right)
        elif token == "*":
            stack.append(left * right)
        else:
            # Division by zero is reported instead of raising.
            if right == 0:
                return "Math Error: division by zero"
            stack.append(left / right)
    if len(stack) != 1:
        raise ValueError("malformed expression")
    return stack[0]


def calculate(expression):
    tokens = normalize_unary(tokenize(expression))
    if not tokens:
        raise ValueError("empty expression")
    value = evaluate_postfix(to_postfix(tokens))
    if isinstance(value, str):
        return value
    # Whole results are returned as integers to keep the output tidy.
    if float(value).is_integer():
        return int(value)
    return value


def main():
    samples = [
        "2 + 3 * 4",
        "(2 + 3) * 4",
        "((1 + 2) * (3 + 4)) / 7",
        "10 / 4",
        "-3 * (2 - 5)",
        "8 / (3 - 3)",
    ]
    for text in samples:
        print("%-22s = %s" % (text, calculate(text)))


if __name__ == "__main__":
    main()

