import heapq
from collections import Counter
from itertools import count


class Node:
    """A node of the Huffman tree; leaves carry a character."""

    def __init__(self, freq, char=None, left=None, right=None):
        self.freq = freq
        self.char = char
        self.left = left
        self.right = right

    def is_leaf(self):
        return self.left is None and self.right is None


def build_frequency_table(text):
    # Counter gives the number of occurrences of every distinct character.
    return Counter(text)


def build_tree(frequencies):
    tiebreaker = count()
    # The counter keeps the heap comparisons total, since Node is not orderable.
    heap = [(freq, next(tiebreaker), Node(freq, char)) for char, freq in frequencies.items()]
    heapq.heapify(heap)
    while len(heap) > 1:
        left_freq, _, left = heapq.heappop(heap)
        right_freq, _, right = heapq.heappop(heap)
        parent = Node(left_freq + right_freq, None, left, right)
        heapq.heappush(heap, (parent.freq, next(tiebreaker), parent))
    return heap[0][2] if heap else None


def build_codes(root):
    codes = {}
    if root is None:
        return codes
    # A tree made of a single leaf still needs one bit per symbol.
    if root.is_leaf():
        codes[root.char] = "0"
        return codes
    stack = [(root, "")]
    while stack:
        node, prefix = stack.pop()
        if node.is_leaf():
            codes[node.char] = prefix
        else:
            stack.append((node.left, prefix + "0"))
            stack.append((node.right, prefix + "1"))
    return codes


def compress(text):
    if not text:
        return ""
    frequencies = build_frequency_table(text)
    root = build_tree(frequencies)
    codes = build_codes(root)
    # Each character is replaced by the bit string of its path in the tree.
    return "".join(codes[char] for char in text)


def decompress(bits, root):
    """Walk the tree bit by bit to recover the original text."""
    if root is None or not bits:
        return ""
    # A degenerate tree encodes every symbol as a single zero bit.
    if root.is_leaf():
        return root.char * len(bits)
    out = []
    node = root
    for bit in bits:
        node = node.left if bit == "0" else node.right
        if node.is_leaf():
            out.append(node.char)
            node = root
    return "".join(out)


def report(text):
    bits = compress(text)
    original_bits = len(text) * 8
    # Guard against dividing by zero when the input carries no information.
    ratio = len(bits) / original_bits if original_bits else 0.0
    return f"{text!r}: {len(bits)} bits (was {original_bits}), ratio {ratio:.2f} -> {bits}"


def main():
    samples = ["aaaaaaaaaabbbbbccc", "abracadabra", "zzzzzzzz"]
    for sample in samples:
        print(report(sample))
    # Round-tripping proves the generated codes are unambiguous.
    tree = build_tree(build_frequency_table(samples[1]))
    restored = decompress(compress(samples[1]), tree)
    print("round trip ok:", restored == samples[1])


if __name__ == "__main__":
    main()

