from collections import deque


def build_graph(packages):
    """Build adjacency lists and in-degree counts from the package list."""
    graph = {}
    in_degree = {}

    # Every package name mentioned anywhere becomes a node in the graph.
    for name, dependencies in packages:
        graph.setdefault(name, [])
        in_degree.setdefault(name, 0)
        for dependency in dependencies:
            graph.setdefault(dependency, [])
            in_degree.setdefault(dependency, 0)

    for name, dependencies in packages:
        for dependency in dependencies:
            # An edge points from the dependency to the package that needs it.
            graph[dependency].append(name)
            in_degree[name] += 1

    return graph, in_degree


def resolve(packages):
    """Return a valid installation order, or [] when dependencies are circular."""
    graph, in_degree = build_graph(packages)

    # Packages that depend on nothing can be installed straight away.
    ready = deque(sorted(node for node, degree in in_degree.items() if degree == 0))
    order = []

    while ready:
        current = ready.popleft()
        order.append(current)
        for dependent in graph[current]:
            in_degree[dependent] -= 1
            # A dependent is ready once its last incoming edge is removed.
            if in_degree[dependent] == 0:
                ready.append(dependent)

    # A shortfall means at least one cycle blocked part of the graph.
    if len(order) != len(in_degree):
        return []

    return order


def format_plan(order):
    """Turn an installation order into a numbered, human-readable plan."""
    if not order:
        return "Circular dependency detected: nothing can be installed."

    lines = ["Installation plan:"]
    for step, name in enumerate(order, start=1):
        lines.append("  {:>2}. {}".format(step, name))
    return "\n".join(lines)


def main():
    project = [
        ("webapp", ["flask", "requests"]),
        ("flask", ["werkzeug", "jinja2"]),
        ("requests", ["urllib3", "certifi"]),
        ("jinja2", ["markupsafe"]),
        ("werkzeug", ["markupsafe"]),
        ("markupsafe", []),
        ("urllib3", []),
        ("certifi", []),
    ]
    print(format_plan(resolve(project)))

    # Two packages depending on each other form an unresolvable cycle.
    broken = [("alpha", ["beta"]), ("beta", ["alpha"])]
    print(format_plan(resolve(broken)))


if __name__ == "__main__":
    main()

