from collections import deque

PHASE_LENGTH = 30
NORTH_SOUTH = ("north", "south")
EAST_WEST = ("east", "west")
DIRECTIONS = NORTH_SOUTH + EAST_WEST


def _normalize(cars):
    """Validate the raw arrivals and return them sorted by arrival second."""
    normalized = []
    for arrival, direction in cars:
        lane = str(direction).strip().lower()
        # only the four cardinal lanes feed this intersection.
        if lane not in DIRECTIONS:
            raise ValueError("unknown direction: %r" % (direction,))
        second = int(arrival)
        if second < 0:
            raise ValueError("arrival times cannot be negative")
        normalized.append((second, lane))
    # sorting chronologically guarantees every queue stays first-in-first-out.
    normalized.sort(key=lambda item: item[0])
    return normalized


def active_lanes(second):
    """Return the lanes holding a green light during the given second."""
    # the signal starts on north/south and flips every PHASE_LENGTH seconds.
    if (second // PHASE_LENGTH) % 2 == 0:
        return NORTH_SOUTH
    return EAST_WEST


def _run(arrivals):
    """Step the clock second by second and collect wait times per lane."""
    queues = {lane: deque() for lane in DIRECTIONS}
    waits = {lane: [] for lane in DIRECTIONS}
    index = 0
    second = 0
    while index < len(arrivals) or any(queues.values()):
        # every car that has shown up by now joins the back of its lane.
        while index < len(arrivals) and arrivals[index][0] <= second:
            arrival, lane = arrivals[index]
            queues[lane].append(arrival)
            index += 1
        for lane in active_lanes(second):
            # one car per green lane clears the intersection each second.
            if queues[lane]:
                departed = queues[lane].popleft()
                waits[lane].append(second - departed)
        second += 1
    return waits


