    """Average wait time, in seconds, once the intersection has drained."""
    waits = _run(_normalize(cars))
    all_waits = [w for lane_waits in waits.values() for w in lane_waits]
    # an empty schedule means nobody ever waited.
    if not all_waits:
        return 0.0
    return sum(all_waits) / len(all_waits)


