            lines.append("%-6s %3d cars  avg %6.2fs  max %3ds"
                         % (lane, len(lane_waits), average, max(lane_waits)))
        else:
            lines.append("%-6s   0 cars  avg      -    max   -" % lane)
    lines.append("overall avg %.2fs" % simulate(cars))
    return "\n".join(lines)


