MASK_32 = 0xFFFFFFFF
LARGE_PRIME = 2654435761
INITIAL_HASH = 0x811C9DC5
BLOCK_SIZE = 16
PAD_MULTIPLE = 64


def to_bytes(message):
    """Return the byte values of a string using UTF-8 encoding."""
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    # Encoding first keeps multi-byte characters intact as byte values.
    return bytearray(message.encode("utf-8"))


def pad_zeros(data, multiple=PAD_MULTIPLE):
    """Append zero bytes until the length is a multiple of `multiple`."""
    padded = bytearray(data)
    remainder = len(padded) % multiple
    if remainder or not padded:
        # An empty message still needs one full block to be hashed.
        padded.extend(b"\x00" * (multiple - remainder))
    return padded


def split_blocks(data, size=BLOCK_SIZE):
    """Split padded data into blocks of exactly `size` bytes."""
    return [bytes(data[i:i + size]) for i in range(0, len(data), size)]


def block_value(block):
    # Interpreting the block big-endian turns 16 bytes into one integer.
    return int.from_bytes(block, "big")


def checksum(message):
    """Compute a 32-bit pseudo random checksum for `message`."""
    padded = pad_zeros(to_bytes(message))
    digest = INITIAL_HASH
    for block in split_blocks(padded):
        digest ^= block_value(block)
        digest <<= 3
        # Multiplying by a large prime spreads single-bit changes widely.
        digest = (digest * LARGE_PRIME) & MASK_32
    return digest


def format_report(message):
    """Build a one-line report of a message and its checksum."""
    value = checksum(message)
    label = message if message else "(empty)"
    # Showing hexadecimal alongside the decimal value eases comparison.
    return "{:<24} {:>10}  0x{:08X}".format(label, value, value)


def avalanche(left, right):
    """Count how many of the 32 checksum bits differ between two messages."""
    difference = checksum(left) ^ checksum(right)
    return bin(difference).count("1")


def main():
    samples = ["", "a", "b", "hello", "Hello", "hello world", "The quick brown fox"]
    print("{:<24} {:>10}  {}".format("message", "decimal", "hex"))
    for sample in samples:
        print(format_report(sample))
    pairs = [("a", "b"), ("hello", "Hello"), ("hello world", "hello worle")]
    print()
    for left, right in pairs:
        # Nearly identical inputs should still flip many output bits.
        flipped = avalanche(left, right)
        print("{!r} vs {!r}: {} of 32 bits differ".format(left, right, flipped))


if __name__ == "__main__":
    main()

