CAPACITY = 10


def _eviction_candidate(frequencies, last_used):
    """Return the key that should be dropped to make room for a new item."""
    # The primary key is the hit count; the timestamp only breaks ties.
    return min(frequencies, key=lambda item: (frequencies[item], last_used[item]))


def cache(requests):
    """Simulate a hybrid LFU/LRU cache and return the surviving items."""
    if requests is None:
        raise ValueError("requests must be an iterable of cache keys")

    frequencies = {}
    last_used = {}

    # A monotonically increasing clock stands in for wall-clock access times.
    clock = 0

    for item in requests:
        clock += 1
        if item in frequencies:
            # A hit only refreshes the counters, never the cache membership.
            frequencies[item] += 1
            last_used[item] = clock
            continue

        if len(frequencies) >= CAPACITY:
            victim = _eviction_candidate(frequencies, last_used)
            del frequencies[victim]
            del last_used[victim]

        # Newly inserted items always start with a single recorded hit.
        frequencies[item] = 1
        last_used[item] = clock

    # Report the residents from coldest to hottest so the LRU end is visible.
    return sorted(frequencies, key=lambda item: last_used[item])


def report(requests):
    """Build a human readable summary of one cache simulation run."""
    survivors = cache(requests)
    stats = {}
    clock = 0

    # Recompute the per-item hit counts for the retained keys only.
    for item in requests:
        clock += 1
        if item in stats:
            stats[item][0] += 1
            stats[item][1] = clock
        else:
            stats[item] = [1, clock]

    lines = ["{} requests -> {} of {} slots used".format(
        len(list(requests)), len(survivors), CAPACITY)]
    for item in survivors:
        hits, stamp = stats[item]
        lines.append("  {:<8} hits={:<3} last={}".format(item, hits, stamp))
    return "\n".join(lines)


def main():
    workload = ["a", "b", "a", "c", "d", "a", "b", "e", "f", "g",
                "h", "i", "j", "k", "a", "l", "b", "m", "a", "n"]

    print(report(workload))

    # A workload that never exceeds capacity keeps every distinct key.
    small = ["x", "y", "x", "z"]
    print(cache(small))

    # Frequency dominates recency: the hot key survives a long cold tail.
    hot_tail = ["hot"] * 5 + ["c{}".format(n) for n in range(15)]
    print("hot" in cache(hot_tail))


if __name__ == "__main__":
    main()

