def build_lcs_table(first, second):
    # Rows stand for words of the first version, columns for the second.
    rows, cols = len(first), len(second)
    table = [[0] * (cols + 1) for _ in range(rows + 1)]
    for i in range(1, rows + 1):
        for j in range(1, cols + 1):
            if first[i - 1] == second[j - 1]:
                # A match extends the subsequence found on the diagonal.
                table[i][j] = table[i - 1][j - 1] + 1
            else:
                # Otherwise keep the best result reachable from above or from the left.
                table[i][j] = max(table[i - 1][j], table[i][j - 1])
    return table


def backtrack(table, first, second):
    # Walk backwards from the bottom right corner collecting edits in reverse.
    i, j = len(first), len(second)
    edits = []
    while i > 0 and j > 0:
        if first[i - 1] == second[j - 1]:
            edits.append(("keep", first[i - 1]))
            i -= 1
            j -= 1
        elif table[i - 1][j] >= table[i][j - 1]:
            edits.append(("delete", first[i - 1]))
            i -= 1
        else:
            edits.append(("insert", second[j - 1]))
            j -= 1
    # Leftover words of the first version were removed.
    while i > 0:
        edits.append(("delete", first[i - 1]))
        i -= 1
    # Leftover words of the second version were added.
    while j > 0:
        edits.append(("insert", second[j - 1]))
        j -= 1
    edits.reverse()
    return edits


def diff(documents):
    # The input must be exactly two word lists to compare.
    if len(documents) != 2:
        raise ValueError("diff expects a tuple of two documents")
    first, second = documents
    if not all(isinstance(word, str) for word in list(first) + list(second)):
        raise TypeError("documents must contain words as strings")
    table = build_lcs_table(first, second)
    return backtrack(table, first, second)


def format_edits(edits):
    # Render each edit with a marker so the instructions read like a patch.
    markers = {"keep": " ", "insert": "+", "delete": "-"}
    return [f"{markers[action]} {word}" for action, word in edits]


def summarize(edits):
    # Count how many words of each kind the edit script contains.
    counts = {"keep": 0, "insert": 0, "delete": 0}
    for action, _word in edits:
        counts[action] += 1
    return counts


def main():
    original = "the quick brown fox jumps over the lazy dog".split()
    revised = "the quick red fox leaps over the dog".split()
    edits = diff((original, revised))
    for line in format_edits(edits):
        print(line)
    counts = summarize(edits)
    # Report the totals so the size of the change is visible at a glance.
    print(
        "kept {keep}, inserted {insert}, deleted {delete}".format(**counts)
    )


if __name__ == "__main__":
    main()

