MAX_CAPACITY = 50


class DependencyError(ValueError):
    """Raised when the prerequisite graph is malformed."""


def _normalize(items):
    """Turn the raw item descriptions into a clean list of tuples."""
    normalized = []
    seen = set()
    for raw in items:
        ident = raw["id"]
        # Duplicate identifiers would make prerequisites ambiguous.
        if ident in seen:
            raise DependencyError("duplicate item id: %r" % (ident,))
        seen.add(ident)
        weight = int(raw["weight"])
        value = int(raw["value"])
        # A zero-weight item would be pickable infinitely often in this DP.
        if weight <= 0:
            raise DependencyError("item %r must have a positive weight" % (ident,))
        normalized.append((ident, weight, value, raw.get("prereq")))

    known = {entry[0] for entry in normalized}
    for ident, _weight, _value, prereq in normalized:
        # An unresolvable prerequisite can never be satisfied, so reject it.
        if prereq is not None and prereq not in known:
            raise DependencyError("item %r requires unknown item %r" % (ident, prereq))
    return normalized


def _topological_order(normalized):
    """Order items so that every prerequisite comes before its dependents."""
    dependents = {ident: [] for ident, _w, _v, _p in normalized}
    indegree = {ident: 0 for ident, _w, _v, _p in normalized}
    for ident, _weight, _value, prereq in normalized:
        if prereq is not None:
            dependents[prereq].append(ident)
            indegree[ident] += 1

    by_id = {entry[0]: entry for entry in normalized}
    queue = [ident for ident, degree in indegree.items() if degree == 0]
    order = []
    while queue:
        current = queue.pop(0)
        order.append(by_id[current])
        for child in dependents[current]:
            indegree[child] -= 1
            if indegree[child] == 0:
                queue.append(child)

    # Leftover nodes mean the prerequisites form a cycle.
    if len(order) != len(normalized):
        raise DependencyError("prerequisite cycle detected")
    return order


def pack(items):
    """Return the best achievable value and the items realizing it."""
    order = _topological_order(_normalize(items))
    table = [(0, ()) for _ in range(MAX_CAPACITY + 1)]

    for ident, weight, value, prereq in order:
        for cap in range(MAX_CAPACITY, weight - 1, -1):
            base_value, base_selection = table[cap - weight]
            # The prerequisite must already sit in this weight configuration.
            if prereq is not None and prereq not in base_selection:
                continue
            candidate = base_value + value
            if candidate > table[cap][0]:
                table[cap] = (candidate, base_selection + (ident,))

    best_value, best_selection = max(table, key=lambda cell: cell[0])
    return best_value, list(best_selection)


def format_report(items, total_value, chosen):
    """Render a short human readable summary of the packing decision."""
    weights = {raw["id"]: int(raw["weight"]) for raw in items}
    used = sum(weights[ident] for ident in chosen)
    lines = ["Total value: %d" % total_value,
             "Weight used: %d/%d" % (used, MAX_CAPACITY)]
    for ident in chosen:
        lines.append("  + %s (weight %d)" % (ident, weights[ident]))
    # An empty knapsack still deserves an explicit line in the report.
    if not chosen:
        lines.append("  (nothing selected)")
    return "\n".join(lines)


def main():
    catalogue = [
        {"id": "tent", "weight": 20, "value": 40},
        {"id": "stakes", "weight": 5, "value": 25, "prereq": "tent"},
        {"id": "stove", "weight": 12, "value": 30},
        {"id": "fuel", "weight": 6, "value": 22, "prereq": "stove"},
        {"id": "radio", "weight": 9, "value": 18},
        {"id": "antenna", "weight": 4, "value": 15, "prereq": "radio"},
    ]
    total_value, chosen = pack(catalogue)
    print(format_report(catalogue, total_value, chosen))


if __name__ == "__main__":
    main()

