def _index(entries):
    """Map each file path to its (mtime, size) metadata."""
    index = {}
    for entry in entries:
        path, mtime, size = entry
        # Reject duplicate paths, since a mirror cannot hold two versions of one file
        if path in index:
            raise ValueError("duplicate path in listing: %s" % path)
        index[path] = (float(mtime), int(size))
    return index


def _needs_update(source_meta, dest_meta):
    """Decide whether a file present on both sides has to be refreshed."""
    src_mtime, src_size = source_meta
    dst_mtime, dst_size = dest_meta
    # A size mismatch always means the copies differ, whatever the clocks say
    if src_size != dst_size:
        return True
    return src_mtime > dst_mtime


def sync(directories):
    """Return the ordered list of actions mirroring source onto destination."""
    source_entries, dest_entries = directories
    source = _index(source_entries)
    dest = _index(dest_entries)
    actions = []

    # Files missing on the destination side are plain copies
    for path in sorted(source):
        if path not in dest:
            actions.append("copy %s" % path)

    # Files on both sides are compared by timestamp and size
    for path in sorted(source):
        if path in dest and _needs_update(source[path], dest[path]):
            actions.append("update %s" % path)

    # Anything left over on the destination breaks the mirror and goes away
    for path in sorted(dest):
        if path not in source:
            actions.append("delete %s" % path)

    return actions


def summarize(actions):
    """Count the actions per kind so the driver can print a short report."""
    counts = {"copy": 0, "update": 0, "delete": 0}
    for action in actions:
        kind = action.split(" ", 1)[0]
        counts[kind] += 1
    return counts


def main():
    source = [
        ("docs/intro.txt", 1000, 120),
        ("docs/guide.txt", 1500, 900),
        ("img/logo.png", 900, 4096),
    ]
    destination = [
        ("docs/intro.txt", 1000, 120),
        ("docs/guide.txt", 1400, 900),
        ("img/logo.png", 900, 2048),
        ("tmp/old.log", 800, 64),
    ]

    actions = sync((source, destination))
    for action in actions:
        print(action)

    counts = summarize(actions)
    # An empty action list means the two trees are already identical
    if not actions:
        print("in sync")
    else:
        print("%(copy)d copied, %(update)d updated, %(delete)d deleted" % counts)


if __name__ == "__main__":
    main()

