import re

TAG_PATTERN = re.compile(r"<\s*(/?)\s*([A-Za-z][-\w]*)([^>]*)>")


def extract_tags(markup):
    """Yield (kind, name) pairs for every tag found in the markup."""
    for match in TAG_PATTERN.finditer(markup):
        slash, name, rest = match.groups()
        # A trailing slash inside the brackets marks a self closing tag.
        if rest.rstrip().endswith("/"):
            kind = "self"
        elif slash:
            kind = "close"
        else:
            kind = "open"
        yield kind, name.lower()


def analyse(markup):
    """Return the leftover stack and a list of human readable syntax errors."""
    if not isinstance(markup, str):
        raise TypeError("markup must be a string")

    stack = []
    errors = []

    for kind, name in extract_tags(markup):
        # Self closing tags never affect the nesting stack.
        if kind == "self":
            continue
        if kind == "open":
            stack.append(name)
            continue
        # A closing tag with nothing open cannot possibly match.
        if not stack:
            errors.append("unexpected closing tag </%s>" % name)
        elif stack[-1] == name:
            stack.pop()
        else:
            # The mismatch means the tags overlap instead of nesting.
            errors.append("expected </%s> but found </%s>" % (stack[-1], name))
            stack.pop()

    for unclosed in reversed(stack):
        errors.append("unclosed tag <%s>" % unclosed)

    return stack, errors


def validate(markup):
    """True when every opening tag is closed in the correct order."""
    stack, errors = analyse(markup)
    # Balanced markup leaves the stack empty and produces no errors.
    return not stack and not errors


def report(markup):
    """Format a one line verdict, listing the problems when there are any."""
    _, errors = analyse(markup)
    if validate(markup):
        return "OK: %s" % markup
    # Several errors are joined so the whole diagnosis fits on one line.
    return "FAIL: %s -> %s" % (markup, "; ".join(errors))


def main():
    samples = [
        "<html><body><p>Hello</p></body></html>",
        "<div><img src='a.png' /><br/></div>",
        "<a><b></a></b>",
        "<ul><li>one<li>two</ul>",
        "plain text without any markup",
        "</p>",
    ]
    for sample in samples:
        print(report(sample))


if __name__ == "__main__":
    main()

