import operator


class UndefinedVariable(Exception):
    """Raised when the tree references a name that was never defined."""

    def __init__(self, name):
        super().__init__(name)
        self.name = name


# Arithmetic primitives are folded left-to-right over their arguments.
OPERATIONS = {
    "+": operator.add,
    "-": operator.sub,
    "*": operator.mul,
    "/": operator.truediv,
    "%": operator.mod,
    "max": max,
    "min": min,
}


def lookup(name, env):
    # Variables live in a plain dictionary that is threaded through the tree.
    if name not in env:
        raise UndefinedVariable(name)
    return env[name]


def eval_node(node, env):
    # Atoms are either literal numbers or variable references.
    if isinstance(node, (int, float)):
        return node
    if isinstance(node, str):
        return lookup(node, env)

    op = node[0]
    args = node[1:]

    # A definition evaluates its right-hand side and mutates the environment.
    if op in ("define", "def", "="):
        name, expression = args
        value = eval_node(expression, env)
        env[name] = value
        return value

    # A sequence evaluates its children in order and yields the last value.
    if op in ("begin", "do"):
        result = None
        for child in args:
            result = eval_node(child, env)
        return result

    if op not in OPERATIONS:
        raise ValueError("unknown operation: {!r}".format(op))

    func = OPERATIONS[op]
    values = [eval_node(child, env) for child in args]

    # Unary minus and unary division mean negation and reciprocal.
    if len(values) == 1:
        if op == "-":
            return -values[0]
        if op == "/":
            return 1 / values[0]
        return values[0]

    accumulator = values[0]
    for value in values[1:]:
        accumulator = func(accumulator, value)
    return accumulator


def evaluate(tree):
    env = {}
    try:
        return eval_node(tree, env)
    except UndefinedVariable as bad:
        # Execution halts and the caller receives a readable diagnostic.
        return "Error: undefined variable '{}'".format(bad.name)


def format_result(tree):
    result = evaluate(tree)
    # Whole floats are printed without a trailing ".0" for readability.
    if isinstance(result, float) and result.is_integer():
        return str(int(result))
    return str(result)


def main():
    program = ["begin",
               ["define", "x", ["+", 2, 3, ["*", 4, 5]]],
               ["define", "y", ["-", ["/", "x", 5], 1]],
               ["max", ["*", "x", "y"], ["+", "x", ["%", 100, 7]]]]
    broken = ["+", 1, ["*", "z", 2]]

    print(format_result(program))
    print(format_result(broken))


if __name__ == "__main__":
    main()

