MAX_HEALTH = 100
POTION_HEAL = 30
POISON_DAMAGE = 5
MONSTER_REWARD = 10
MONSTER_DAMAGE = {"goblin": 10, "orc": 20}
ORC_GOLD_LOSS = 5


def resolve_monster(name, health, gold):
    """Fight a monster: take its damage, lose gold to orcs, claim the reward."""
    health -= MONSTER_DAMAGE[name]
    # Orcs steal gold, but the purse can never go negative.
    if name == "orc":
        gold = max(0, gold - ORC_GOLD_LOSS)
    # A hero who falls in combat collects no reward.
    if health <= 0:
        return 0, gold, False
    return health, gold + MONSTER_REWARD, True


def battle(events):
    """Run the encounters in order and report (health, gold, survived)."""
    health = MAX_HEALTH
    gold = 0
    poisoned = False

