"""Cleaning and analysis of raw temperature readings from an industrial sensor."""

CAP = 100.0
DROP_THRESHOLD = 20.0
RISE_RUN_LENGTH = 3


def sanitize(readings):
    """Replace non-positive readings with the previous valid one and cap extremes."""
    cleaned = []
    previous = None
    for value in readings:
        # Zero and negative values mean a sensor glitch, not a real temperature.
        if value <= 0:
            if previous is None:
                # No earlier valid reading exists yet, so the glitch is dropped.
                continue
            value = previous
        elif value > CAP:
            value = CAP
        previous = value
        cleaned.append(float(value))
    return cleaned


def smooth(values):
    """Replace every interior reading with the mean of itself and its neighbours."""
    if len(values) < 3:
        # The ends are never averaged, so short series pass through untouched.
        return list(values)
    averaged = [values[0]]
    for i in range(1, len(values) - 1):
        averaged.append((values[i - 1] + values[i] + values[i + 1]) / 3.0)
    averaged.append(values[-1])
    return averaged


def rising_runs(values):
    """Return start indices of stretches that increase strictly three times in a row."""
    starts = []
    streak = 0
    for i in range(1, len(values)):
        if values[i] > values[i - 1]:
            streak += 1
        else:
            streak = 0
        # A streak of three consecutive increases spans four readings.
        if streak >= RISE_RUN_LENGTH:
            starts.append(i - RISE_RUN_LENGTH)
    return starts


def count_sudden_drops(values):
    """Count consecutive pairs whose temperature falls by more than the threshold."""
    drops = 0
    for i in range(1, len(values)):
        if values[i - 1] - values[i] > DROP_THRESHOLD:
            drops += 1
    return drops


def clean(readings):
    smoothed = smooth(sanitize(readings))
    return smoothed, count_sudden_drops(smoothed)


def report(readings):
    """Build a human readable summary of one measurement stream."""
    smoothed, drops = clean(readings)
    lines = ["raw:      " + ", ".join(str(r) for r in readings),
             "smoothed: " + ", ".join("%.2f" % v for v in smoothed),
             "sudden drops: %d" % drops]
    runs = rising_runs(smoothed)
    if runs:
        # Sustained rises are worth naming explicitly in the summary.
        lines.append("rising runs start at indices: " + ", ".join(str(i) for i in runs))
    else:
        lines.append("rising runs start at indices: none")
    return "\n".join(lines)


def main():
    streams = [[50, 10],
               [20, -5, 0, 140, 30, 35, 40, 45, 12],
               [-3, 0, 70]]
    for stream in streams:
        print(report(stream))
        print("-" * 40)


if __name__ == "__main__":
    main()

