BASE_VALUES = {"single": 1, "double": 2, "triple": 3, "home run": 4}
ALIASES = {"homerun": "home run", "hr": "home run", "walk": "ball", "k": "strike"}


def normalize(raw):
    """Turn a raw outcome string into one of the recognised event names."""
    cleaned = " ".join(str(raw).strip().lower().split())
    # Aliases let callers write "homerun" or "HR" for the same event.
    cleaned = ALIASES.get(cleaned, cleaned)
    if cleaned not in BASE_VALUES and cleaned not in ("strike", "ball", "out"):
        raise ValueError("unknown outcome: %r" % (raw,))
    return cleaned


def advance_runners(bases, base_value):
    """Move every runner forward by base_value and return (new_bases, runs)."""
    runs = 0
    new_bases = [False, False, False]
    for index, occupied in enumerate(bases):
        if not occupied:
            continue
        target = index + base_value
        # A runner reaching index 3 or beyond has crossed home plate.
        if target >= 3:
            runs += 1
        else:
            new_bases[target] = True
    if base_value >= 4:
        # The batter scores too on a home run, and the bases end up empty.
        return [False, False, False], runs + 1
    new_bases[base_value - 1] = True
    return new_bases, runs


def play(outcomes):
    runs = 0
    batters = 0
    outs = 0
    strikes = 0
    balls = 0
    bases = [False, False, False]
    for raw in outcomes:
        outcome = normalize(raw)
        if outcome == "strike":
            strikes += 1
            # Three strikes retire the batter and reset the count.
            if strikes == 3:
                outs += 1
                batters += 1
                strikes = balls = 0
        elif outcome == "ball":
            balls += 1
            # Four balls are a walk, which forces runners like a single.
            if balls == 4:
                bases, scored = advance_runners(bases, 1)
                runs += scored
                batters += 1
                strikes = balls = 0
        elif outcome == "out":
            outs += 1
            batters += 1
            strikes = balls = 0
        else:
            bases, scored = advance_runners(bases, BASE_VALUES[outcome])
            runs += scored
            batters += 1
            strikes = balls = 0
        # The half inning stops the moment the third out is recorded.
        if outs == 3:
            break
    return runs, batters


def describe(outcomes):
    """Format the result of a half inning as a short human-readable line."""
    runs, batters = play(outcomes)
    run_word = "run" if runs == 1 else "runs"
    return "%d %s on %d batters faced" % (runs, run_word, batters)


def main():
    innings = [
        ["single", "home run"],
        ["ball", "ball", "ball", "ball", "strike", "strike", "strike", "double"],
        ["out", "strike", "out", "single", "out", "home run"],
    ]
    for outcomes in innings:
        print(describe(outcomes))


if __name__ == "__main__":
    main()

