"""Hard-drive defragmenter.

Positive numbers are ordinary file blocks, zeros are free space and
negative numbers are system blocks that may never leave their slot.
"""


def _validate(disk):
    """Return a mutable copy of the disk after checking every block."""
    if not isinstance(disk, (list, tuple)):
        raise TypeError("disk must be a list or tuple of integers")
    for block in disk:
        # Booleans are ints in Python, yet they are never valid block markers.
        if isinstance(block, bool) or not isinstance(block, int):
            raise TypeError("disk blocks must be integers, got %r" % (block,))
    return list(disk)


def locked_positions(disk):
    """Collect every index that must keep its current content."""
    locked = {i for i, block in enumerate(disk) if block < 0}
    index = 0
    size = len(disk)
    while index < size:
        if disk[index] == 0:
            start = index
            while index < size and disk[index] == 0:
                index += 1
            # A gap is trapped only when system blocks flank it on both sides.
            if start - 1 in locked and index < size and disk[index] < 0:
                locked.update(range(start, index))
        else:
            index += 1
    return locked


def plan_layout(disk, locked):
    """Rewrite the movable slots so each file sits in one contiguous run."""
    movable = [i for i in range(len(disk)) if i not in locked]
    order = []
    sizes = {}
    for slot in movable:
        file_id = disk[slot]
        # Free space is not a file, so it takes no place in the ordering.
        if file_id == 0:
            continue
        if file_id not in sizes:
            order.append(file_id)
            sizes[file_id] = 0
        sizes[file_id] += 1
    layout = list(disk)
    cursor = 0
    for file_id in order:
        # Files keep their first-seen order and grow towards the disk front.
        for _ in range(sizes[file_id]):
            layout[movable[cursor]] = file_id
            cursor += 1
    for slot in movable[cursor:]:
        layout[slot] = 0
    return layout


def count_moves(original, layout):
    """Count the file blocks that ended up in a slot they did not occupy."""
    moved = 0
    for before, after in zip(original, layout):
        if after != 0 and after != before:
            moved += 1
    return moved


def format_layout(disk):
    """Render a disk as a compact human readable strip."""
    cells = []
    for block in disk:
        # System blocks get an "S" prefix so locked areas stand out.
        if block < 0:
            cells.append("S%d" % -block)
        elif block == 0:
            cells.append(".")
        else:
            cells.append(str(block))
    return " ".join(cells)


def defragment(disk):
    original = _validate(disk)
    locked = locked_positions(original)
    layout = plan_layout(original, locked)
    return layout, count_moves(original, layout)


def main():
    samples = [
        [1, 0, 2, 1, 0, 3, 2, 0, 1],
        [0, 1, -7, 0, 0, -8, 2, 1, 0, 2, 3],
        [-1, 0, 0, 5, 5, 0, 4],
    ]
    for sample in samples:
        layout, moves = defragment(sample)
        print("before: %s" % format_layout(sample))
        print("after : %s  (%d blocks moved)" % (format_layout(layout), moves))


if __name__ == "__main__":
    main()

