    # weight, volume and distance are physical quantities and cannot be negative.
    for name, value in (("weight", weight), ("volume", volume), ("distance", distance)):
        if value < 0:
            raise ValueError("%s must not be negative" % name)
    # the zone index selects a pricing rule, so it must be one we know about.
    if zone not in ZONE_NAMES:
        raise ValueError("unknown destination zone: %r" % (zone,))
    return float(weight), float(volume), float(distance), bool(hazardous), bool(express), int(zone)


def chargeable_weight(weight, volume):
    """Return the greater of actual weight and dimensional weight."""
    dimensional = volume * DIMENSIONAL_FACTOR
    # carriers bill on whichever weight is larger, which is the point of the comparison.
    if dimensional > weight:
        return dimensional
    return weight


def shipping_cost(shipment):
    """Determine the freight shipping cost, floored to whole dollars."""
    weight, volume, distance, hazardous, express, zone = parse_shipment(shipment)

    billable = chargeable_weight(weight, volume)
    cost = billable * WEIGHT_RATE
    # distance scales the base cost in units of one hundred kilometres.
    cost *= distance / 100.0

    if hazardous:
        cost += HAZMAT_SURCHARGE
    if express:
        cost *= EXPRESS_MULTIPLIER

    # zone zero is local delivery and earns a discount; zone two costs extra.
    if zone == 0:
        cost *= 0.90
    elif zone == 2:
        cost += REMOTE_FEE

    # hazardous freight is uncapped because the surcharge must always be recovered.
    if not hazardous:
        cost = min(cost, STANDARD_CAP)

    return math.floor(cost)


def describe(shipment):
    """Build a one-line human readable quote for a shipment."""
    weight, volume, distance, hazardous, express, zone = parse_shipment(shipment)
    flags = []
    if hazardous:
        flags.append("hazmat")
    if express:
        flags.append("express")
    # an empty flag list would read badly in the report, so name the default service.
    label = ", ".join(flags) if flags else "standard"
    return "%6.1f kg %5.2f m3 %6.0f km  %-8s %-16s $%d" % (
        weight, volume, distance, ZONE_NAMES[zone], label, shipping_cost(shipment))


def main():
    manifest = [
        [100, 2.0, 500, False, True, 2],
        [40, 0.1, 120, False, False, 0],
        [900, 5.0, 2500, True, True, 1],
        [250, 1.0, 1800, False, False, 1],
    ]
    print("Freight quotes")
    for shipment in manifest:
        print(describe(shipment))
    total = sum(shipping_cost(s) for s in manifest)
    print("Manifest total: $%d" % total)


if __name__ == "__main__":
    main()

