def parse_sensor_reading(raw):
    """Convert a raw six-element sensor list into a validated tuple."""
    # The controller relies on positional data, so the length is checked first.
    if len(raw) != 6:
        raise ValueError("sensor reading must contain exactly 6 fields")

    hour, occupied, outside_temp, window_open, vacation, day_index = raw

    # Hour and day come from a clock, so they must be whole numbers in range.
    if not isinstance(hour, int) or not 0 <= hour <= 23:
        raise ValueError("hour must be an integer between 0 and 23")
    if not isinstance(day_index, int) or not 0 <= day_index <= 6:
        raise ValueError("day index must be an integer between 0 (Mon) and 6 (Sun)")

    # Outside temperature may arrive as a float from the probe.
    if not isinstance(outside_temp, (int, float)):
        raise ValueError("outside temperature must be numeric")

    return (hour, bool(occupied), outside_temp, bool(window_open),
            bool(vacation), day_index)


def target_temperature(reading):
    """Return the integer target indoor temperature for the given reading."""
    hour, occupied, outside_temp, window_open, vacation, day_index = \
        parse_sensor_reading(reading)

    target = 72

    # An empty house is set back to save energy.
    if not occupied:
        target -= 5

    # Vacation mode overrides the occupancy setback entirely.
    if vacation:
        target = 60

    # An open window means heating would be wasted, so it is shut off.
    if window_open:
        target = 40

    # Night hours wrap past midnight, hence the OR instead of a range test.
    if hour >= 22 or hour <= 6:
        target -= 3

    # Weekend mornings get a comfort boost while the household lingers in bed.
    if day_index in (5, 6) and 8 <= hour <= 10:
        target += 2

    # Sub-freezing air outside risks burst pipes, so nudge the target up.
    if outside_temp < 0:
        target += 1

    return int(target)


def describe(reading):
    """Build a one-line human readable summary of a reading and its target."""
    names = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
    hour, occupied, outside_temp, window_open, vacation, day_index = \
        parse_sensor_reading(reading)
    flags = []

    # Only the active flags are worth mentioning in the summary.
    if not occupied:
        flags.append("away")
    if vacation:
        flags.append("vacation")
    if window_open:
        flags.append("window open")

    state = ", ".join(flags) if flags else "normal"
    return "{} {:02d}:00  outside {}째  [{}] -> {}째".format(
        names[day_index], hour, outside_temp, state, target_temperature(reading))


def main():
    readings = [
        [23, True, 25, False, False, 4],
        [9, True, 5, False, False, 5],
        [14, False, -4, False, False, 1],
        [12, True, 10, True, False, 2],
        [7, False, 3, False, True, 3],
    ]
    for reading in readings:
        print(describe(reading))


if __name__ == "__main__":
    main()

