# Rain index to flight-time multiplier, as specified by the delivery model.
RAIN_MULTIPLIERS = {0: 1.0, 1: 1.2, 2: 1.5}

MAX_FLIGHT_MINUTES = 45
FREE_PAYLOAD_KG = 2.0
TAKEOFF_LANDING_MINUTES = 3


def parse_request(request):
    """Validate a raw delivery request list and return its five fields."""
    if len(request) != 5:
        raise ValueError("a request needs distance, payload, wind, rain and airspace flag")
    distance, payload, wind, rain, restricted = request
    # Distances and weights are physical quantities, so negatives are rejected.
    if distance < 0 or payload < 0 or wind < 0:
        raise ValueError("distance, payload and wind speed must be non-negative")
    if rain not in RAIN_MULTIPLIERS:
        raise ValueError("rain severity index must be 0, 1 or 2")
    return float(distance), float(payload), float(wind), int(rain), bool(restricted)


def delivery_time(request):
    """Return the estimated delivery time in whole minutes, or 0 if not viable."""
    distance, payload, wind, rain, restricted = parse_request(request)

    # Restricted airspace makes the flight illegal before anything else matters.
    if restricted:
        return 0

    minutes = distance * 2.0

    # Every kilogram above the free allowance costs one extra minute.
    if payload > FREE_PAYLOAD_KG:
        minutes += payload - FREE_PAYLOAD_KG

    # Above 40 km/h the drone cannot hold a heading at all.
    if wind > 40:
        return 0
    if wind > 20:
        minutes += 5

    minutes *= RAIN_MULTIPLIERS[rain]

    # The battery limit is checked on the cruise time, before ground procedures.
    if minutes > MAX_FLIGHT_MINUTES:
        return 0

    minutes += TAKEOFF_LANDING_MINUTES
    return int(minutes)


def describe(request):
    """Build a one-line human-readable verdict for a single request."""
    minutes = delivery_time(request)
    distance, payload, wind, rain, restricted = parse_request(request)
    label = "{:.1f} km / {:.1f} kg / wind {:.0f} / rain {}".format(
        distance, payload, wind, rain
    )
    if minutes == 0:
        # Zero minutes always means the delivery was refused; explain why.
        if restricted:
            reason = "restricted airspace"
        elif wind > 40:
            reason = "wind too strong"
        else:
            reason = "exceeds battery range"
        return "{}: REJECTED ({})".format(label, reason)
    return "{}: {} minutes".format(label, minutes)


def main():
    requests = [
        [10, 3.5, 15, 0, False],
        [12, 1.0, 25, 1, False],
        [8, 4.0, 45, 0, False],
        [30, 2.0, 10, 2, False],
        [5, 0.5, 5, 0, True],
    ]
    for request in requests:
        print(describe(request))


if __name__ == "__main__":
    main()

