"""Transaction risk scoring.

Takes a transaction described as a flat list of features and turns it into a
risk score between 0 and 100, plus a short human-readable report.
"""

MAX_SCORE = 100
FIELD_NAMES = (
    "amount",
    "account_age_days",
    "distance_from_home_miles",
    "hour_of_day",
    "international_merchant",
    "consecutive_transactions",
)


def parse_transaction(transaction):
    """Validate the raw list and return it as a dict keyed by field name."""
    if len(transaction) != len(FIELD_NAMES):
        raise ValueError(
            "expected %d fields, got %d" % (len(FIELD_NAMES), len(transaction))
        )
    record = dict(zip(FIELD_NAMES, transaction))
    # The boolean flag is the only non-numeric field, everything else must be a number.
    for name in FIELD_NAMES:
        if name == "international_merchant":
            continue
        if not isinstance(record[name], (int, float)) or isinstance(record[name], bool):
            raise TypeError("field %r must be numeric" % name)
    if not 0 <= record["hour_of_day"] <= 23:
        raise ValueError("hour_of_day must be in the range 0..23")
    return record


def score_transaction(transaction):
    """Return the capped risk score for one transaction given as a list."""
    tx = parse_transaction(transaction)
    score = 0

    # Large amounts are risky, and very large amounts are cumulatively worse.
    if tx["amount"] > 500:
        score += 10
    if tx["amount"] > 2000:
        score += 30

    # Brand new accounts have no history to vouch for them.
    if tx["account_age_days"] < 30:
        score += 20

    # Geographic risk: far from home, or off-shore entirely.
    if tx["distance_from_home_miles"] > 50:
        score += 15
    if tx["international_merchant"]:
        score += 50

    # Overnight activity between midnight and 5am is unusual for most users.
    if 0 <= tx["hour_of_day"] < 5:
        score += 25

    # Velocity check: each rapid-fire transaction past the third adds risk.
    if tx["consecutive_transactions"] > 3:
        score += 10 * (tx["consecutive_transactions"] - 3)

    # Long-standing customers earn a trust discount.
    if tx["account_age_days"] > 5 * 365:
        score -= 20

    # Keep the result inside the reportable 0..100 band.
    return max(0, min(MAX_SCORE, score))


def risk_band(score):
    """Map a numeric score onto a coarse decision band."""
    if score >= 75:
        return "BLOCK"
    if score >= 40:
        return "REVIEW"
    return "APPROVE"


def format_report(transaction):
    score = score_transaction(transaction)
    return "amount=%-7s age=%-5s score=%3d -> %s" % (
        transaction[0],
        transaction[1],
        score,
        risk_band(score),
    )


def main():
    batch = [
        [750, 15, 10, 2, False, 5],
        [2500, 400, 120, 14, True, 1],
        [40, 2600, 5, 19, False, 2],
    ]
    for tx in batch:
        print(format_report(tx))


if __name__ == "__main__":
    main()

