def irrigation_duration(params):
    """Return the irrigation time in minutes for one field reading."""
    moisture, rain_mm, crop_index, temperature, restricted = params

    # Start from the nominal watering cycle used by the controller.
    minutes = 60.0

    # Wet soil needs less water, and saturated soil needs none at all.
    if moisture > 60:
        minutes = 0.0
    elif moisture > 40:
        minutes -= 30

    # Forecast rain substitutes for two minutes of irrigation per millimetre.
    minutes -= 2 * rain_mm

    # Thirsty crops get a fixed bonus depending on their water need index.
    if crop_index == 1:
        minutes += 20
    elif crop_index == 2:
        minutes += 40

    # Heat drives evaporation, so compensate above thirty degrees.
    if temperature > 30:
        minutes += 15

    # Local restrictions halve whatever the schedule asked for.
    if restricted:
        minutes /= 2

    # The valve controller refuses anything longer than two hours.
    minutes = min(minutes, 120)

    return int(minutes)


def validate_reading(params):
    """Check one raw reading and return it with normalised field types."""
    if len(params) != 5:
        raise ValueError("a reading needs exactly 5 fields")

    moisture, rain_mm, crop_index, temperature, restricted = params

    # Sensor percentages outside 0-100 mean a broken or miswired probe.
    if not 0 <= moisture <= 100:
        raise ValueError("soil moisture %r is out of range" % (moisture,))

    # Negative rainfall would silently add irrigation time instead of removing it.
    if rain_mm < 0:
        raise ValueError("rain forecast cannot be negative")

    if crop_index not in (0, 1, 2):
        raise ValueError("unknown crop water need index %r" % (crop_index,))

    return [moisture, rain_mm, crop_index, temperature, bool(restricted)]


def format_plan(name, params, minutes):
    """Build a one-line report for a field's irrigation plan."""
    if minutes == 0:
        action = "no irrigation needed"
    else:
        action = "irrigate for %d min" % minutes

    # Flag restricted fields so the operator knows the cut was applied.
    suffix = " (restricted)" if params[4] else ""
    return "%-10s %s%s" % (name + ":", action, suffix)


def main():
    fields = {
        "north": [35, 10, 1, 32, True],
        "south": [65, 0, 2, 28, False],
        "terrace": [20, 2, 2, 35, False],
        "orchard": [45, 1, 0, 31, True],
    }

    total = 0
    # Fields are reported in a stable order so the log stays comparable.
    for name in sorted(fields):
        reading = validate_reading(fields[name])
        minutes = irrigation_duration(reading)
        total += minutes
        print(format_plan(name, reading, minutes))

    print("Total valve time: %d min" % total)


if __name__ == "__main__":
    main()

