"""Car wash price calculator.

Computes the final charge for a wash order described as a flat list of options.
"""

PACKAGE_PRICES = (10.0, 15.0, 25.0)
SIZE_SURCHARGES = (0.0, 5.0, 10.0)
PACKAGE_NAMES = ("Basic", "Deluxe", "Premium")
SIZE_NAMES = ("Small", "Medium", "Large")

MEMBER_DISCOUNT = 0.20
ENVIRONMENTAL_FEE = 1.0


def validate_order(order):
    """Unpack and sanity-check a six element order list."""
    if len(order) != 6:
        raise ValueError("an order needs exactly 6 fields")
