def parse_readings(raw):
    """Convert a sequence of six raw sensor values into a list of floats."""
    # The sensor bus may deliver strings, so every field is coerced explicitly.
    if len(raw) != 6:
        raise ValueError("expected exactly six readings, got %d" % len(raw))
    return [float(value) for value in raw]


def validate_readings(readings):
    """Reject readings that cannot come from a working sensor array."""
    humidity, ext_temp, int_temp, soil, sun, co2 = readings
    # Percentage-based channels are physically bounded to 0..100.
    for name, value in (("humidity", humidity), ("soil moisture", soil)):
        if not 0.0 <= value <= 100.0:
            raise ValueError("%s out of range: %r" % (name, value))
    # A negative sunlight index or CO2 concentration means a faulty probe.
    if sun < 0 or co2 < 0:
        raise ValueError("sunlight index and CO2 must be non-negative")
    if not -60.0 <= ext_temp <= 60.0:
        raise ValueError("external temperature implausible: %r" % ext_temp)
    if not -20.0 <= int_temp <= 60.0:
        raise ValueError("internal temperature implausible: %r" % int_temp)
    return readings


def energy_load(readings):
    """Return the integer energy load of the greenhouse climate system."""
    humidity, ext_temp, int_temp, soil, sun, co2 = validate_readings(parse_readings(readings))

    load = 10.0

    # Heating and cooling are mutually exclusive comfort-band corrections.
    if int_temp < 18:
        load += 30
    elif int_temp > 28:
        load += 40

    # Dehumidifiers only run once the air is close to saturation.
    if humidity > 80:
        load += 20

    # A sunlight index of exactly zero means the grow lights carry the photoperiod.
    if sun == 0:
        load += 25

    if co2 < 400:
        load += 15

    # Poor insulation inflates everything accumulated so far by 15%.
    if ext_temp < 5:
        load *= 1.15

    # The pumps are added after the insulation penalty, so they are not scaled.
    if soil < 30:
        load += 10

    return int(load)


def report(label, readings):
    """Format a single greenhouse's load as one human-readable line."""
    load = energy_load(readings)
    return "%-12s humidity=%3.0f%% in=%4.1fC out=%5.1fC -> %4d units" % (
        label, readings[0], readings[2], readings[1], load)


def main():
    sites = {
        "north-bay": [85, 2, 16, 40, 0, 350],
        "south-bay": [55, 12, 24, 65, 7, 620],
        "propagation": [92, -3, 30, 22, 0, 380],
    }
    # Sorting keeps the printed report stable between runs.
    for label in sorted(sites):
        print(report(label, sites[label]))

    total = sum(energy_load(values) for values in sites.values())
    print("%-12s %42d units" % ("TOTAL", total))


if __name__ == "__main__":
    main()

