def overweight_surcharge(weight_kg):
    # Weight tiers are exclusive: the heavier band replaces the lighter one.
    if weight_kg > 32:
        return 100
    if weight_kg > 23:
        return 50
    return 0


def linear_dimensions(length_cm, width_cm, height_cm):
    # Airlines measure oversize bags by the sum of the three sides.
    return length_cm + width_cm + height_cm


def oversize_fee(length_cm, width_cm, height_cm):
    # Anything above 158 cm of combined dimensions is charged as oversize.
    if linear_dimensions(length_cm, width_cm, height_cm) > 158:
        return 75
    return 0


def parse_request(raw):
    # The caller may hand over strings (e.g. from a CSV row), so normalise first.
    if len(raw) != 6:
        raise ValueError("expected 6 values: class, status, weight, length, width, height")
    values = [int(field) for field in raw]
    if any(value < 0 for value in values):
        raise ValueError("negative values are not valid for a baggage request")
    return values


def baggage_fee(data):
    ticket_class, flyer_status, weight, length, width, height = parse_request(data)

    # Standard checked bag fee before any waiver or surcharge.
    fee = 30

    # Premium cabins and higher loyalty tiers travel with the first bag free.
    if ticket_class >= 1 or flyer_status >= 2:
        fee = 0

    fee += overweight_surcharge(weight)
    fee += oversize_fee(length, width, height)

    # Entry-level frequent flyers keep a ten percent discount on all fees.
    if flyer_status == 1:
        fee *= 0.9

    # Bags beyond 45 kg cannot be carried at all; 999 flags the rejection.
    if weight > 45:
        fee = 999

    return int(round(fee))


def describe(data):
    ticket_class, flyer_status, weight, length, width, height = parse_request(data)
    fee = baggage_fee(data)
    girth = linear_dimensions(length, width, height)
    # A rejected bag is reported differently from a priced one.
    if fee == 999:
        return "class %d / tier %d: %d kg REJECTED (over 45 kg limit)" % (
            ticket_class, flyer_status, weight)
    return "class %d / tier %d: %d kg, %d cm linear -> $%d" % (
        ticket_class, flyer_status, weight, girth, fee)


def main():
    requests = [
        [0, 0, 25, 80, 50, 30],
        [1, 0, 20, 55, 40, 20],
        [0, 1, 35, 90, 45, 25],
        [2, 3, 33, 60, 40, 30],
        [0, 0, 48, 70, 50, 40],
    ]
    for request in requests:
        print(describe(request))


if __name__ == "__main__":
    main()

