import math


def validate_readings(readings):
    """Return the six sensor readings as floats, raising on malformed input."""
    if len(readings) != 6:
        raise ValueError("expected exactly 6 readings")
    crew, oxygen, co2, temperature, radiation, solar = readings
    # Crew count must be a whole, non-negative number of people.
    if crew < 0 or crew != int(crew):
        raise ValueError("crew count must be a non-negative integer")
    # Percentages cannot leave the 0-100 range.
    for name, value in (("oxygen", oxygen), ("carbon dioxide", co2)):
        if not 0 <= value <= 100:
            raise ValueError(f"{name} level out of range: {value}")
    if solar < 0:
        raise ValueError("solar panel output cannot be negative")
    return int(crew), float(oxygen), float(co2), float(temperature), float(radiation), float(solar)


def climate_power(temperature):
    """Power for heaters or coolers, which is what emergency mode halves."""
    if temperature < 18:
        return 20.0
    # Coolers draw more than heaters because the radiators run continuously.
    if temperature > 26:
        return 25.0
    return 0.0


def life_support_power(readings):
    crew, oxygen, co2, temperature, radiation, solar = validate_readings(readings)

    # Base load scales linearly with the number of people aboard.
    power = 10.0 * crew

    if oxygen < 20:
        power += 50.0
    if co2 > 1:
        power += 30.0

    climate = climate_power(temperature)
    power += climate

    if radiation > 5:
        power += 40.0

    # Emergency mode: the panels cannot carry the load, so climate control is cut in half.
    if power > solar:
        power -= climate / 2.0

    return math.ceil(power)


def allocation_report(readings):
    """Human-readable summary of one sensor sweep and its allocation."""
    crew, oxygen, co2, temperature, radiation, solar = validate_readings(readings)
    allocated = life_support_power(readings)
    mode = "EMERGENCY" if allocated > solar else "NOMINAL"
    return (
        f"crew={crew} O2={oxygen:.1f}% CO2={co2:.2f}% "
        f"temp={temperature:.1f}C rad={radiation:.1f} solar={solar:.0f}kW "
        f"-> {allocated} kW [{mode}]"
    )


def main():
    sweeps = [
        [4, 19, 0.5, 17, 6, 120],
        [6, 21, 1.4, 28, 2, 400],
        [12, 18, 2.1, 30, 7, 150],
    ]
    for sweep in sweeps:
        print(allocation_report(sweep))

    # Peak draw drives the sizing of the backup battery bank.
    peak = max(life_support_power(sweep) for sweep in sweeps)
    print(f"peak allocation across sweeps: {peak} kW")


if __name__ == "__main__":
    main()

