    for name in ("wait_time", "payload_weight", "shift_end_proximity"):
        if record[name] < 0:
            raise ValueError(f"reading '{name}' cannot be negative")
    return record


def truck_priority(readings):
    """Score a mining truck for its place in the crusher queue."""
    data = parse_truck_record(readings)

    # start from the payload: the more ore on board, the more the crusher wants it.
    score = data["payload_weight"]

    # high grade ore earns two points per percent above the fifty percent cut-off.
    if data["ore_grade"] > 50:
        score += 2 * (data["ore_grade"] - 50)

    # every minute already spent queueing adds a point, so nobody starves.
    score += data["wait_time"]

    # a nearly empty tank is an emergency: let the truck dump and go refuel.
    if data["fuel_remaining"] < 15:
        score += 50

    # worn tires mean the truck should be in the workshop, not at the head of the line.
    if data["tire_wear"] >= 3:
        score -= 20

    # clear the truck before the driver changeover at the end of the shift.
    if data["shift_end_proximity"] < 30:
        score += 40

    # cap the result so downstream fixed-range dispatch systems cannot overflow.
    return int(min(score, MAX_PRIORITY))


def rank_fleet(fleet):
    """Return (truck_id, score) pairs ordered from most to least urgent."""
    scored = [(truck_id, truck_priority(readings)) for truck_id, readings in fleet.items()]
    # ties are broken alphabetically by truck id to keep the report stable.
    return sorted(scored, key=lambda pair: (-pair[1], pair[0]))


def main():
    fleet = {
        "T-101": [65, 20, 10, 2, 150, 15],
        "T-102": [48, 5, 70, 3, 120, 90],
        "T-103": [80, 45, 55, 1, 200, 120],
        "T-104": [52, 60, 12, 4, 90, 25],
    }
    for truck_id, score in rank_fleet(fleet):
        print(f"{truck_id}: priority {score}")


if __name__ == "__main__":
    main()

