from typing import List, Tuple, Sequence

Interval = Tuple[float, float]
FAILURE = (None, 0, 0)

WORK_START = 8
WORK_END = 20


def normalize(intervals: Sequence[Interval]) -> List[Interval]:
    """Sort and merge one participant's intervals, dropping degenerate ones."""
    clean = []
    for start, end in intervals:
        # Intervals shorter than an hour can never host a full slot.
        if end - start >= 1:
            clean.append((float(start), float(end)))
    clean.sort()
    merged: List[Interval] = []
    for start, end in clean:
        if merged and start <= merged[-1][1]:
            # Overlapping or touching ranges collapse into the previous one.
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def available_hours(intervals: Sequence[Interval]) -> float:
    return sum(end - start for start, end in intervals)


def intersect(a: Sequence[Interval], b: Sequence[Interval]) -> List[Interval]:
    """Classic two-pointer walk over two sorted, merged interval lists."""
    out: List[Interval] = []
    i = j = 0
    while i < len(a) and j < len(b):
        low = max(a[i][0], b[j][0])
        high = min(a[i][1], b[j][1])
        if high - low >= 1:
            out.append((low, high))
        # Advance whichever interval finishes first.
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return out


def earliest_slot(people: Sequence[List[Interval]]):
    common = people[0]
    for other in people[1:]:
        common = intersect(common, other)
        if not common:
            return None
    low, high = common[0]
    # Round the window start up to a whole hour, then confirm it still fits.
    candidate = int(low) if float(low).is_integer() else int(low) + 1
    if candidate + 1 <= high:
        return candidate
    return None


def penalty_of(start: int) -> int:
    return int(max(0, WORK_START - start) + max(0, (start + 1) - WORK_END))


def fits(people: Sequence[List[Interval]], start: int) -> bool:
    return all(any(s <= start and start + 1 <= e for s, e in p) for p in people)


def schedule(availabilities, day_offset: int = 0):
    # Weekends are never schedulable, whatever the availabilities say.
    if day_offset % 7 >= 5:
        return FAILURE
    people = [normalize(p) for p in availabilities]
    while len(people) >= 3:
        start = earliest_slot(people)
        if start is not None:
            score = penalty_of(start)
            # A penalised slot may become clean one hour later.
            if score and fits(people, start + 1) and penalty_of(start + 1) == 0:
                start += 1
                score = 0
            return (start, len(people), score)
        # Drop the least available participant and retry with a smaller group.
        weakest = min(range(len(people)), key=lambda k: available_hours(people[k]))
        people.pop(weakest)
    return FAILURE


def main() -> None:
    team = [
        [(7, 12), (14, 18)],
        [(6, 11), (15, 21)],
        [(7.5, 10), (16, 19)],
        [(22, 23)],
    ]
    start, attendees, score = schedule(team, day_offset=2)
    if start is None:
        print("No viable slot")
    else:
        print(f"Slot {start:02d}:00-{start + 1:02d}:00, {attendees} attendees, penalty {score}")
    # A Saturday offset must be rejected outright.
    print(schedule(team, day_offset=5))


if __name__ == "__main__":
    main()

