MEATS = {"beef", "pork", "chicken", "lamb", "bacon", "turkey"}
DAIRY = {"milk", "cheese", "butter", "yogurt", "cream"}
NUTS = {"peanut", "almond", "walnut", "cashew", "pecan", "hazelnut"}
GREENS = {"spinach", "kale", "lettuce", "arugula", "chard", "broccoli"}
SPICY = {"chili", "jalapeno", "cayenne", "habanero", "wasabi", "harissa"}

NUT_WARNING = "WARNING: contains nuts"


def normalize(meal):
    # Ingredient names are compared case-insensitively, so fold them once here.
    return [str(item).strip().lower() for item in meal]


def has_meat_and_dairy(ingredients):
    # A meal is only rejected when both groups are present at the same time.
    return bool(set(ingredients) & MEATS) and bool(set(ingredients) & DAIRY)


def count_spicy(ingredients):
    return sum(1 for item in ingredients if item in SPICY)


def filter(meals):
    accepted = []
    rejected = 0

    for meal in meals:
        ingredients = normalize(meal)

        # Rule one: mixing meat with dairy disqualifies the meal outright.
        if has_meat_and_dairy(ingredients):
            rejected += 1
            continue

        # Rule two: nut-bearing meals keep their ingredients but gain a warning.
        if set(ingredients) & NUTS and NUT_WARNING not in ingredients:
            ingredients.append(NUT_WARNING)

        # Rule three: overly complex meals get their final ingredient trimmed.
        if len(ingredients) > 5:
            ingredients = ingredients[:-1]

        # Rule four: at least one standard green is mandatory.
        if not set(ingredients) & GREENS:
            rejected += 1
            continue

        # Rule five: more than two spicy items makes the meal too hot to serve.
        if count_spicy(ingredients) > 2:
            rejected += 1
            continue

        accepted.append(ingredients)

    # Richer meals are listed first, so sort by descending ingredient count.
    accepted.sort(key=len, reverse=True)
    return rejected, accepted


def report(rejected, accepted):
    lines = ["Rejected meals: {}".format(rejected),
             "Accepted meals: {}".format(len(accepted))]
    for index, meal in enumerate(accepted, start=1):
        lines.append("{}. ({} items) {}".format(index, len(meal), ", ".join(meal)))
    return "\n".join(lines)


def main():
    menu = [
        ["beef", "cheese", "kale"],
        ["spinach", "almond", "rice", "olive oil"],
        ["kale", "chili", "jalapeno", "cayenne", "tofu"],
        ["chicken", "broccoli", "garlic", "ginger", "rice", "sesame", "lemon"],
        ["pasta", "tomato", "basil"],
        ["arugula", "walnut", "pear"],
    ]

    rejected, accepted = filter(menu)
    print(report(rejected, accepted))


if __name__ == "__main__":
    main()

