ODD_PRIME = 7
MODULUS = 1000


def scramble(seed):
    """Multiply the seed by an odd prime and keep it inside three digits."""
    # A token only makes sense for whole, non-negative starting numbers.
    if not isinstance(seed, int) or isinstance(seed, bool):
        raise TypeError("seed must be an integer")
    if seed < 0:
        raise ValueError("seed must not be negative")
    return (seed * ODD_PRIME) % MODULUS


def reversed_digits(value):
    """Return the decimal digits of value in reverse order."""
    # Zero has no digits when stripped, so keep it as a single digit.
    if value == 0:
        return [0]
    digits = []
    while value > 0:
        digits.append(value % 10)
        value //= 10
    return digits


def adjust(digit):
    """Shift a single digit according to its parity."""
    if digit % 2 == 0:
        shifted = digit + 7
    else:
        shifted = digit - 3
    # Negative results are folded back into positive territory.
    return abs(shifted)


def collapse_adjacent(sequence):
    """Drop the second member of every pair of equal neighbours."""
    collapsed = []
    for number in sequence:
        # Only the previous survivor matters when hunting for duplicates.
        if collapsed and collapsed[-1] == number:
            continue
        collapsed.append(number)
    return collapsed


def generate(seed):
    """Build the security token derived from the given seed."""
    digits = reversed_digits(scramble(seed))
    modified = [adjust(digit) for digit in digits]
    # The running total of the modified digits closes the sequence.
    token = modified + [sum(modified)]
    token = collapse_adjacent(token)
    if len(token) > 1:
        token[0], token[-1] = token[-1], token[0]
    return token


def format_token(seed, token):
    """Render one seed and its token as a single report line."""
    body = "-".join(str(number) for number in token)
    return "seed {:>4} -> {}".format(seed, body)


def main():
    seeds = [0, 1, 13, 42, 143, 256, 999]
    for seed in seeds:
        print(format_token(seed, generate(seed)))
    # A rejected seed is reported instead of crashing the whole run.
    try:
        generate(-5)
    except ValueError as error:
        print("rejected -5:", error)


if __name__ == "__main__":
    main()

