from decimal import Decimal

MIN_AUDIBLE = 20.0
MAX_AUDIBLE = 20000.0
VOCAL_LOW = 80.0
VOCAL_HIGH = 255.0


def to_floats(frequencies):
    # Accept Decimal and string inputs so the caller can pass exact literals.
    values = []
    for item in frequencies:
        if isinstance(item, (Decimal, str)):
            values.append(float(item))
        else:
            values.append(float(item))
    return values


def filter_audible(values):
    # Anything outside the human hearing band is dropped entirely.
    return [v for v in values if MIN_AUDIBLE <= v <= MAX_AUDIBLE]


def damp_spikes(values):
    # A spike is judged against the already damped previous value, not the raw one.
    damped = []
    for value in values:
        if damped and value > 2 * damped[-1]:
            damped.append(value / 2)
        else:
            damped.append(value)
    return damped


def moving_average(values, window=3):
    # Windows are centred, and shrink at the two ends of the list.
    smoothed = []
    half = window // 2
    for index in range(len(values)):
        start = max(0, index - half)
        stop = min(len(values), index + half + 1)
        chunk = values[start:stop]
        smoothed.append(sum(chunk) / len(chunk))
    return smoothed


def replace_silence(values):
    # Exact zeros would trigger silence errors downstream, so lift them to one.
    return [1.0 if v == 0.0 else v for v in values]


def count_vocal(values):
    return sum(1 for v in values if VOCAL_LOW <= v <= VOCAL_HIGH)


def clean(frequencies):
    values = to_floats(frequencies)
    audible = filter_audible(values)
    damped = damp_spikes(audible)
    smoothed = replace_silence(moving_average(damped))
    # An empty result has no maximum, so report None instead of raising.
    peak = max(smoothed) if smoothed else None
    return smoothed, count_vocal(smoothed), peak


def format_report(smoothed, vocal, peak):
    body = ", ".join("{:.2f}".format(v) for v in smoothed)
    # Guard the formatting of the peak, which may be absent.
    peak_text = "n/a" if peak is None else "{:.2f}".format(peak)
    return "cleaned: [{}]\nvocal values: {}\npeak: {}".format(body, vocal, peak_text)


def main():
    samples = [5.0, 110.0, 250.0, 900.0, 120.5, 0.0, 30000.0, 180.0, 95.25, 19.9]
    smoothed, vocal, peak = clean(samples)
    print(format_report(smoothed, vocal, peak))


if __name__ == "__main__":
    main()

