DAYS_IN_SHORTEST_MONTH = 28
HIGH_RISK_THRESHOLD = 70
MONTHS_REQUIRED = 12


def _validate(history):
    """Return the history as a list of ints, rejecting malformed input."""
    # A full year of monthly counts is required for the comparison to be meaningful.
    if len(history) != MONTHS_REQUIRED:
        raise ValueError("history must contain exactly 12 monthly login counts")
    counts = []
    for month, value in enumerate(history, start=1):
        # Booleans are ints in Python, but they are never a valid login count.
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("month %d: login count must be an integer" % month)
        if value < 0:
            raise ValueError("month %d: login count cannot be negative" % month)
        counts.append(value)
    return counts


def _mean(values):
    return sum(values) / len(values)


def _has_zero_streak(counts, length=3):
    """True when `length` consecutive months contain no logins at all."""
    streak = 0
    for value in counts:
        streak = streak + 1 if value == 0 else 0
        if streak >= length:
            return True
    return False


def score(history):
    counts = _validate(history)
    first_half = _mean(counts[:6])
