def _validate(observation):
    # Each observation must carry exactly three numeric fields.
    if len(observation) != 3:
        raise ValueError("observation needs right ascension, declination and magnitude")
    ra, dec, mag = observation
    for value in (ra, dec, mag):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("coordinates and magnitude must be numeric")
    # Right ascension is measured in hours, declination in degrees.
    if not 0 <= ra < 24:
        raise ValueError("right ascension out of range: %r" % (ra,))
    if not -90 <= dec <= 90:
        raise ValueError("declination out of range: %r" % (dec,))
    return float(ra), float(dec), float(mag)


def classify(ra, dec, mag):
    # Anything this close to the celestial pole is a polar star whatever its brightness.
    if dec > 80:
        return "polar"
    # A negative magnitude is far too bright for a star at these distances.
    if mag < 0:
        return "planet"
    # The galactic window between 10h and 14h is rich in galaxies and clusters.
    if 10 <= ra <= 14:
        return "deep_sky"
    # Mid-brightness objects below the equator are southern survey targets.
    if dec < 0 and 2 <= mag <= 5:
        return "southern"
    return None


def identify(observations):
    counts = {"planet": 0, "polar": 0, "deep_sky": 0, "southern": 0}
    for observation in observations:
        ra, dec, mag = _validate(observation)
        # A reading of exactly zero hours is sensor noise, so drop it.
        if ra == 0:
            continue
        label = classify(ra, dec, mag)
        if label is not None:
            counts[label] += 1
    return [counts["planet"], counts["polar"], counts["deep_sky"], counts["southern"]]


def format_report(counts):
    names = ("Planets", "Polar stars", "Deep sky objects", "Southern targets")
    lines = []
    for name, value in zip(names, counts):
        lines.append("%-18s %3d" % (name + ":", value))
    # The trailing total makes the report easy to sanity check by eye.
    lines.append("%-18s %3d" % ("Classified:", sum(counts)))
    return "\n".join(lines)


def main():
    survey = [
        (5.24, -8.2, -1.46),
        (13.42, 55.1, 8.3),
        (2.53, 89.3, 2.02),
        (0.0, 41.0, 3.5),
        (11.05, -12.7, 4.1),
        (18.62, -26.4, 3.2),
        (22.14, 12.0, 6.8),
        (10.0, 85.5, -0.5),
    ]
    counts = identify(survey)
    print(format_report(counts))
    # Highlight how much of the run the noise filter and rules discarded.
    ignored = len(survey) - sum(counts)
    print("Unclassified or ignored: %d" % ignored)


if __name__ == "__main__":
    main()

