text_nat:
MOVES = {
    0: (1, -1, 0),
    1: (1, 0, -1),
    2: (0, 1, -1),
    3: (-1, 1, 0),
    4: (-1, 0, 1),
    5: (0, -1, 1),
}

BOUNDARY = 10


def parse_directions(raw):
    """Turn a string or iterable of values into a list of valid direction codes."""
    # Accept a compact textual form such as "0 1 5" as well as real iterables.
    if isinstance(raw, str):
        tokens = raw.replace(",", " ").split()
    else:
        tokens = list(raw)
    directions = []
    for token in tokens:
        step = int(token)
        # Only the six hex directions exist, anything else is a caller mistake.
        if step not in MOVES:
            raise ValueError("invalid direction: %r" % (token,))
        directions.append(step)
    return directions


def hex_distance(x, y, z):
    """Distance in hex steps is the largest absolute cubic coordinate."""
    return max(abs(x), abs(y), abs(z))


def walk(directions):
    """Run the path and report coordinates, distance, errors and the event log."""
    x = y = z = 0
    errors = 0
    log = []
    for step in parse_directions(directions):
        dx, dy, dz = MOVES[step]
        nx, ny, nz = x + dx, y + dy, z + dz
        # A move leaving the ten unit disc is discarded and counted as an error.
        if hex_distance(nx, ny, nz) > BOUNDARY:
            errors += 1
            continue
        x, y, z = nx, ny, nz
        # Passing back through the origin means the trail closed a loop.
        if x == 0 and y == 0 and z == 0:
            log.append("loop")
    return (x, y, z), hex_distance(x, y, z), errors, log


def navigate(directions):
    """Return the final cubic coordinates, the distance travelled out and errors."""
    coords, distance, errors, _log = walk(directions)
    return coords, distance, errors


def format_report(directions):
    """Build a human readable summary of a single robot run."""
    coords, distance, errors, log = walk(directions)
    lines = ["position: %d, %d, %d" % coords, "distance: %d" % distance]
    # Errors are only worth mentioning when at least one step was rejected.
    if errors:
        lines.append("out of bounds steps: %d" % errors)
    # The log holds one flag per return to the origin.
    if log:
        lines.append("loops closed: %d" % len(log))
    return "\n".join(lines)


def main():
    runs = [
        "0 0 0",
        [0, 3, 1, 4],
        [1] * 15,
        [2, 2, 2, 5, 5, 5, 0, 3],
    ]
    for run in runs:
        print(format_report(run))
        print("-" * 20)
    # A malformed path should fail loudly rather than move the robot.
    try:
        navigate([0, 7])
    except ValueError as exc:
        print("rejected:", exc)


if __name__ == "__main__":
    main()

