WARNING_FLAG = "GARBAGE_WARNING"

TEMPERATURE = 1
PRESSURE = 2
STATUS_FLAGS = 3

GARBAGE_LIMIT = 5


def _validate(stream):
    # The stream must be a real sequence of byte-sized integers.
    if not stream:
        raise ValueError("empty stream")
    for index, byte in enumerate(stream):
        if not isinstance(byte, int) or isinstance(byte, bool):
            raise ValueError("non-integer byte at position %d" % index)
        if not 0 <= byte <= 255:
            raise ValueError("byte out of range at position %d" % index)


def _to_int(data):
    # Big-endian accumulation keeps multi-byte temperature readings intact.
    value = 0
    for byte in data:
        value = (value << 8) | byte
    return value


def decode(stream):
    _validate(stream)
    declared_length = stream[0]
    payload = stream[1:1 + declared_length]
    # A truncated frame cannot be trusted, so refuse it outright.
    if len(payload) < declared_length:
        raise ValueError("payload shorter than declared length")
    if not payload:
        raise ValueError("payload carries no sensor type")

    sensor_type = payload[0]
    data = payload[1:]
    garbage_count = len(stream) - 1 - declared_length

    if sensor_type == TEMPERATURE:
        # The offset of fifty lets the sensor transmit negatives unsigned.
        value = _to_int(data) - 50
    elif sensor_type == PRESSURE:
        value = sum(data) * 10
    elif sensor_type == STATUS_FLAGS:
        value = [byte != 0 for byte in data]
    else:
        raise ValueError("unknown sensor type %d" % sensor_type)

    result = (value, sensor_type, garbage_count)
    # Excessive trailing bytes hint at a desynchronised link.
    if garbage_count > GARBAGE_LIMIT:
        result = result + (WARNING_FLAG,)
    return result


def format_report(result):
    value, sensor_type, garbage_count = result[0], result[1], result[2]
    names = {TEMPERATURE: "temperature", PRESSURE: "pressure", STATUS_FLAGS: "status"}
    if sensor_type == STATUS_FLAGS:
        # Boolean payloads read better as a compact flag string.
        shown = "".join("1" if flag else "0" for flag in value)
    else:
        shown = str(value)
    line = "%-11s value=%s garbage=%d" % (names[sensor_type], shown, garbage_count)
    if WARNING_FLAG in result[3:]:
        line += " [%s]" % WARNING_FLAG
    return line


def main():
    frames = [
        [2, 1, 70],
        [3, 2, 12, 40, 9, 9],
        [4, 3, 1, 0, 5],
        [2, 1, 20, 0, 0, 0, 0, 0, 0],
    ]
    for frame in frames:
        # Malformed frames are reported instead of killing the whole run.
        try:
            print(format_report(decode(frame)))
        except ValueError as error:
            print("frame %r rejected: %s" % (frame, error))


if __name__ == "__main__":
    main()

