import re

SEASONAL_WORDS = ("winter", "spring", "summer", "autumn", "fall")
BANNED_WORDS = ("damn", "bloody", "wretch", "filth")

WORD_RE = re.compile(r"[A-Za-z']+")


def words_of(line):
    """Return the alphabetic words of a line, lower-cased."""
    return [w.lower() for w in WORD_RE.findall(line)]


def last_letter(line):
    # Punctuation must be ignored so that "night." rhymes with "light"
    words = words_of(line)
    if not words:
        return None
    return words[-1][-1]


def contains_banned(lines):
    # A banned word only counts as a whole word, so "damned" is fine
    for line in lines:
        for word in words_of(line):
            if word in BANNED_WORDS:
                return True
    return False


def rhyme_points(lines):
    """Ten points for every neighbouring pair sharing a final letter."""
    points = 0
    for first, second in zip(lines, lines[1:]):
        a, b = last_letter(first), last_letter(second)
        # Empty lines have no final letter and cannot form a pair
        if a is not None and a == b:
            points += 10
    return points


def length_penalty(lines):
    counts = [len(words_of(line)) for line in lines]
    if not counts:
        return 0
    average = sum(counts) / len(counts)
    # Terse lines lose three points, bloated ones lose five
    if average < 5:
        return -3
    if average > 12:
        return -5
    return 0


def seasonal_points(lines):
    points = 0
    for line in lines:
        for word in words_of(line):
            if word in SEASONAL_WORDS:
                points += 1
    return points


def evaluate(lines):
    # Offensive language voids the whole submission immediately
    if contains_banned(lines):
        return 0
    score = 0
    if len(lines) == 14:
        score += 5
    score += rhyme_points(lines)
    score += length_penalty(lines)
    score += seasonal_points(lines)
    return int(score)


def report(title, lines):
    """Format a one-line summary of a poem's evaluation."""
    return "{:<18} {:>3} points ({} lines)".format(title, evaluate(lines), len(lines))


def main():
    quatrain = [
        "The winter wind will carry off the light",
        "and leave the frozen orchard bare and white",
        "until the spring returns to warm the stone",
        "and every quiet root is sung and grown",
    ]
    terse = ["Snow falls", "Rain calls", "Spring waits"]
    rude = ["A bloody mess of metaphor and rhyme", "that wastes the reader's patience and his time"]
    print(report("Quatrain", quatrain))
    print(report("Terse", terse))
    print(report("Rude", rude))


if __name__ == "__main__":
    main()

