EMPTY, TREE, BURNING, WATER = 0, 1, 2, 3

GLYPHS = {EMPTY: ".", TREE: "T", BURNING: "*", WATER: "~"}


def neighbors(grid, row, col):
    # Orthogonal neighbours only, clipped to the grid bounds.
    height, width = len(grid), len(grid[0])
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        r, c = row + dr, col + dc
        if 0 <= r < height and 0 <= c < width:
            yield grid[r][c]


def is_doused(grid, row, col):
    # A fire touching water is extinguished, so it never spreads.
    return WATER in neighbors(grid, row, col)


def has_live_fire(grid, row, col):
    height, width = len(grid), len(grid[0])
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        r, c = row + dr, col + dc
        if 0 <= r < height and 0 <= c < width and grid[r][c] == BURNING:
            # Only fires that are not already doused can ignite this cell.
            if not is_doused(grid, r, c):
                return True
    return False


def simulate(grid):
    if not grid or not grid[0]:
        raise ValueError("grid must contain at least one row and one column")
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("all rows must have the same length")

    new_grid = [[EMPTY] * width for _ in grid]
    burned = 0

    for row, cells in enumerate(grid):
        for col, cell in enumerate(cells):
            if cell == WATER:
                # Water is permanent terrain and never changes state.
                new_grid[row][col] = WATER
            elif cell == BURNING:
                new_grid[row][col] = EMPTY
            elif cell == TREE:
                if has_live_fire(grid, row, col):
                    new_grid[row][col] = BURNING
                    burned += 1
                else:
                    new_grid[row][col] = TREE
            else:
                # Deterministic "chance" of regrowth in a well-wooded spot.
                trees = sum(1 for n in neighbors(grid, row, col) if n == TREE)
                if trees >= 3 and (row * width + col) % 7 == 0:
                    new_grid[row][col] = TREE

    return new_grid, burned


def render(grid):
    return "\n".join("".join(GLYPHS[c] for c in row) for row in grid)


def main():
    grid = [
        [1, 1, 1, 0, 1, 1],
        [1, 2, 1, 1, 1, 0],
        [1, 1, 1, 3, 1, 1],
        [0, 1, 2, 1, 1, 1],
        [1, 1, 1, 1, 0, 1],
    ]
    print("step 0")
    print(render(grid))
    for step in range(1, 5):
        grid, burned = simulate(grid)
        # Report the freshly ignited trees after each time step.
        print("step %d (%d trees caught fire)" % (step, burned))
        print(render(grid))


if __name__ == "__main__":
    main()

