CLAMP_LIMIT = 50
FILLER_VALUE = 10


def validate_signal(signal):
    """Return the signal as a list of ints, rejecting anything else."""
    # A signal must be an ordered sequence, so reject sets and mappings.
    if not isinstance(signal, (list, tuple)):
        raise TypeError("signal must be a list or tuple of integers")
    checked = []
    for position, amplitude in enumerate(signal):
        # Booleans are ints in Python but are never valid amplitudes.
        if isinstance(amplitude, bool) or not isinstance(amplitude, int):
            raise TypeError("amplitude at index %d is not an integer" % position)
        checked.append(amplitude)
    return checked


def invert_every_third(amplitudes):
    """Flip the sign of the third, sixth, ninth ... amplitude."""
    for index in range(2, len(amplitudes), 3):
        amplitudes[index] = -amplitudes[index]
    return amplitudes


def clamp(amplitude):
    # Values outside the transmitter range saturate at the limit.
    if amplitude > CLAMP_LIMIT:
        return CLAMP_LIMIT
    if amplitude < -CLAMP_LIMIT:
        return -CLAMP_LIMIT
    return amplitude


def fill_zero_gaps(amplitudes):
    """Insert a keep-alive value between any two consecutive zeros."""
    filled = []
    for amplitude in amplitudes:
        # Two zeros in a row would silence the transmitter completely.
        if filled and filled[-1] == 0 and amplitude == 0:
            filled.append(FILLER_VALUE)
        filled.append(amplitude)
    return filled


def strip_trailing_zeros(amplitudes):
    end = len(amplitudes)
    # Shorten the transmission by dropping silence at the tail.
    while end > 0 and amplitudes[end - 1] == 0:
        end -= 1
    return amplitudes[:end]


def modulate(signal):
    amplitudes = validate_signal(signal)
    invert_every_third(amplitudes)
    amplitudes = [clamp(value) for value in amplitudes]
    amplitudes = fill_zero_gaps(amplitudes)
    # Energy accounts for the inserted keep-alive values as well.
    energy = sum(abs(value) for value in amplitudes)
    amplitudes = strip_trailing_zeros(amplitudes)
    return amplitudes, energy, len(amplitudes)


def format_report(signal):
    """Describe one modulation run in a single human-readable line."""
    modulated, energy, length = modulate(signal)
    return "%s -> %s | energy=%d | length=%d" % (signal, modulated, energy, length)


def main():
    samples = [
        [3, 70, 12, -80, 5, 4],
        [0, 0, 0, 7, 0, 0],
        [51, -51, 51, 0, 0],
        [],
    ]
    for sample in samples:
        print(format_report(sample))
    # A non-integer entry must be reported rather than silently modulated.
    try:
        modulate([1, 2, "3"])
    except TypeError as error:
        print("rejected:", error)


if __name__ == "__main__":
    main()

