def _validate(levels):
    """Return the readings as a list of ints, raising on unusable input."""
    if levels is None:
        raise ValueError("levels must be a list of integers, not None")
    readings = list(levels)
    # An empty reservoir log has no average, so it cannot be regulated.
    if not readings:
        raise ValueError("levels must contain at least one reading")
    for index, value in enumerate(readings):
        # Booleans are ints in Python, but they are not depth measurements.
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("reading %d is not an integer: %r" % (index, value))
        if value < 0:
            raise ValueError("reading %d is a negative depth: %d" % (index, value))
    return readings


def regulate(levels):
    """Inspect reservoir depths and return the control flags, count and average."""
    readings = _validate(levels)

    release_valve = False
    refill_pump = False
    alarm = False
    optimal_count = 0

    for position, depth in enumerate(readings):
        # Too much water: the primary release valve has to open.
        if depth > 80:
            release_valve = True
        # Too little water: the emergency refill pump has to run.
        if depth < 20:
            refill_pump = True
        if depth == 50:
            optimal_count += 1
        # A sudden loss of more than ten meters means a leak or a burst pipe.
        if position > 0 and readings[position - 1] - depth > 10:
            alarm = True

    negative_trend = readings[-1] < readings[0]
    average_depth = sum(readings) / len(readings)

    return (release_valve, refill_pump, alarm, negative_trend,
            optimal_count, average_depth)


def report(levels):
    """Build a human readable summary of the regulation decision."""
    release_valve, refill_pump, alarm, negative_trend, optimal_count, average = regulate(levels)

    lines = ["Readings: " + ", ".join(str(depth) for depth in levels)]
    lines.append("Average depth: %.2f m" % average)
    lines.append("Optimal readings (50 m): %d" % optimal_count)

    actions = []
    if release_valve:
        actions.append("primary release valve OPEN")
    if refill_pump:
        actions.append("emergency refill pump ON")
    if alarm:
        actions.append("ALARM: rapid drop detected")
    if negative_trend:
        actions.append("negative trend over the period")
    # With every flag clear the reservoir simply runs itself.
    if not actions:
        actions.append("no intervention required")
    lines.append("Status: " + "; ".join(actions))

    return "\n".join(lines)


def main():
    logs = [
        [45, 50, 50, 52, 48],
        [30, 85, 70, 55, 18],
        [60, 62, 61, 63, 64],
    ]
    for log in logs:
        print(report(log))
        # Keep the individual reservoir blocks visually separated.
        print("-" * 40)


if __name__ == "__main__":
    main()

