import random

TRACK_MINUTES = 3
FAST_TEMPO = 120
MIN_TEMPO = 60


def total_playtime(count):
    """Playtime in minutes, assuming a fixed length for every track."""
    return count * TRACK_MINUTES


def is_fast(track):
    # A tempo strictly above 120 counts as fast; everything else is slow.
    return track[2] > FAST_TEMPO


def drop_unplayable(tracks):
    # Tracks below 60 BPM are dropped before any grouping happens.
    return [t for t in tracks if t[2] >= MIN_TEMPO]


def group_by_artist(tracks):
    groups = {}
    for track in tracks:
        groups.setdefault(track[1], []).append(track)
    return groups


def spread_by_artist(groups):
    """Flatten artist groups round-robin so the same artist is rarely adjacent."""
    queues = [list(items) for items in groups.values()]
    # Artists with many tracks go first, otherwise they pile up at the end.
    queues.sort(key=len, reverse=True)
    spread = []
    while queues:
        for queue in queues:
            spread.append(queue.pop(0))
        queues = [q for q in queues if q]
    return spread


def pick_next(pool, last_artist):
    # Only a different artist is acceptable, so signal failure when none is left.
    for index, track in enumerate(pool):
        if track[1] != last_artist:
            return pool.pop(index)
    return None


def build_alternating(tracks):
    fast = [t for t in tracks if is_fast(t)]
    slow = [t for t in tracks if not is_fast(t)]
    order = []
    # Starting fast and ending slow means the playlist grows in fast/slow pairs.
    while fast and slow:
        lead = pick_next(fast, order[-1][1] if order else None)
        if lead is None:
            break
        follow = pick_next(slow, lead[1])
        if follow is None:
            fast.append(lead)
            break
        order.extend([lead, follow])
    return order


def find_genre_break(order, i, spare):
    run_genre = order[i][3]
    lead_class = is_fast(order[i])
    # The inserted pair keeps the fast/slow cadence and the artist rule intact.
    leads = [t for t in spare
             if is_fast(t) == lead_class and t[3] != run_genre and t[1] != order[i - 1][1]]
    for lead in random.sample(leads, len(leads)):
        follows = [t for t in spare
                   if t is not lead and is_fast(t) != lead_class
                   and t[1] != lead[1] and t[1] != order[i][1]]
        if follows:
            return [lead, random.choice(follows)]
    return None


def fix_genre_runs(order, pool):
    used = {id(t) for t in order}
    spare = [t for t in pool if id(t) not in used]
    i = 2
    while i < len(order):
        if order[i][3] == order[i - 1][3] == order[i - 2][3]:
            pair = find_genre_break(order, i, spare)
            if pair:
                order[i:i] = pair
                spare = [t for t in spare if t not in pair]
                i += len(pair)
        i += 1
    return order


def shuffle(tracks):
    playable = drop_unplayable(tracks)
    spread = spread_by_artist(group_by_artist(playable))
    order = fix_genre_runs(build_alternating(spread), playable)
    return [track[0] for track in order]


def report(tracks):
    titles = shuffle(tracks)
    lines = ["Playtime: %d minutes" % total_playtime(len(titles))]
    lines.extend("%2d. %s" % (n, title) for n, title in enumerate(titles, 1))
    return "\n".join(lines)


if __name__ == "__main__":
    library = [
        ("Track A", "Artist X", 130, "rock"),
        ("Track B", "Artist Y", 80, "pop"),
        ("Roadburn", "Artist X", 145, "rock"),
        ("Slow Lane", "Artist Z", 95, "rock"),
        ("Night Drive", "Artist Y", 132, "rock"),
        ("Quiet Hour", "Artist X", 70, "jazz"),
        ("Broken Clock", "Artist Z", 40, "ambient"),
    ]
    print(report(library))

