ROW_SIZE = 20


def _validate(groups):
    """Return the group sizes as a clean list of positive integers."""
    cleaned = []
    for value in groups:
        # Booleans are ints in Python, but they are not meaningful group sizes.
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("group sizes must be integers, got %r" % (value,))
        if value <= 0:
            raise ValueError("group sizes must be positive, got %d" % value)
        cleaned.append(value)
    return cleaned


def _fits_at(row, start, size):
    """Tell whether a group of size can occupy row[start:start+size]."""
    end = start + size
    if end > len(row):
        return False
    # The block itself has to be completely free.
    if any(row[i] for i in range(start, end)):
        return False
    # A seat on the left must stay empty as a buffer, unless we are at the wall.
    if start > 0 and row[start - 1] != 0:
        return False
    # Same rule applies on the right-hand side of the block.
    if end < len(row) and row[end] != 0:
        return False
    return True


def _find_block(row, size):
    """Return the leftmost valid start index for size, or None."""
    for start in range(len(row) - size + 1):
        if _fits_at(row, start, size):
            return start
    return None


def seat(groups):
    """Seat each group in the leftmost fitting block, counting rejections."""
    sizes = _validate(groups)
    row = [0] * ROW_SIZE
    rejected = 0
    for size in sizes:
        start = _find_block(row, size)
        # A group that finds no gap is turned away and the next one is tried.
        if start is None:
            rejected += 1
            continue
        for index in range(start, start + size):
            row[index] = size
    return row, rejected


def format_row(row):
    """Render the row as a compact seating map with dots for empty seats."""
    cells = []
    for seat_value in row:
        # Multi-digit groups would break the alignment, so pad every cell.
        cells.append("." if seat_value == 0 else str(seat_value))
    return " ".join(cell.rjust(2) for cell in cells)


def main():
    requests = [3, 5, 15]
    row, rejected = seat(requests)
    print("requests:", requests)
    print("row      :", format_row(row))
    print("occupied :", sum(1 for value in row if value != 0), "of", ROW_SIZE)
    # Report the outcome in plain language for the box office operator.
    if rejected:
        print("rejected :", rejected, "group(s) could not be seated")
    else:
        print("rejected : none, every group was seated")


if __name__ == "__main__":
    main()

