ACHIEVEMENT_NAMES = {
    1: "achievement one",
    2: "achievement two",
    3: "achievement three",
    4: "achievement four",
}

TRACKED_ACTIONS = ("enemies defeated", "coins collected", "levels completed")


def normalize(action):
    """Return a cleaned (name, value) pair for a single logged action."""
    name, value = action
    # Action names arrive from user input, so casing and spacing are unreliable.
    key = " ".join(str(name).lower().split())
    if key not in TRACKED_ACTIONS:
        raise ValueError("unknown action: {!r}".format(name))
    # Values must be numeric; a bad log entry should fail loudly rather than skew totals.
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("value for {!r} must be a number".format(key))
    return key, value


def unlock(actions):
    """Award achievements for a sequence of (action, value) tuples."""
    totals = {name: 0 for name in TRACKED_ACTIONS}
    logged = {name: False for name in TRACKED_ACTIONS}
    awarded = []

    def award(number):
        # Each achievement is granted at most once, in unlock order.
        if ACHIEVEMENT_NAMES[number] not in awarded:
            awarded.append(ACHIEVEMENT_NAMES[number])

    for action in actions:
        key, value = normalize(action)
        totals[key] += value
        logged[key] = True

        if totals["enemies defeated"] >= 100:
            award(1)
        if totals["coins collected"] >= 500:
            award(2)
        # A fast single level counts as a speedrun, regardless of the running total.
        if key == "levels completed" and value < 300:
            award(3)
        if all(logged.values()):
            award(4)

    return awarded


def format_report(label, actions):
    """Build a one-line summary of the achievements a log unlocks."""
    earned = unlock(actions)
    # An empty result still deserves a readable line in the report.
    detail = ", ".join(earned) if earned else "none"
    return "{}: {}".format(label, detail)


def main():
    logs = [
        ("rich run", [("coins collected", 500)]),
        ("speedrun", [("Levels Completed", 240), ("levels completed", 410)]),
        ("grinder", [("enemies defeated", 60), ("enemies defeated", 45),
                     ("coins collected", 120), ("levels completed", 900)]),
        ("quiet run", [("coins collected", 12)]),
    ]
    for label, actions in logs:
        print(format_report(label, actions))

    # A malformed entry is reported instead of silently corrupting the totals.
    try:
        unlock([("bosses defeated", 3)])
    except ValueError as err:
        print("rejected: {}".format(err))


if __name__ == "__main__":
    main()

