import re
import sys

# Characters we keep when building a canonical form: letters and spaces only.
_ALLOWED = re.compile(r"[^a-z ]")


def canonicalize(name):
    """Return the comparison key for a raw name string."""
    lowered = name.lower().strip()
    # Special characters are dropped rather than replaced, so "O'Brien" -> "obrien".
    letters_only = _ALLOWED.sub("", lowered)
    # Collapse runs of whitespace that the stripping above left inside the name.
    return " ".join(letters_only.split())


def positional_matches(left, right):
    """Count characters that agree at the same index in both strings."""
    limit = min(len(left), len(right))
    matches = 0
    for index in range(limit):
        if left[index] == right[index]:
            matches += 1
    return matches


def is_duplicate(candidate, existing):
    """True when candidate is close enough to an already accepted canonical name."""
    # A large length gap means the names cannot describe the same person.
    if abs(len(candidate) - len(existing)) > 3:
        return False
    longer = max(len(candidate), len(existing))
    # Two empty canonical names collapse to the same thing.
    if longer == 0:
        return True
    return positional_matches(candidate, existing) > 0.8 * longer


def deduplicate(records):
    """Return the original names whose canonical forms are mutually distinct."""
    unique = []
    canonical_seen = []
    for record in records:
        key = canonicalize(record)
        duplicate = False
        for seen in canonical_seen:
            if is_duplicate(key, seen):
                duplicate = True
                break
        # Only the first spelling of a name survives; later variants are discarded.
        if not duplicate:
            canonical_seen.append(key)
            unique.append(record)
    return unique


def format_report(records, unique):
    """Build a human readable summary of the deduplication run."""
    lines = ["Input records: {0}".format(len(records)),
             "Unique records: {0}".format(len(unique))]
    for name in unique:
        lines.append("  {0}  ->  {1}".format(name, canonicalize(name)))
    removed = len(records) - len(unique)
    # Mention the discarded count only when something was actually dropped.
    if removed:
        lines.append("Discarded {0} duplicate(s)".format(removed))
    return "\n".join(lines)


def main(argv):
    # Names may be supplied on the command line; otherwise use a small demo list.
    if len(argv) > 1:
        records = argv[1:]
    else:
        records = ["John Doe", "john doe", "  JOHN   DOE  ", "Jane-Doe!",
                   "Jane Doe", "Robert Roe"]
    print(format_report(records, deduplicate(records)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

