ASKING_START = 1000
MINIMUM = 800
STEP = 50
WALK_AWAY = 500


def parse_offers(text):
    """Turn a comma separated string of prices into a list of integers."""
    items = [chunk.strip() for chunk in text.split(",") if chunk.strip()]
    offers = []
    for item in items:
        # Reject anything that is not a plain whole number of currency units.
        if not item.lstrip("+-").isdigit():
            raise ValueError("offer %r is not an integer" % item)
        value = int(item)
        # Negative prices are meaningless in a negotiation.
        if value < 0:
            raise ValueError("offer %d is negative" % value)
        offers.append(value)
    return offers


def negotiate(offers):
    """Return the agreed price for a sequence of buyer offers, or zero."""
    asking = ASKING_START
    for index, offer in enumerate(offers):
        if index == 0:
            # A first offer above the minimum is snapped up at once.
            if offer > MINIMUM:
                return offer
        else:
            # Each new round costs the seller another fifty off the asking price.
            asking = max(MINIMUM, asking - STEP)
        # Anything under five hundred insults the seller and ends the talks.
        if offer < WALK_AWAY:
            return 0
        if abs(asking - offer) <= STEP:
            # Close enough to split the difference, rounded down to an integer.
            return (asking + offer) // 2
    return 0


def describe(offers, price):
    """Build a one line summary of how a negotiation turned out."""
    sequence = " -> ".join(str(offer) for offer in offers) or "(no offers)"
    if price == 0:
        outcome = "no deal"
    else:
        outcome = "sold for %d" % price
    return "%s : %s" % (sequence, outcome)


def report(raw_sequences):
    """Parse each raw offer sequence, negotiate it and return the summaries."""
    lines = []
    for raw in raw_sequences:
        try:
            offers = parse_offers(raw)
        except ValueError as exc:
            # Malformed input is reported instead of aborting the whole run.
            lines.append("%s : invalid (%s)" % (raw, exc))
            continue
        lines.append(describe(offers, negotiate(offers)))
    return lines


def main():
    sequences = [
        "900",
        "700, 750, 800",
        "600, 620, 400",
        "750, 820",
        "300",
        "650, 7x0",
    ]
    for line in report(sequences):
        print(line)


if __name__ == "__main__":
    main()

