RARITY_THRESHOLD = 50


def _validate(pieces):
    """Return the pieces as a list of 4-tuples, raising on malformed input."""
    validated = []
    for entry in pieces:
        if len(entry) != 4:
            raise ValueError(f"piece record must have 4 fields, got {len(entry)}: {entry!r}")
        index, rarity, size, downloaded = entry
        # Indices address positions in the torrent, so they must be non-negative integers.
        if not isinstance(index, int) or index < 0:
            raise ValueError(f"invalid piece index: {index!r}")
        if rarity < 0:
            raise ValueError(f"rarity score cannot be negative: {rarity!r}")
        if size <= 0:
            raise ValueError(f"piece size must be positive: {size!r}")
        validated.append((index, rarity, size, bool(downloaded)))
    return validated


def _pending(pieces):
    """Drop everything we already hold on disk."""
    return [p for p in pieces if not p[3]]


def select(pieces):
    records = _validate(pieces)
    candidates = _pending(records)
    # Nothing left to ask a peer for.
    if not candidates:
        return -1

    # Rarest-first: lowest rarity wins, then smaller size, then lower index.
    rarest = min(candidates, key=lambda p: (p[1], p[2], p[0]))

    if rarest[1] > RARITY_THRESHOLD:
        # Every remaining piece is widely available, so optimise for finishing fast.
        smallest = min(candidates, key=lambda p: (p[2], p[0]))
        return smallest[0]

    return rarest[0]


def describe(pieces):
    """Human readable one-line summary of the scheduler's decision."""
    chosen = select(pieces)
    if chosen == -1:
        return "no pieces pending: download complete"

    record = next(p for p in _validate(pieces) if p[0] == chosen)
    rarest = min(_pending(_validate(pieces)), key=lambda p: (p[1], p[2], p[0]))
    # The strategy label depends on whether the rarest piece was still rare enough.
    strategy = "smallest-first" if rarest[1] > RARITY_THRESHOLD else "rarest-first"
    return (f"piece {record[0]} via {strategy} "
            f"(rarity={record[1]}, size={record[2]})")


def main():
    swarms = {
        "mixed": [(0, 80, 900, False), (1, 10, 500, False), (2, 10, 400, True)],
        "all common": [(3, 70, 2048, False), (4, 90, 128, False), (5, 55, 700, False)],
        "tie broken by size": [(6, 12, 300, False), (7, 12, 200, False)],
        "finished": [(8, 5, 100, True), (9, 40, 100, True)],
    }
    for name, pieces in swarms.items():
        # Report each swarm so the chosen strategy is visible side by side.
        print(f"{name:>20}: {describe(pieces)}")


if __name__ == "__main__":
    main()

