FICTION_DISCOUNT = 0.10
EDUCATIONAL_DISCOUNT = 0.20
EDUCATIONAL_MIN_QUANTITY = 3
BULK_DISCOUNT = 0.05
BULK_QUANTITY_THRESHOLD = 10
FREE_SHIPPING_THRESHOLD = 50.0
FLAT_SHIPPING = 5.0


def line_discount(category, quantity):
    """Return the fractional discount that applies to a single cart line."""
    normalised = category.strip().lower()
    # Fiction is always reduced, regardless of how many copies are bought.
    if normalised == "fiction":
        return FICTION_DISCOUNT
    # Educational books only qualify once the customer buys a small bundle.
    if normalised == "educational" and quantity >= EDUCATIONAL_MIN_QUANTITY:
        return EDUCATIONAL_DISCOUNT
    return 0.0


def line_cost(title, category, unit_price, quantity):
    """Return the discounted cost of one cart line after validating it."""
    # Negative money or counts would silently corrupt the cart total.
    if unit_price < 0 or quantity < 0:
        raise ValueError("invalid line for %r: price and quantity must be >= 0" % title)
    base = unit_price * quantity
    return base * (1.0 - line_discount(category, quantity))


def price(books):
    """Return (final_total, shipping) for a cart of (title, category, price, qty)."""
    subtotal = 0.0
    total_quantity = 0
    for title, category, unit_price, quantity in books:
        subtotal += line_cost(title, category, unit_price, quantity)
        total_quantity += quantity

    # Large carts earn an extra cut, applied to the whole discounted subtotal.
    if total_quantity > BULK_QUANTITY_THRESHOLD:
        subtotal *= 1.0 - BULK_DISCOUNT

    # Shipping is judged on the cart value only, never on the parcel size.
    if subtotal > FREE_SHIPPING_THRESHOLD:
        shipping = 0.0
    else:
        shipping = FLAT_SHIPPING

    return round(subtotal + shipping, 2), round(shipping, 2)


def receipt(books):
    """Build a human readable breakdown of the cart and its charges."""
    lines = []
    for title, category, unit_price, quantity in books:
        cost = line_cost(title, category, unit_price, quantity)
        saved = unit_price * quantity - cost
        row = "%-28s %2d x %6.2f = %7.2f" % (title, quantity, unit_price, cost)
        # Only mention savings when a discount actually changed the line.
        if saved > 0:
            row += "  (saved %.2f)" % saved
        lines.append(row)

    total, shipping = price(books)
    # The free-shipping case deserves an explicit note on the receipt.
    if shipping == 0.0:
        lines.append("%-28s %22s" % ("Shipping", "FREE"))
    else:
        lines.append("%-28s %22.2f" % ("Shipping", shipping))
    lines.append("%-28s %22.2f" % ("Total", total))
    return "\n".join(lines)


def main():
    cart = [
        ("The Long Walk", "fiction", 10.00, 1),
        ("Algebra Basics", "educational", 12.50, 4),
        ("Kitchen Notes", "cookery", 8.75, 2),
    ]
    print(receipt(cart))
