def validate_inputs(weight, style):
    # Weight must be numeric and positive for any of the formulas to make sense.
    if not isinstance(weight, (int, float)) or isinstance(weight, bool):
        raise TypeError("weight must be a number in kilograms")
    if weight <= 0:
        raise ValueError("weight must be greater than zero")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    # Styles are compared case-insensitively, so normalise once here.
    return float(weight), style.strip().lower()


def tune(weight, style):
    weight, style = validate_inputs(weight, style)

    air_pressure = weight * 0.8
    rebound = 5
    compression = 3

    # Riding style shifts all three settings in opposite directions.
    if style == "aggressive":
        air_pressure += 15
        rebound += 2
        compression += 1
    elif style == "casual":
        air_pressure -= 5
        compression -= 1

    # Heavier riders need extra rebound damping, one click per full 10 kg over 80.
    if weight > 80:
        rebound += int((weight - 80) // 10)
    elif weight < 60:
        rebound -= 1

    # The shock body cannot be safely charged beyond 120 psi.
    air_pressure = min(air_pressure, 120)
    # Rebound adjusters bottom out at zero clicks.
    rebound = max(rebound, 0)

    return [air_pressure, rebound, compression]


def format_setup(weight, style, setup):
    air_pressure, rebound, compression = setup
    # Pressure is reported to one decimal since 0.8 * weight is rarely whole.
    return (
        f"{weight:g} kg / {style}: "
        f"{air_pressure:.1f} psi, "
        f"{rebound} rebound clicks, "
        f"{compression} compression clicks"
    )


def build_report(riders):
    lines = []
    for weight, style in riders:
        setup = tune(weight, style)
        lines.append(format_setup(weight, style, setup))
    return "\n".join(lines)


def main():
    riders = [
        (55, "casual"),
        (72, "trail"),
        (95, "aggressive"),
        (140, "aggressive"),
    ]
    print(build_report(riders))

    # A single setup is also useful on its own, e.g. for a shop ticket.
    air_pressure, rebound, compression = tune(84, "casual")
    print(f"Ticket: {air_pressure:.1f} psi | rebound {rebound} | compression {compression}")


if __name__ == "__main__":
    main()

