def base_total(elements):
    """Return the summed base value, with a 10% bonus on the final element."""
    if not elements:
        return 0.0
    # The closing element is rewarded for being attempted late in the program.
    total = sum(elements[:-1]) + elements[-1] * 1.1
    return total


def fall_deduction(falls):
    """Return the total penalty in points for a given number of falls."""
    if falls <= 0:
        return 0.0
    # The first two falls cost a single point each, the rest cost double.
    counted = min(falls, 2)
    penalty = float(counted)
    if falls > 2:
        penalty += 2.0 * (falls - 2)
    return penalty


def score(elements, falls):
    """Calculate a skater's final mark from element base values and falls."""
    if falls < 0:
        raise ValueError("falls cannot be negative")
    # Negative base values are not valid technical scores.
    for value in elements:
        if value < 0:
            raise ValueError("element base values must be non-negative")

    total = base_total(elements)

    # A demanding program earns a flat presentation bonus.
    if total > 40:
        total += 3.0

    total -= fall_deduction(falls)

    # A clean skate without a single fall earns the flawless execution bonus.
    if falls == 0:
        total += 2.0

    # Marks are never allowed to drop below zero.
    if total < 0:
        total = 0.0

    return round(total, 2)


def format_row(name, elements, falls):
    """Build a single line of the results table for one skater."""
    final = score(elements, falls)
    # Show the raw technical content next to the awarded mark.
    raw = round(base_total(elements), 2)
    return "{:<12}{:>8.2f}{:>7d}{:>10.2f}".format(name, raw, falls, final)


def report(entries):
    """Return a ranked results table for a list of (name, elements, falls)."""
    # Ranking is by final score, highest first, with ties broken alphabetically.
    ordered = sorted(entries, key=lambda e: (-score(e[1], e[2]), e[0]))
    header = "{:<12}{:>8}{:>7}{:>10}".format("Skater", "Base", "Falls", "Score")
    lines = [header, "-" * len(header)]
    for name, elements, falls in ordered:
        lines.append(format_row(name, elements, falls))
    return "\n".join(lines)


def main():
    entries = [
        ("Kimura", [10.5, 9.8, 8.4, 7.2, 6.9], 0),
        ("Novak", [11.0, 10.2, 9.5, 8.8, 7.4], 3),
        ("Ellis", [6.0, 5.5, 4.8, 4.1], 1),
        ("Rossi", [3.2, 2.8, 2.5], 4),
    ]
    print(report(entries))


if __name__ == "__main__":
    main()

