import math

# Base brewing parameters shared by every tea before any adjustment.
BASE_TEMPERATURE = 80
BASE_TIME = 120

# Per-variety adjustments: (temperature delta, time delta) applied to the base.
RELATIVE_ADJUSTMENTS = {
    "black": (15, 60),
    "green": (-10, -30),
}


def normalise_tea(tea):
    """Return the canonical variety name for a user-supplied tea string."""
    if not isinstance(tea, str):
        raise TypeError("tea must be a string")
    # Users type things like " Green Tea ", so strip and lower-case first.
    cleaned = tea.strip().lower()
    if cleaned.endswith(" tea"):
        cleaned = cleaned[:-4].strip()
    if not cleaned:
        raise ValueError("tea must not be empty")
    return cleaned


def check_weight(weight):
    """Validate the leaf weight and return it as a float number of grams."""
    if isinstance(weight, bool) or not isinstance(weight, (int, float)):
        raise TypeError("weight must be a number of grams")
    if math.isnan(weight) or weight <= 0:
        raise ValueError("weight must be a positive number of grams")
    return float(weight)


def steep(tea, weight):
    """Return (temperature in C, steep time in seconds) for a cup of tea."""
    variety = normalise_tea(tea)
    grams = check_weight(weight)

    temperature = BASE_TEMPERATURE
    seconds = BASE_TIME

    if variety == "herbal":
        # Herbal infusions need a full boil and twice the base steep.
        temperature = 100
        seconds = BASE_TIME * 2
    elif variety in RELATIVE_ADJUSTMENTS:
        temp_delta, time_delta = RELATIVE_ADJUSTMENTS[variety]
        temperature += temp_delta
        seconds += time_delta

    if grams > 5:
        # Every gram past the fifth adds half a minute, fractions included.
        seconds += 30 * (grams - 5)
    elif grams < 3:
        seconds -= 15

    return int(temperature), int(round(seconds))


def describe(tea, weight):
    """Build a one-line human-readable brewing instruction."""
    temperature, seconds = steep(tea, weight)
    minutes, rest = divmod(seconds, 60)
    # Show a bare seconds count for short brews, m:ss otherwise.
    if minutes:
        clock = "{0}:{1:02d}".format(minutes, rest)
    else:
        clock = "{0}s".format(rest)
    return "{0} ({1:g} g): {2} C for {3}".format(tea.strip(), weight, temperature, clock)


def main():
    orders = [("black", 4), ("Green Tea", 7.5), ("herbal", 5), ("oolong", 2.5)]
    for tea, weight in orders:
        print(describe(tea, weight))


if __name__ == "__main__":
    main()

