SIDES = ("left", "right")


def parse_action(action):
    """Split a raw event string into (side, kind), where side is None for 'double touch'."""
    if not isinstance(action, str):
        raise TypeError("each action must be a string, got %r" % (action,))
    tokens = action.strip().lower().split()
    # Normalise the double touch, which belongs to neither fencer.
    if tokens == ["double", "touch"]:
        return None, "double touch"
    if len(tokens) != 2:
        raise ValueError("unrecognised action: %r" % (action,))
    side, kind = tokens
    if side not in SIDES:
        raise ValueError("unknown side in action: %r" % (action,))
    if kind not in ("attack", "parry", "touch"):
        raise ValueError("unknown event in action: %r" % (action,))
    return side, kind


def opponent(side):
    # The two fencers are always each other's opponent.
    return "right" if side == "left" else "left"


def referee(actions):
    """Score a fencing match from a sequence of event strings."""
    scores = {"left": 0, "right": 0}
    right_of_way = None

    for action in actions:
        side, kind = parse_action(action)

        if kind == "attack":
            # An attack into the opponent's priority cancels priority entirely.
            if right_of_way == opponent(side):
                right_of_way = None
            else:
                right_of_way = side
        elif kind == "parry":
            # Parrying takes priority away from the attacker.
            right_of_way = side
        elif kind == "touch":
            # Only a touch made with priority counts.
            if right_of_way == side:
                scores[side] += 1
        else:
            # Simultaneous touches are awarded to whoever holds priority.
            if right_of_way is not None:
                scores[right_of_way] += 1

    return scores["left"], scores["right"]


def format_result(left, right):
    """Render a final score as a short human-readable verdict."""
    if left > right:
        winner = "left wins"
    elif right > left:
        winner = "right wins"
    else:
        # Equal scores mean nobody takes the bout.
        winner = "draw"
    return "left %d - right %d (%s)" % (left, right, winner)


def main():
    bouts = [
        ["left attack", "left touch", "right attack", "right touch"],
        ["left attack", "right parry", "double touch", "left touch"],
        ["left attack", "right attack", "double touch", "right touch"],
        ["right attack", "left touch", "left attack", "left touch"],
    ]
    for number, bout in enumerate(bouts, start=1):
        left, right = referee(bout)
        # Report each bout with its sequence number for readability.
        print("Bout %d: %s" % (number, format_result(left, right)))


if __name__ == "__main__":
    main()

