    # Wear labels arrive from catalogue entries in mixed case with stray spaces.
    if not isinstance(wear, str):
        raise TypeError("wear must be a string condition")
    cleaned = wear.strip().lower()
    if cleaned not in ("none", "light", "heavy"):
        raise ValueError("unknown wear condition: {!r}".format(wear))
    return cleaned


def check_scratches(scratches):
    # Booleans are instances of int, so reject them explicitly.
    if isinstance(scratches, bool) or not isinstance(scratches, int):
        raise TypeError("scratches must be an integer count")
    if scratches < 0:
        raise ValueError("scratches cannot be negative")
    return scratches


def score(scratches, wear):
    scratches = check_scratches(scratches)
    wear = normalize_wear(wear)

    # A mint album starts at the full 100 points.
    points = 100
    points -= 5 * scratches

    # Heavily scratched sides pick up audible surface noise.
    if scratches > 3:
        points -= 10

    if wear == "light":
        points -= 8
    elif wear == "heavy":
        points -= 20
    elif scratches == 0:
        # No wear and no scratches earns the pristine bonus.
        points += 5

    return points


def grade(scratches, wear):
    points = score(scratches, wear)

    # The bands are checked from the top down so each range stays exclusive.
    if points > 90:
        return "mint"
    if points >= 71:
        return "good"
    if points >= 50:
        return "fair"
    return "poor"


def describe(title, scratches, wear):
    # Report the numeric score alongside the grade so appraisals are auditable.
    points = score(scratches, wear)
    label = grade(scratches, wear)
    return "{:<28} {:>4} pts  {}".format(title, points, label)


def main():
    inventory = [
        ("Kind of Blue", 0, "none"),
        ("Rumours", 2, "light"),
        ("Abbey Road", 4, "none"),
        ("Bitches Brew", 5, "heavy"),
        ("Thriller", 1, "None"),
    ]

    for title, scratches, wear in inventory:
        print(describe(title, scratches, wear))

    # Summarise how many copies fall into each grade.
    tally = {}
    for _title, scratches, wear in inventory:
        label = grade(scratches, wear)
        tally[label] = tally.get(label, 0) + 1

    print()
    for label in ("mint", "good", "fair", "poor"):
        if label in tally:
            print("{}: {}".format(label, tally[label]))


if __name__ == "__main__":
