text_nat:
BASE_INTERVAL_DAYS = 3
MIN_INTERVAL_DAYS = 1
MAX_INTERVAL_DAYS = 5

SLOW_DRINKERS = ("pine", "juniper")
FAST_DRINKERS = ("maple",)


def normalize_species(species):
    """Return a canonical lowercase species name."""
    # Species names arrive from user forms, so stray spaces and case are common.
    if not isinstance(species, str):
        raise TypeError("species must be a string")
    cleaned = species.strip().lower()
    if not cleaned:
        raise ValueError("species must not be empty")
    return cleaned


def check_readings(humidity, temp):
    """Validate the sensor readings used to adjust the interval."""
    # Humidity is a percentage, so anything outside 0..100 is a broken sensor.
    if not 0 <= humidity <= 100:
        raise ValueError("humidity must be a percentage between 0 and 100")
    # Ambient air temperatures outside this band mean the probe is faulty.
    if not -50 <= temp <= 60:
        raise ValueError("temp must be between -50 and 60 celsius")


def water(species, humidity, temp):
    """Return the watering interval in whole days for a miniature tree."""
    name = normalize_species(species)
    check_readings(humidity, temp)

    interval = BASE_INTERVAL_DAYS

    # Conifers hold moisture longer than broadleaf species.
    if name in SLOW_DRINKERS:
        interval += 2
    elif name in FAST_DRINKERS:
        interval -= 1

    # Dry air pulls water out of the shallow pot faster.
    if humidity < 40:
        interval -= 1

    if temp > 25:
        interval -= 1
    elif temp < 10:
        # Cold slows growth and evaporation, so watering can wait.
        interval += 1

    # Clamp the result into the allowed range before returning it.
    if interval < MIN_INTERVAL_DAYS:
        interval = MIN_INTERVAL_DAYS
    elif interval > MAX_INTERVAL_DAYS:
        interval = MAX_INTERVAL_DAYS

    return int(interval)


def describe(species, humidity, temp):
    """Build a one-line schedule note for a single tree."""
    days = water(species, humidity, temp)
    # English needs a plural only when more than one day passes.
    unit = "day" if days == 1 else "days"
    return "{}: water every {} {} ({}% RH, {}C)".format(
        normalize_species(species), days, unit, humidity, temp
    )


def main():
    collection = [
        ("Pine", 55, 18),
        ("juniper", 30, 28),
        ("Maple", 35, 30),
        ("ficus", 70, 5),
        ("elm", 45, 22),
    ]
    for species, humidity, temp in collection:
        print(describe(species, humidity, temp))

    # The soonest interval tells the owner when to next visit the bench.
    soonest = min(water(s, h, t) for s, h, t in collection)
    print("Next bench check in {} day(s)".format(soonest))


if __name__ == "__main__":
    main()

