SKIRT_EFFICIENCY = 0.6


def normalize_wetland(entry):
    """Turn a raw wetland entry into a (coordinate, viable) pair."""
    if isinstance(entry, (int, float)):
        # A bare number is a wetland that is assumed to be in good shape.
        return float(entry), True
    coordinate = float(entry["position"])
    dried_up = entry.get("dried_up", False)
    food = entry.get("food", 1.0)
    # A stopover is only usable if it still holds water and enough food.
    return coordinate, (not dried_up and food > 0)


def viable_sites(wetlands):
    """Collect the coordinates of all wetlands the flock can actually use."""
    usable = []
    for entry in wetlands:
        coordinate, viable = normalize_wetland(entry)
        if viable:
            usable.append(coordinate)
    # Birds meet the wetlands in geographic order, not in list order.
    return sorted(usable)


def furthest_within_reach(position, reach, sites):
    """Return the most distant usable wetland inside one day of flight."""
    best = None
    for coordinate in sites:
        if position < coordinate <= position + reach:
            best = coordinate
    return best


def skirt_obstacle(position, reach):
    """Fly around an impassable body of water, gaining less ground than usual."""
    progress = reach * SKIRT_EFFICIENCY
    # Rounding keeps the reported detour waypoints readable on a map.
    return round(position + progress, 1)


def route(flock, wetlands):
    """Pick the chain of stopovers a flock uses along its migration corridor."""
    if isinstance(flock, (int, float)):
        reach, position = float(flock), 0.0
    else:
        reach = float(flock["range"])
        position = float(flock.get("start", 0.0))
    if reach <= 0:
        raise ValueError("a flock must be able to fly some distance each day")

    sites = viable_sites(wetlands)
    stops = []
    while True:
        remaining = [c for c in sites if c > position]
        if not remaining:
            # Nothing usable lies ahead, so the migration leg is finished.
            break
        target = furthest_within_reach(position, reach, sites)
        if target is None:
            # Open water blocks the next wetland: detour instead of drowning.
            position = skirt_obstacle(position, reach)
        else:
            position = target
        stops.append(position)
    return stops


def describe(stops):
    """Format a route as a human readable flight plan."""
    if not stops:
        return "no stopovers needed"
    return " -> ".join(str(int(s) if float(s).is_integer() else s) for s in stops)


def main():
    plain = route(100, [50, 90, 150, 180])
    print("Simple corridor:", describe(plain))

    detailed = [
        {"position": 40, "food": 2.0},
        {"position": 95, "dried_up": True},
        {"position": 260, "food": 1.5},
        {"position": 330, "food": 0.0},
        {"position": 400, "food": 3.0},
    ]
    # The gap between 40 and 260 is wider than the daily range of 100.
    print("With obstacles:", describe(route({"range": 100}, detailed)))


if __name__ == "__main__":
    main()

