def reinforced_lanes(lane_count):
    """Return the indices of the wide, reinforced lanes built for heavy trucks."""
    # Roughly the last third of the plaza is poured as reinforced concrete.
    width = max(1, lane_count // 3)
    return list(range(lane_count - width, lane_count))


def standard_lanes(lane_count):
    """Return the indices of the ordinary lanes used by passenger cars."""
    reserved = set(reinforced_lanes(lane_count))
    return [index for index in range(lane_count) if index not in reserved]


def least_busy(counts, candidates):
    """Pick the candidate lane with the shortest queue, lowest index breaking ties."""
    return min(candidates, key=lambda index: (counts[index], index))


def open_lane(counts):
    """Find the lane an emergency vehicle can drive straight through."""
    for index, waiting in enumerate(counts):
        # A lane with nobody waiting lets the siren pass without slowing down.
        if waiting == 0:
            return index
    # Nothing is completely clear, so the shortest queue becomes the bypass.
    return least_busy(counts, range(len(counts)))


def assign(vehicles, lanes):
    """Route each arriving vehicle to a toll booth lane and return the lane numbers."""
    if not isinstance(lanes, int) or isinstance(lanes, bool):
        raise TypeError("lanes must be an integer count of toll booths")
    # Both a standard lane and a reinforced lane are needed to serve every class.
    if lanes < 2:
        raise ValueError("at least two lanes are required")

    counts = [0] * lanes
    truck_lanes = reinforced_lanes(lanes)
    car_lanes = standard_lanes(lanes)
    assignments = []

    for vehicle in vehicles:
        kind = str(vehicle).strip().lower()
        if kind in ("emergency", "ambulance", "fire"):
            # Emergency traffic bypasses the queue, so no waiting count grows.
            chosen = open_lane(counts)
        elif kind in ("truck", "heavy", "semi"):
            chosen = least_busy(counts, truck_lanes)
            counts[chosen] += 1
        elif kind in ("car", "van", "motorcycle"):
            chosen = least_busy(counts, car_lanes)
            counts[chosen] += 1
        else:
            raise ValueError("unknown vehicle classification: %r" % (vehicle,))
        assignments.append(chosen)

    return assignments


def format_report(vehicles, assignments):
    """Build human readable routing lines for the dispatch log."""
    lines = []
    for vehicle, lane in zip(vehicles, assignments):
        lines.append("%-10s -> lane %d" % (vehicle, lane))
    return "\n".join(lines)


def main():
    lanes = 3
    arrivals = ["car", "truck", "car", "emergency", "car", "truck"]
    assignments = assign(arrivals, lanes)
    print("reinforced lanes:", reinforced_lanes(lanes))
    print("standard lanes:  ", standard_lanes(lanes))
    print(format_report(arrivals, assignments))
    print("lane sequence:", assignments)


if __name__ == "__main__":
    main()

