import logging

logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
LOG = logging.getLogger("windfarm")

CUT_IN_SPEED = 3.0
RATED_SPEED = 12.0
CUT_OUT_SPEED = 25.0
HIGH_WIND_SPEED = 18.0
FEATHER_ANGLE = 90.0
FINE_PITCH = 2.0
START_PITCH = 8.0
VIBRATION_LIMIT = 4.5


def _wind_speed(wind):
    # Accept either a raw speed or a small meteorological record.
    if isinstance(wind, dict):
        speed = wind.get("speed")
    else:
        speed = wind
    if speed is None:
        raise ValueError("wind data carries no speed reading")
    speed = float(speed)
    # Negative anemometer output means a faulty sensor, not a valid breeze.
    if speed < 0.0:
        raise ValueError("wind speed cannot be negative")
    return speed


def _normalize(turbines):
    # A bare integer is treated as an array of that many identical machines.
    if isinstance(turbines, int):
        return [{"id": "T%d" % (i + 1), "vibration": 0.0} for i in range(turbines)]
    fleet = []
    for index, unit in enumerate(turbines):
        record = dict(unit)
        record.setdefault("id", "T%d" % (index + 1))
        record.setdefault("vibration", 0.0)
        fleet.append(record)
    return fleet


def optimal_angle(speed):
    # Below the rated point the blades stay fine to capture every watt available.
    if speed < RATED_SPEED:
        ramp = (speed - CUT_IN_SPEED) / (RATED_SPEED - CUT_IN_SPEED)
        return round(START_PITCH + ramp * (FINE_PITCH - START_PITCH), 1)
    # Above the rated point the blades bleed off surplus power to hold the generator steady.
