"""Reconstruct ancient skeletons by matching excavated fragments to a template."""

# The template maps every mountable position onto its anatomical region.
ANATOMY_TEMPLATE = {
    "skull": "cranial",
    "mandible": "cranial",
    "vertebrae": "axial",
    "ribs": "axial",
    "pelvis": "axial",
    "femur": "limb",
    "tibia": "limb",
    "humerus": "limb",
}

# Structural elements without which the mount cannot stand on its own.
VITAL_ELEMENTS = ("skull", "ribs", "pelvis", "femur")
LEG_BONES = ("femur", "tibia")


def catalogue(bones, anatomy):
    """Sort excavated fragments into the skeletal positions they can fill."""
    finds = {}
    for fragment in bones:
        # Field notes arrive either as bare bone names or as annotated records.
        if isinstance(fragment, str):
            name, quality, label = fragment.lower(), 0.0, fragment
        else:
            name = str(fragment.get("name", "")).lower()
            quality = float(fragment.get("preservation", 0.0))
            label = fragment.get("id", name)
        # Finds with no counterpart in the template are not skeletal material.
        if name not in anatomy:
            continue
        finds.setdefault(name, []).append((quality, label))
    return finds


def select_mounts(finds):
    """Keep the best preserved piece per position, relegating the rest."""
    mounted, spares = {}, []
    for position, candidates in finds.items():
        ranked = sorted(candidates, key=lambda item: item[0], reverse=True)
        mounted[position] = ranked[0]
        # Duplicates of an occupied position go to the alternate display case.
        spares.extend(label for _, label in ranked[1:])
    return mounted, spares


def measure_completeness(mounted, anatomy):
    """Return the mounted percentage and the vital elements still missing."""
    percentage = round(100.0 * len(mounted) / len(anatomy), 1)
    missing = [part for part in VITAL_ELEMENTS if part not in mounted]
    return percentage, missing


def needs_synthetic_cast(mounted):
    # A headless or legless mount has to be propped up with replica bone.
    if "skull" not in mounted:
        return True
    return not any(leg in mounted for leg in LEG_BONES)


def build_display(bones, anatomy=ANATOMY_TEMPLATE):
    """Assemble the full exhibit record for a set of excavated bones."""
    finds = catalogue(bones, anatomy)
    mounted, spares = select_mounts(finds)
    percentage, missing = measure_completeness(mounted, anatomy)
    return {
        "mounted": mounted,
        "spares": spares,
        "percentage": percentage,
        "missing": missing,
        "cast_required": needs_synthetic_cast(mounted),
    }


def assemble(bones, anatomy=ANATOMY_TEMPLATE):
    display = build_display(bones, anatomy)
    return display["percentage"], display["missing"]


def format_report(display, anatomy=ANATOMY_TEMPLATE):
    """Render a human readable summary of the reconstructed skeleton."""
    lines = ["Skeleton %.1f%% complete" % display["percentage"]]
    for position, (quality, label) in sorted(display["mounted"].items()):
        region = anatomy[position]
        lines.append("  %-10s %-8s %s (preservation %.2f)" % (position, region, label, quality))
    # Only mention the side cabinet when there is something to put in it.
    if display["spares"]:
        lines.append("  Alternate display: " + ", ".join(display["spares"]))
    if display["missing"]:
        lines.append("  Missing vital elements: " + ", ".join(display["missing"]))
    if display["cast_required"]:
        lines.append("  Synthetic cast replacements required")
    return "\n".join(lines)


def main():
    dig_site = [
        {"id": "F-1", "name": "femur", "preservation": 0.41},
        {"id": "F-2", "name": "Femur", "preservation": 0.82},
        {"id": "R-7", "name": "ribs", "preservation": 0.6},
        "coprolite",
    ]
    print(format_report(build_display(dig_site)))
    print(assemble(dig_site))


if __name__ == "__main__":
    main()

