"""Isolate genuine cosmic signals from terrestrial interference."""

import math

# Frequencies closer than this (in MHz) are treated as the same emitter.
MATCH_TOLERANCE = 0.5

# Residual power below this level is indistinguishable from background noise.
NOISE_FLOOR = 0.05


def _as_reading(entry, default_amplitude=1.0):
    """Normalise a catalogue or spectrum entry into a (frequency, amplitude) pair."""
    if isinstance(entry, (tuple, list)):
        frequency, amplitude = float(entry[0]), float(entry[1])
    else:
        # A bare number carries no power information, so assume unit amplitude.
        frequency, amplitude = float(entry), default_amplitude
    if frequency <= 0.0:
        raise ValueError("frequency must be positive, got %r" % (frequency,))
    return frequency, amplitude


def detect_spikes(readings, sigma=1.0):
    """Return the indices of readings whose amplitude stands out from the spectrum."""
    amplitudes = [amplitude for _, amplitude in readings]
    if not amplitudes:
        return []
    mean = sum(amplitudes) / len(amplitudes)
    variance = sum((a - mean) ** 2 for a in amplitudes) / len(amplitudes)
    deviation = math.sqrt(variance)
    # A perfectly flat spectrum has no relative peaks, so every transmission is prominent.
    if deviation == 0.0:
        return list(range(len(readings)))
    threshold = mean + sigma * deviation
    return [i for i, a in enumerate(amplitudes) if a >= threshold]


def match_source(frequency, catalogue, tolerance=MATCH_TOLERANCE):
    """Find the known terrestrial emitter nearest to a frequency, if any is close enough."""
    best = None
    best_gap = tolerance
    for source in catalogue:
        gap = abs(source[0] - frequency)
        # Keep the tightest match so overlapping satellite bands do not both claim the spike.
        if gap <= best_gap:
            best, best_gap = source, gap
    return best


def subtract_waveform(reading, source):
    """Remove the interferer's waveform from a reading, returning the residual."""
    frequency, amplitude = reading
    residual = amplitude - source[1]
    # Over-subtraction is physically meaningless, so clamp the leftover power at zero.
    return frequency, max(residual, 0.0)


def filter(signals, sources):
    """Return the spectrum with all identified terrestrial transmissions removed."""
    readings = [_as_reading(s) for s in signals]
    catalogue = [_as_reading(s) for s in sources]
    spikes = set(detect_spikes(readings))
    scalar_output = all(not isinstance(s, (tuple, list)) for s in signals)

    cleaned = []
    for index, reading in enumerate(readings):
        # Weak background samples are never bright enough to be a candidate transmission.
        if index in spikes:
            culprit = match_source(reading[0], catalogue)
            if culprit is not None:
                reading = subtract_waveform(reading, culprit)
                if reading[1] <= NOISE_FLOOR:
                    continue
        cleaned.append(reading)

    if scalar_output:
        return [frequency for frequency, _ in cleaned]
    return cleaned


def format_report(cleaned):
    """Describe the surviving candidates for the observing log."""
    if not cleaned:
        return "No unexplained signals remain."
    lines = []
    for entry in cleaned:
        frequency, amplitude = _as_reading(entry)
        lines.append("  %.3f MHz  (amplitude %.2f)" % (frequency, amplitude))
    return "Deep-space candidates:\n" + "\n".join(lines)


def main():
    spectrum = [1420.4, 2400.0]
    emitters = [2400.0]
    print(filter(spectrum, emitters))

    # A power-resolved scan keeps partially explained spikes as faint residuals.
    detailed = [(1420.4, 8.0), (1575.42, 6.0), (2400.0, 5.5), (900.0, 0.4)]
    known = [(1575.42, 6.0), (2400.0, 3.0)]
    print(format_report(filter(detailed, known)))


if __name__ == "__main__":
    main()

