from math import gcd
from collections import defaultdict


def _parse_throws(throws):
    """Turn a siteswap notation (string or iterable) into a list of heights."""
    if isinstance(throws, str):
        # Each non-space character of a compact siteswap is a single throw height.
        heights = [int(char, 36) for char in throws if not char.isspace()]
    else:
        heights = [int(height) for height in throws]
    if not heights:
        raise ValueError("the throw sequence must contain at least one throw")
    # A negative flight time has no physical meaning.
    if any(height < 0 for height in heights):
        raise ValueError("throw heights must be non-negative")
    return heights


def _cycle_length(period, hands):
    # The pattern repeats once the sequence and the hand rotation realign.
    # Their least common multiple is the number of beats that takes.
    return period * hands // gcd(period, hands)


def object_count(throws):
    """Number of objects implied by the sequence (the average throw height)."""
    heights = _parse_throws(throws)
    total = sum(heights)
    # Only an integral average can correspond to a whole number of objects.
    if total % len(heights):
        return None
    return total // len(heights)


def validate(throws, hands=2):
    """Check that the sequence is collision free; return (valid, collisions)."""
    heights = _parse_throws(throws)
    if hands < 1:
        raise ValueError("at least one hand is required to juggle")

    period = len(heights)
    cycle = _cycle_length(period, hands)
    landings = defaultdict(list)

    for beat in range(cycle):
        height = heights[beat % period]
        # A throw of height zero leaves the hand empty on this beat.
        # Nothing is airborne, so no landing has to be scheduled.
        if height == 0:
            continue
        landing_beat = (beat + height) % cycle
        landings[landing_beat].append(beat)

    # Two objects arriving on the same beat necessarily share a hand.
    # The receiving hand is the landing beat modulo the number of hands.
    collisions = sorted(beat for beat, sources in landings.items() if len(sources) > 1)
    return (not collisions, collisions)


def format_report(throws, hands=2):
    """Human readable summary of a single pattern."""
    valid, collisions = validate(throws, hands)
    label = throws if isinstance(throws, str) else "".join(str(h) for h in _parse_throws(throws))
    objects = object_count(throws)
    verdict = "valid" if valid else "invalid"
    parts = ["{0} on {1} hands: {2}".format(label, hands, verdict)]
    # The object count is undefined when the average height is fractional.
    if objects is not None:
        parts.append("{0} objects".format(objects))
    if collisions:
        parts.append("collisions at beats " + ", ".join(str(b) for b in collisions))
    return " | ".join(parts)


def main():
    patterns = [([3, 3, 3], 2), ("531", 2), ([4, 4, 1], 2),
                ([3, 4, 3], 2), ([5, 0, 5, 0], 2), ([4, 4, 4], 3)]
    for throws, hands in patterns:
        print(format_report(throws, hands))


if __name__ == "__main__":
    main()

