"""Cooling schedule calculations for annealing glass pieces."""

HARD_FAST_COOL = 30
SOFT_FAST_COOL = 20
THICK_THRESHOLD = 50
THICK_SLOW_COOL_FACTOR = 1.2

VALID_TYPES = ("soft", "hard")


def heating_time(thickness):
    # Heating scales with the square of the thickness.
    return thickness * thickness * 2


def soak_time(thickness):
    # Soaking holds a base half hour plus five minutes per millimetre.
    return 30 + 5 * thickness


def fast_cool_time(glass_type):
    # Hard glass needs a longer rapid drop than soft glass.
    if glass_type == "hard":
        return HARD_FAST_COOL
    return SOFT_FAST_COOL


def slow_cool_time(thickness):
    duration = thickness * 10
    # Thick pieces get twenty percent extra to avoid thermal shock cracking.
    if thickness > THICK_THRESHOLD:
        duration *= THICK_SLOW_COOL_FACTOR
    return duration


def validate_piece(piece):
    thickness, glass_type = piece
    # Thickness must be a real positive measurement in millimetres.
    if not isinstance(thickness, (int, float)) or thickness <= 0:
        raise ValueError("thickness must be a positive number of millimetres")
    # Only the two documented glass families have known schedules.
    if glass_type not in VALID_TYPES:
        raise ValueError("unknown glass type: %r" % (glass_type,))
    return thickness, glass_type


def cycle_time(piece):
    thickness, glass_type = validate_piece(piece)
    total = heating_time(thickness)
    total += soak_time(thickness)
    total += fast_cool_time(glass_type)
    total += slow_cool_time(thickness)
    return float(total)


def anneal(pieces):
    # An empty batch has no schedule to report.
    if not pieces:
        raise ValueError("at least one piece is required")
    times = [cycle_time(piece) for piece in pieces]
    return max(times), sum(times) / len(times)


def format_report(pieces):
    lines = []
    for thickness, glass_type in pieces:
        lines.append("%6.1f mm %-5s -> %9.1f min" % (
            thickness, glass_type, cycle_time((thickness, glass_type))))
    longest, average = anneal(pieces)
    lines.append("longest cycle: %.1f min" % longest)
    lines.append("average cycle: %.1f min" % average)
    return "\n".join(lines)


def main():
    batch = [(40, "soft"), (12, "hard"), (65, "hard"), (5, "soft")]
    print(format_report(batch))
    # A single-piece batch has identical maximum and average times.
    print(format_report([(40, "soft")]))


if __name__ == "__main__":
    main()

