MIN_CAPPED_PERCENT = 70
BASE_UNCAPPING_MINUTES = 2
BASE_SPINNING_MINUTES = 5
WAX_LOSS_FRACTION = 0.10
FILTER_MINUTES_PER_POUND = 3
SPINNING_BONUS = {"clover": 2, "wildflower": 4}


def is_ready(capped_percent):
    # Frames below the capping threshold are left on the hive to ripen further.
    return capped_percent >= MIN_CAPPED_PERCENT


def uncapping_time(capped_percent):
    # Every full ten percent above the threshold adds a minute of scraping.
    excess = capped_percent - MIN_CAPPED_PERCENT
    return BASE_UNCAPPING_MINUTES + excess / 10.0


def spinning_time(nectar_type):
    # Thicker nectars need a longer run in the extractor.
    return BASE_SPINNING_MINUTES + SPINNING_BONUS.get(nectar_type.strip().lower(), 0)


def honey_volume(capped_percent, raw_weight):
    gross = raw_weight * capped_percent / 100.0
    # A tenth of the gross yield stays behind as wax and comb debris.
    return gross * (1 - WAX_LOSS_FRACTION)


def filtering_time(volume):
    return FILTER_MINUTES_PER_POUND * volume


def extract(frames):
    total_volume = 0.0
    total_time = 0.0
    for capped_percent, raw_weight, nectar_type in frames:
        if not is_ready(capped_percent):
            continue
        volume = honey_volume(capped_percent, raw_weight)
        # Uncapping, spinning and filtering happen in sequence on one frame.
        total_time += uncapping_time(capped_percent)
        total_time += spinning_time(nectar_type)
        total_time += filtering_time(volume)
        total_volume += volume
    return (round(total_volume, 10), round(total_time, 10))


def validate(frames):
    # The harvest log is hand-typed, so reject nonsense before doing arithmetic.
    for index, frame in enumerate(frames):
        if len(frame) != 3:
            raise ValueError("frame %d must hold percent, weight and nectar" % index)
        capped_percent, raw_weight, nectar_type = frame
        if not isinstance(capped_percent, int):
            raise TypeError("frame %d capped percentage must be an integer" % index)
        if not 0 <= capped_percent <= 100:
            raise ValueError("frame %d capped percentage out of range" % index)
        if raw_weight < 0:
            raise ValueError("frame %d has a negative raw weight" % index)
        if not nectar_type.strip():
            raise ValueError("frame %d is missing a nectar type" % index)
    return frames


def report(frames):
    # Summarise one super's worth of frames for the beekeeper's notebook.
    volume, minutes = extract(validate(frames))
    kept = sum(1 for frame in frames if is_ready(frame[0]))
    lines = ["Frames supplied: %d" % len(frames),
             "Frames extracted: %d" % kept,
             "Honey yield: %.2f lb" % volume,
             "Processing time: %.1f min" % minutes]
    return "\n".join(lines)


def main():
    super_box = [(80, 10, "clover"), (65, 12, "wildflower"),
                 (95, 8.5, "wildflower"), (70, 9, "goldenrod")]
    print(report(super_box))
    # The single-frame case from the specification should yield (7.2, 31.6).
    print(extract([(80, 10, "clover")]))


if __name__ == "__main__":
    main()

