IDEAL_PH_MIN = 6
IDEAL_PH_MAX = 7
IDEAL_NITROGEN = 50
IDEAL_PHOSPHORUS = 30
IDEAL_POTASSIUM = 40
PH_PENALTY_PER_POINT = 10


def ph_penalty(ph):
    # Points below the ideal window cost ten each.
    if ph < IDEAL_PH_MIN:
        return (IDEAL_PH_MIN - ph) * PH_PENALTY_PER_POINT
    # Points above the window are charged at the same rate.
    if ph > IDEAL_PH_MAX:
        return (ph - IDEAL_PH_MAX) * PH_PENALTY_PER_POINT
    return 0


def nitrogen_penalty(nitrogen):
    difference = abs(nitrogen - IDEAL_NITROGEN)
    # A deficiency starves the crop, so it weighs twice as much as an excess.
    if nitrogen < IDEAL_NITROGEN:
        return difference * 2
    return difference


def sample_penalty(sample):
    # Each reading must carry exactly the four measured values.
    if len(sample) != 4:
        raise ValueError("each sample needs ph, nitrogen, phosphorus and potassium")
    ph, nitrogen, phosphorus, potassium = sample
    for value in sample:
        # Laboratory readings arrive as whole numbers; booleans are not readings.
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("soil measurements must be integers")
    total = ph_penalty(ph)
    total += nitrogen_penalty(nitrogen)
    total += abs(phosphorus - IDEAL_PHOSPHORUS)
    total += abs(potassium - IDEAL_POTASSIUM)
    return total


def categorize(penalty):
    # Very small deviations leave the soil in optimal shape.
    if penalty < 20:
        return "optimal"
    # Moderate deviations are still workable with light amendment.
    if penalty < 50:
        return "acceptable"
    return "poor"


def analyze(samples):
    return [categorize(sample_penalty(sample)) for sample in samples]


def report(samples):
    lines = []
    categories = analyze(samples)
    for index, (sample, category) in enumerate(zip(samples, categories), start=1):
        penalty = sample_penalty(sample)
        lines.append(
            "Sample {0}: ph={1} N={2} P={3} K={4} -> penalty {5} ({6})".format(
                index, sample[0], sample[1], sample[2], sample[3], penalty, category
            )
        )
    # A closing summary helps the agronomist scan the batch quickly.
    worst = max(categories, key=lambda c: ["optimal", "acceptable", "poor"].index(c))
    lines.append("Worst category in batch: {0}".format(worst))
    return "\n".join(lines)


def main():
    field_samples = [
        (5, 40, 30, 40),
        (6, 50, 30, 40),
        (8, 20, 55, 10),
        (7, 65, 28, 44),
    ]
    print(report(field_samples))


if __name__ == "__main__":
    main()

