text_nat:
MAX_POWER_RESERVE_HOURS = 72.0
STALL_EFFICIENCY = 0.4
FRICTION_THRESHOLD = 28000.0
FRICTION_STEP = 1000.0
FRICTION_RATE = 0.05


def _validate(movement):
    # A movement must carry exactly three physical parameters.
    if len(movement) != 3:
        raise ValueError("each movement needs (torque, mass, beat_rate)")
    torque, mass, beat_rate = movement
    # Negative or zero values have no mechanical meaning here.
    if torque <= 0 or mass <= 0 or beat_rate <= 0:
        raise ValueError("torque, mass and beat rate must be positive")
    return float(torque), float(mass), float(beat_rate)


def friction_loss(beat_rate):
    # Only beats above the threshold generate extra friction.
    excess = beat_rate - FRICTION_THRESHOLD
    if excess <= 0:
        return 0.0
    return FRICTION_RATE * (excess / FRICTION_STEP)


def transfer_efficiency(torque, mass, beat_rate):
    base_energy = torque * 10.0
    kinetic_energy = mass * beat_rate ** 2 / 2.0
    raw = kinetic_energy / base_energy
    # Friction eats a proportional slice of the raw efficiency.
    return raw * (1.0 - friction_loss(beat_rate))


def power_reserve(torque, loss):
    # With no friction the mainspring unwinds at its nominal rate.
    hours = torque / (1.0 + loss)
    return min(hours, MAX_POWER_RESERVE_HOURS)


def escapement(movements):
    results = []
    for movement in movements:
        torque, mass, beat_rate = _validate(movement)
        loss = friction_loss(beat_rate)
        efficiency = transfer_efficiency(torque, mass, beat_rate)
        # Too little energy reaches the balance wheel to keep it swinging.
        stalls = efficiency < STALL_EFFICIENCY
        results.append((power_reserve(torque, loss), stalls))
    return results


def format_report(movements, results):
    lines = []
    for (torque, mass, beat_rate), (reserve, stalls) in zip(movements, results):
        # A stalled movement is reported instead of its running autonomy.
        status = "STALLS" if stalls else "{:.1f} h reserve".format(reserve)
        lines.append(
            "torque {:g} / mass {:g} / {:g} bph -> {}".format(
                torque, mass, beat_rate, status
            )
        )
    return "\n".join(lines)


def main():
    designs = [
        (50, 2, 28000),
        (80, 3, 36000),
        (12, 0.05, 21600),
        (100, 1.5, 72000),
    ]
    evaluated = escapement(designs)
    print(format_report(designs, evaluated))
    # The highest reserve among the surviving designs guides the final choice.
    running = [reserve for reserve, stalls in evaluated if not stalls]
    if running:
        print("best usable reserve: {:.1f} h".format(max(running)))
    else:
        print("no design keeps running")


if __name__ == "__main__":
    main()

