text_nat:
MATERIAL_BONUS = {
    "nylon": 1.20,
    "polyester": 1.10,
    "polypropylene": 0.95,
}

KNOT_PENALTY = {
    "bowline": 0.70,
    "figure eight": 0.80,
    "square": 0.50,
}

UNSAFE_LIMIT = 100.0


def normalize(text):
    # Material and knot names are matched case-insensitively and without padding spaces.
    return str(text).strip().lower()


def material_factor(material):
    key = normalize(material)
    # Unlisted materials such as manila or hemp get no bonus and no malus.
    return MATERIAL_BONUS.get(key, 1.0)


def knot_factor(knot):
    key = normalize(knot)
    # A missing or unknown knot leaves the rope at full rated strength.
    return KNOT_PENALTY.get(key, 1.0)


def base_strength(diameter_mm):
    diameter = float(diameter_mm)
    if diameter <= 0:
        raise ValueError("rope diameter must be positive, got %r" % (diameter_mm,))
    # Base rating grows with the cross-section, i.e. with the square of the diameter.
    return diameter * diameter * 50.0


def strength(lines):
    strengths = []
    unsafe = 0
    for diameter, material, knot in lines:
        value = base_strength(diameter) * material_factor(material)
        # The knot penalty applies last, to the already material-adjusted figure.
        value *= knot_factor(knot)
        strengths.append(value)
        if value < UNSAFE_LIMIT:
            unsafe += 1
    return strengths, unsafe


def format_report(lines, strengths):
    rows = []
    for (diameter, material, knot), value in zip(lines, strengths):
        flag = "UNSAFE" if value < UNSAFE_LIMIT else "ok"
