STEPS_PER_BAR = 16
MAX_VELOCITY = 127
SWING_OFFSET = 0.1
DOWNBEATS = (1, 5, 9, 13)
CLOSED_HATS = ("hihat", "hh", "closed_hihat", "closed hihat", "closed hi-hat")


def step_in_bar(step):
    # Patterns may be written past the end of the bar, so fold them back in.
    return ((step - 1) % STEPS_PER_BAR) + 1


def normalize_instrument(name):
    # Instrument names arrive from a text pattern file, so tidy them up.
    return " ".join(str(name).lower().replace("-", " ").split())


def swing(step):
    # Even steps are pushed late by a tenth of a step to create the shuffle.
    if step % 2 == 0:
        return SWING_OFFSET
    return 0.0


def accent(step, instrument, velocity):
    result = velocity
    if instrument == "kick" and step == 1:
        # The downbeat kick anchors the bar and is pushed hardest.
        result += 20
    elif instrument == "snare" and step in (5, 13):
        result += 15
    elif instrument in CLOSED_HATS and step not in DOWNBEATS:
        # Ghosted off-beat hats keep the quarter notes audible.
        result -= 10
    return min(result, MAX_VELOCITY)


def validate(hit):
    if len(hit) != 3:
        raise ValueError("each hit needs a step, an instrument and a velocity")
    step, instrument, velocity = hit
    if not isinstance(step, int) or isinstance(step, bool) or step < 1:
        raise ValueError("step numbers must be positive integers: %r" % (step,))
    if not isinstance(velocity, (int, float)) or velocity < 0:
        raise ValueError("velocity must be a non-negative number: %r" % (velocity,))
    return step, normalize_instrument(instrument), velocity


def sequence(hits):
    grooved = []
    for hit in hits:
        raw_step, instrument, velocity = validate(hit)
        step = step_in_bar(raw_step)
        # Timing and loudness are independent, so compute them separately.
        offset = swing(step)
        grooved.append((offset, accent(step, instrument, velocity)))
    return grooved


def format_report(hits, grooved):
    lines = []
    for (step, instrument, base), (offset, final) in zip(hits, grooved):
        # A plus sign reads better than a bare float when describing late hits.
        timing = "on grid" if offset == 0.0 else "+%.2f step" % offset
        lines.append(
            "step %2d %-12s %3d -> %3d  (%s)"
            % (step_in_bar(step), normalize_instrument(instrument), base, final, timing)
        )
    return "\n".join(lines)


def main():
    pattern = [
        (1, "kick", 100),
        (3, "closed hi-hat", 70),
        (5, "snare", 110),
        (8, "closed-hihat", 60),
        (9, "kick", 120),
        (13, "snare", 118),
        (17, "kick", 95),
    ]
    grooved = sequence(pattern)
    print(format_report(pattern, grooved))
    # The raw tuples are what a downstream MIDI writer would consume.
    print(grooved)


if __name__ == "__main__":
    main()

