def _validate(genotype):
    """Check that a genotype string describes two two-allele traits."""
    if not isinstance(genotype, str) or len(genotype) != 4:
        raise ValueError("A genotype must be exactly four characters: %r" % (genotype,))
    # Every allele has to be a letter, otherwise dominance is undefined.
    if not genotype.isalpha():
        raise ValueError("A genotype may only contain letters: %r" % (genotype,))
    first_trait = {genotype[0].lower(), genotype[1].lower()}
    second_trait = {genotype[2].lower(), genotype[3].lower()}
    # The two alleles of one trait must name the same gene.
    if len(first_trait) != 1 or len(second_trait) != 1:
        raise ValueError("Alleles of a trait must share one letter: %r" % (genotype,))
    # The two traits themselves must be different genes.
    if first_trait == second_trait:
        raise ValueError("The two traits must use different letters: %r" % (genotype,))
    return genotype


def gametes(genotype):
    """Return the four gametes produced by a two-trait genotype."""
    _validate(genotype)
    return [a + b for a in genotype[:2] for b in genotype[2:]]


def punnett(parent_one, parent_two):
    """Build the sixteen offspring of a cross as (trait1, trait2) pairs."""
    offspring = []
    for left in gametes(parent_one):
        for right in gametes(parent_two):
            # One allele of each trait comes from each gamete.
            offspring.append((left[0] + right[0], left[1] + right[1]))
    return offspring


def cross(pairs):
    """Summarise each parental pair as (dominant percentage, recessive count)."""
    results = []
    for parent_one, parent_two in pairs:
        squares = punnett(parent_one, parent_two)
        recessive_second = 0
        fully_dominant = 0
        for trait_one, trait_two in squares:
            one_shows = any(allele.isupper() for allele in trait_one)
            two_shows = any(allele.isupper() for allele in trait_two)
            # A trait is recessive only when both of its alleles are lowercase.
            if not two_shows:
                recessive_second += 1
            if one_shows and two_shows:
                fully_dominant += 1
        percentage = round(fully_dominant * 100.0 / len(squares), 2)
        results.append((percentage, recessive_second))
    return results


def report(pairs):
    """Render one human readable line per cross."""
    lines = []
    for (parent_one, parent_two), (percentage, recessive) in zip(pairs, cross(pairs)):
        lines.append(
            "%s x %s -> %.2f%% fully dominant, %d/16 recessive for trait 2"
            % (parent_one, parent_two, percentage, recessive)
        )
    return "\n".join(lines)


def main():
    crosses = [
        ("AaBb", "aabb"),
        ("AaBb", "AaBb"),
        ("AABB", "aabb"),
        ("aaBb", "AAbb"),
    ]
    # The driver prints both the raw tuples and the formatted summary.
    print(cross(crosses))
    print(report(crosses))


if __name__ == "__main__":
    main()

