"""Factorial utilities: computation, validation and a small report driver."""

import sys


def calculate_factorial(n):
    """Return the factorial of the non-negative integer n."""
    # Booleans are ints in Python, but treating True as 1 would be misleading here.
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer, got %r" % (n,))
    # Factorial is undefined for negative arguments.
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    result = 1
    # The loop body never runs for n == 0 or n == 1, which yields the required 1.
    for factor in range(2, n + 1):
        result *= factor
    return result


def parse_argument(text):
    """Convert a command-line token into a non-negative integer."""
    stripped = text.strip()
    # Underscore separators are legal in int literals, but confusing on input.
    if "_" in stripped:
        raise ValueError("unexpected underscore in %r" % text)
    return int(stripped)


def trailing_zero_count(value):
    """Count the trailing zeros of a positive integer's decimal form."""
    zeros = 0
    while value % 10 == 0:
        zeros += 1
        value //= 10
    return zeros


def format_report(n):
    """Build a one-line summary of n! including its size and trailing zeros."""
    value = calculate_factorial(n)
    digits = len(str(value))
    # Zero and one have no trailing zeros, and dividing them by ten would loop badly.
    zeros = trailing_zero_count(value) if value > 1 else 0
    if digits > 20:
        shown = "%s... (%d digits)" % (str(value)[:20], digits)
    else:
        shown = str(value)
    return "%d! = %s [trailing zeros: %d]" % (n, shown, zeros)


def main(argv):
    """Report the factorial of every numeric argument given on the command line."""
    if len(argv) < 2:
        print("usage: %s N [N ...]" % argv[0], file=sys.stderr)
        return 2
    exit_code = 0
    for token in argv[1:]:
        try:
            n = parse_argument(token)
            print(format_report(n))
        except ValueError as exc:
            # Bad input should not abort the remaining arguments.
            print("skipping %r: %s" % (token, exc), file=sys.stderr)
            exit_code = 1
    return exit_code


if __name__ == "__main__":
    sys.exit(main(sys.argv))

