"""Utilities for summing lists of numbers, with a small command-line driver."""

import sys


def sum_list(numbers):
    """Return the sum of all numbers in the given list (0 for an empty list)."""
    total = 0
    # Accumulate manually so that the running total starts at an exact integer zero.
    for value in numbers:
        total += value
    return total


def parse_numbers(tokens):
    """Convert a sequence of strings into ints where possible, otherwise floats."""
    parsed = []
    for token in tokens:
        text = token.strip()
        # Skip separators such as trailing commas left over from copy-pasted input.
        if not text or text == ",":
            continue
        text = text.rstrip(",")
        try:
            # Prefer int so that whole-number sums stay free of float rounding.
            parsed.append(int(text))
        except ValueError:
            try:
                parsed.append(float(text))
            except ValueError:
                raise ValueError("not a number: %r" % token)
    return parsed


def mean(numbers):
    """Return the arithmetic mean, or None when there is nothing to average."""
    if not numbers:
        return None
    return sum_list(numbers) / len(numbers)


def format_report(numbers):
    """Build a human-readable summary of a list of numbers."""
    lines = ["count: %d" % len(numbers), "sum:   %s" % sum_list(numbers)]
    average = mean(numbers)
    # An empty list has no average, so report that explicitly instead of dividing.
    if average is None:
        lines.append("mean:  n/a")
    else:
        lines.append("mean:  %.4g" % average)
    return "\n".join(lines)


def main(argv):
    """Sum the numbers given on the command line, or read them from stdin."""
    if argv:
        tokens = argv
    else:
        # With no arguments, treat whitespace-separated stdin content as the input.
        tokens = sys.stdin.read().split()
    try:
        numbers = parse_numbers(tokens)
    except ValueError as exc:
        print("error: %s" % exc, file=sys.stderr)
        return 2
    print(format_report(numbers))
    return 0


if __name__ == "__main__":
    # Propagate the driver's status code so the script composes well in shells.
    sys.exit(main(sys.argv[1:]))

