"""A tiny arithmetic calculator with an expression parser and report driver."""

OPERATORS = ('+', '-', '*', '/')


def simple_calculator(num1, operator, num2):
    """Apply the given operator to num1 and num2, or return 'Error'."""
    # Reject operators the calculator does not implement.
    if operator not in OPERATORS:
        raise ValueError("unsupported operator: {!r}".format(operator))

    # Only real numbers make sense here, and bool would silently sneak through.
    for value in (num1, num2):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("operands must be numbers, got {!r}".format(value))

    if operator == '+':
        return num1 + num2
    if operator == '-':
        return num1 - num2
    if operator == '*':
        return num1 * num2

    # Division by zero is reported instead of raising.
    if num2 == 0:
        return 'Error'
    return num1 / num2


def parse_number(text):
    """Convert a token to an int when possible, otherwise to a float."""
    try:
        return int(text)
    except ValueError:
        return float(text)


def parse_expression(text):
    """Split 'a op b' into (number, operator, number)."""
    parts = text.split()

    # The parser only understands the strict three-token form.
    if len(parts) != 3:
        raise ValueError("expected 'a op b', got {!r}".format(text))

    left, operator, right = parts
    return parse_number(left), operator, parse_number(right)


def evaluate(text):
    """Parse an expression string and compute its value."""
    num1, operator, num2 = parse_expression(text)
    return simple_calculator(num1, operator, num2)


def format_result(text, result):
    """Build a single human-readable report line."""
    # Floats that are whole numbers read better without the trailing zeros.
    if isinstance(result, float) and result.is_integer():
        result = int(result)
    return "{} = {}".format(text, result)


def main():
    expressions = ['10 + 5', '10 - 5', '10 * 5', '10 / 4', '10 / 0', '7 % 2']
    for text in expressions:
        try:
            line = format_result(text, evaluate(text))
        except (ValueError, TypeError) as exc:
            # Bad input should not abort the whole report.
            line = "{} -> rejected ({})".format(text, exc)
        print(line)


if __name__ == '__main__':
    main()

