"""Helpers for computing the common elements of two lists."""

from collections import Counter


def _membership_container(values):
    """Return a container suited to repeated membership tests on values."""
    try:
        return set(values)
    except TypeError:
        # Unhashable elements such as lists force a linear scan instead.
        return list(values)


def list_intersection(list1, list2):
    """Return the elements of list1 that also appear in list2.

    The result follows the order of list1 and contains no duplicates.
    """
    # The second list is only ever queried for membership.
    lookup = _membership_container(list2)
    result = []
    for item in list1:
        # Keep the first occurrence of each shared element.
        if item in lookup and item not in result:
            result.append(item)
    return result


def multiset_intersection(list1, list2):
    """Return the intersection keeping min(count1, count2) copies of each item."""
    # Counter arithmetic computes the smaller multiplicity for every key at once.
    remaining = Counter(list1) & Counter(list2)
    result = []
    for item in list1:
        if remaining[item] > 0:
            remaining[item] -= 1
            result.append(item)
    return result


def describe(list1, list2):
    """Build one report line comparing both intersection flavours."""
    plain = list_intersection(list1, list2)
    line = "{} & {} -> {}".format(list1, list2, plain)
    try:
        multi = multiset_intersection(list1, list2)
    except TypeError:
        # Counter needs hashable items, so unhashable input has no multiset form.
        return line
    # Mention the multiset variant only when duplicates change the answer.
    if multi != plain:
        line += "  (with duplicates: {})".format(multi)
    return line


def main():
    cases = [
        ([1, 2, 3], [3, 4, 5]),
        ([1, 2], [3, 4]),
        ([1, 2, 2, 3, 3], [2, 3, 3, 9]),
        (["a", "b", "c"], ["c", "a", "a"]),
        ([[1], [2], [3]], [[3], [1]]),
        ([], [1, 2, 3]),
    ]
    for first, second in cases:
        print(describe(first, second))


if __name__ == "__main__":
    main()

