def merge_dictionaries(dict1, dict2):
    """Return a new dict with all pairs from both, dict2 winning on conflicts."""
    # validate inputs early so callers get a clear error instead of a weird one
    for name, value in (("dict1", dict1), ("dict2", dict2)):
        if not isinstance(value, dict):
            raise TypeError(f"{name} must be a dict, got {type(value).__name__}")
    merged = dict(dict1)
    # assigning dict2 last is what gives its values priority
    merged.update(dict2)
    return merged


def merge_many(dicts):
    """Fold merge_dictionaries over a sequence; later dicts override earlier ones."""
    result = {}
    for d in dicts:
        result = merge_dictionaries(result, d)
    return result


def deep_merge(dict1, dict2):
    """Like merge_dictionaries, but nested dicts are merged instead of replaced."""
    merged = merge_dictionaries(dict1, dict2)
    for key, value in dict2.items():
        original = dict1.get(key)
        # only recurse when both sides hold a mapping at the same key
        if isinstance(original, dict) and isinstance(value, dict):
            merged[key] = deep_merge(original, value)
    return merged


def find_conflicts(dict1, dict2):
    """Return keys present in both dicts whose values actually differ."""
    shared = dict1.keys() & dict2.keys()
    return sorted(key for key in shared if dict1[key] != dict2[key])


def format_merge_report(dict1, dict2):
    """Build a short human-readable summary of what a merge would do."""
    merged = merge_dictionaries(dict1, dict2)
    conflicts = find_conflicts(dict1, dict2)
    lines = [f"merged {len(dict1)} + {len(dict2)} keys into {len(merged)}"]
    # sorting keeps the report stable across runs and Python versions
    for key in sorted(merged, key=str):
        origin = "dict2" if key in dict2 else "dict1"
        lines.append(f"  {key!r}: {merged[key]!r} (from {origin})")
    if conflicts:
        overridden = ", ".join(repr(key) for key in conflicts)
        lines.append(f"  overridden by dict2: {overridden}")
    else:
        lines.append("  no conflicting keys")
    return "\n".join(lines)


def main():
    left = {'a': 1, 'b': 2}
    right = {'b': 3, 'c': 4}
    print(merge_dictionaries(left, right))
    # neither input may be mutated by the merge
    print("originals intact:", left == {'a': 1, 'b': 2} and right == {'b': 3, 'c': 4})
    print(format_merge_report(left, right))

    defaults = {'host': 'localhost', 'port': 8080, 'opts': {'debug': False, 'retries': 3}}
    user = {'port': 9090, 'opts': {'debug': True}}
    # a shallow merge throws away the untouched nested options
    print("shallow:", merge_dictionaries(defaults, user))
    print("deep:   ", deep_merge(defaults, user))

    # layered configuration is just a left-to-right fold of merges
    layers = [defaults, {'host': 'example.com'}, user]
    print("layered:", merge_many(layers))


