import re
from collections import Counter

# Hashtags are '#' followed by at least one letter, digit or underscore.
HASHTAG_PATTERN = re.compile(r"#(\w+)")


def extract_hashtags(text):
    """Return the hashtags found in text, without the leading '#'."""
    # The input must be textual; anything else is a programming error.
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return HASHTAG_PATTERN.findall(text)


def normalize_hashtags(tags):
    # Lowercasing makes '#Python' and '#python' the same tag.
    return [tag.lower() for tag in tags]


def count_hashtags(texts):
    """Count how often each hashtag appears across a sequence of texts."""
    counter = Counter()
    for text in texts:
        # Tallying is case-insensitive, so normalize first.
        counter.update(normalize_hashtags(extract_hashtags(text)))
    return counter


def top_hashtags(counter, limit=3):
    # Sort by descending count, then alphabetically to break ties.
    ranked = sorted(counter.items(), key=lambda item: (-item[1], item[0]))
    return ranked[:limit]


def format_report(counter, limit=3):
    """Build a human readable summary of the collected hashtags."""
    if not counter:
        return "No hashtags found."

    lines = ["Hashtag report:"]
    # Align the counts by padding every tag to the longest one.
    width = max(len(tag) for tag in counter)
    for tag, count in top_hashtags(counter, limit):
        plural = "s" if count != 1 else ""
        lines.append("  #{0:<{1}}  {2} time{3}".format(tag, width, count, plural))

    total = sum(counter.values())
    lines.append("  total: {0} hashtag(s), {1} unique".format(total, len(counter)))
    return "\n".join(lines)


def main():
    messages = [
        "This is a #test with #python.",
        "No hashtags here.",
        "Learning #Python and #python again, plus #regex!",
        "Mixed #Test_1 and #regex content.",
    ]

    for message in messages:
        print(extract_hashtags(message), "<-", message)

    print()
    print(format_report(count_hashtags(messages)))


if __name__ == "__main__":
    main()

