def normalize(text):
    """Return the text lowercased and stripped of spaces."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Spaces are irrelevant to the tally, so they are dropped here.
    without_spaces = (ch for ch in text if ch != " ")
    # Case folding merges 'A' and 'a' into one bucket.
    return "".join(ch.lower() for ch in without_spaces)


def char_counts(cleaned):
    """Build a mapping of character to occurrence count."""
    counts = {}
    for ch in cleaned:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def most_frequent_char(text):
    """Return the most frequent character in text, ignoring spaces and case."""
    cleaned = normalize(text)
    if not cleaned:
        return None
    counts = char_counts(cleaned)
    best = cleaned[0]
    # Scanning the cleaned text in order lets the earliest character win ties.
    for ch in cleaned:
        if counts[ch] > counts[best]:
            best = ch
    return best


def ranked_chars(text, limit=None):
    """Return (char, count) pairs sorted by count, then by first appearance."""
    cleaned = normalize(text)
    counts = char_counts(cleaned)
    first_seen = {}
    for index, ch in enumerate(cleaned):
        # Only the first index of each character matters for the tie-break.
        if ch not in first_seen:
            first_seen[ch] = index
    pairs = sorted(counts.items(), key=lambda item: (-item[1], first_seen[item[0]]))
    if limit is None:
        return pairs
    return pairs[:limit]


def format_report(text, limit=3):
    """Produce a one-line human readable summary for a piece of text."""
    winner = most_frequent_char(text)
    # Text made only of spaces has nothing to report beyond that fact.
    if winner is None:
        return "{!r}: no countable characters".format(text)
    top = ranked_chars(text, limit)
    details = ", ".join("{}={}".format(ch, n) for ch, n in top)
    return "{!r}: winner {!r} ({})".format(text, winner, details)


def main():
    samples = [
        "hello world",
        "aabbc",
        "Mississippi River",
        "   ",
        "The quick brown fox jumps over the lazy dog",
    ]
    for sample in samples:
        print(format_report(sample))


