from collections.abc import Iterable


def flatten_list(list_of_lists):
    """Return a single list containing the items of every sublist, in order."""
    # Reject the common mistake of passing a bare item instead of a container.
    if not isinstance(list_of_lists, Iterable) or isinstance(list_of_lists, (str, bytes)):
        raise TypeError("flatten_list expects an iterable of lists")

    flat = []
    for index, sublist in enumerate(list_of_lists):
        # Each element of the outer container must itself be a sequence of items.
        if not isinstance(sublist, Iterable) or isinstance(sublist, (str, bytes)):
            raise TypeError("element %d is not a list: %r" % (index, sublist))
        flat.extend(sublist)
    return flat


def deep_flatten(nested):
    """Flatten arbitrarily nested lists into one flat list of scalars."""
    flat = []
    for item in nested:
        # Strings are iterable but count as scalars here, so they stay intact.
        if isinstance(item, Iterable) and not isinstance(item, (str, bytes)):
            flat.extend(deep_flatten(item))
        else:
            flat.append(item)
    return flat


def group_sizes(list_of_lists):
    """Report the length of every sublist, which is useful for sanity checks."""
    return [len(sublist) for sublist in list_of_lists]


def unflatten(flat, sizes):
    """Rebuild a list of lists from a flat list and the original group sizes."""
    # The sizes must account for exactly as many items as the flat list holds.
    if sum(sizes) != len(flat):
        raise ValueError("sizes %r do not match %d items" % (sizes, len(flat)))

    result = []
    start = 0
    for size in sizes:
        result.append(flat[start:start + size])
        start += size
    return result


def describe(list_of_lists):
    """Produce a one-line summary of a flattening operation."""
    flat = flatten_list(list_of_lists)
    sizes = group_sizes(list_of_lists)
    return "%r -> %r (groups: %s)" % (list_of_lists, flat, sizes or "none")


def main():
    samples = [
        [[1, 2], [3, 4, 5]],
        [[]],
        [],
        [["a"], ["b", "c"], []],
    ]
    for sample in samples:
        print(describe(sample))

    # Round-tripping proves the flattening kept the original grouping information.
    tricky = [[1], [], [2, 3, 4], [5]]
    restored = unflatten(flatten_list(tricky), group_sizes(tricky))
    print("round trip ok:", restored == tricky)

    # Deeply nested input needs the recursive variant, not the one-level version.
    nested = [1, [2, [3, [4, 5]]], [], [[6]]]
    print("deep:", deep_flatten(nested))

    try:
        flatten_list([1, 2, 3])
    except TypeError as exc:
        # Bad input should fail loudly rather than silently produce odd output.
        print("error:", exc)


if __name__ == "__main__":
    main()

