def find_missing_number(numbers):
    """Return the single missing value from an unsorted list of 1..N with one gap."""
    validate_sequence(numbers)
    # The full range runs from 1 to N, where N is one more than the count given.
    n = len(numbers) + 1
    expected_total = n * (n + 1) // 2
    # Whatever the order, the shortfall against the full total is the missing value.
    return expected_total - sum(numbers)


def validate_sequence(numbers):
    """Raise ValueError unless numbers is a valid 1..N sequence with exactly one gap."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if not numbers:
        raise ValueError("numbers must contain at least one element")
    n = len(numbers) + 1
    seen = set()
    for value in numbers:
        # Booleans are instances of int, so reject them explicitly.
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("all entries must be integers, got %r" % (value,))
        if value < 1 or value > n:
            raise ValueError("entry %d is outside the range 1..%d" % (value, n))
        # Repeats would hide a second gap and make the sum trick give a wrong answer.
        if value in seen:
            raise ValueError("entry %d appears more than once" % value)
        seen.add(value)


def parse_sequence(text):
    """Turn a comma or whitespace separated string into a list of integers."""
    # Commas are treated as plain separators so both input styles work.
    tokens = text.replace(",", " ").split()
    if not tokens:
        raise ValueError("no numbers found in %r" % text)
    return [int(token) for token in tokens]


def describe(numbers):
    """Build a one-line report about the sequence and its missing member."""
    missing = find_missing_number(numbers)
    n = len(numbers) + 1
    shown = ", ".join(str(value) for value in numbers)
    return "[%s] covers 1..%d and is missing %d" % (shown, n, missing)


def main():
    samples = [
        "1, 2, 4, 5",
        "5 1 3 2",
        "2",
        "7, 3, 1, 5, 4, 2, 8, 9, 10, 6",
        "1, 2, 2, 4",
    ]
    for sample in samples:
        try:
            print(describe(parse_sequence(sample)))
        except ValueError as error:
            # Bad input should be reported without killing the whole run.
            print("%r rejected: %s" % (sample, error))


if __name__ == "__main__":
