    # Times must be integers; booleans are rejected because they are not real clock values.
    if not isinstance(start, int) or not isinstance(end, int):
        raise ValueError("event times must be integers")
    if isinstance(start, bool) or isinstance(end, bool):
        raise ValueError("event times must be integers, not booleans")
    # An event has to move forward in time, so an empty or reversed span is invalid.
    if start >= end:
        raise ValueError("event start must be strictly before its end")
    return (start, end)


def overlaps(first, second):
    """Tell whether two half-open intervals share at least one time unit."""
    a_start, a_end = first
    b_start, b_end = second
    # Touching endpoints do not clash: an event ending at 6 leaves 6 free.
    return a_start < b_end and b_start < a_end


def has_conflict(schedule, new_event_start, new_event_end):
    """Return True if the new event overlaps any event already in the schedule."""
    new_event = validate_interval(new_event_start, new_event_end)
    for entry in schedule:
        # Each schedule entry is checked for shape before it is trusted.
        if len(entry) != 2:
            raise ValueError("schedule entries must be (start, end) pairs")
        existing = validate_interval(entry[0], entry[1])
        if overlaps(existing, new_event):
            return True
    return False


def conflicting_events(schedule, new_event_start, new_event_end):
    """List every existing event that the new event collides with."""
    new_event = validate_interval(new_event_start, new_event_end)
    clashes = [validate_interval(s, e) for s, e in schedule]
    # Sorting makes the report read chronologically regardless of input order.
    clashes.sort()
    return [event for event in clashes if overlaps(event, new_event)]


