    """Build a one-line human readable verdict for a booking request."""
    clashes = conflicting_events(schedule, new_event_start, new_event_end)
    request = "{}-{}".format(new_event_start, new_event_end)
    if not clashes:
        return "%s: free" % request
    # Several clashes are joined so the caller sees all of them at once.
    listed = ", ".join("{}-{}".format(s, e) for s, e in clashes)
    return "{}: conflicts with {}".format(request, listed)


