    """Insert the event into the schedule, returning whether it was accepted."""
    if has_conflict(schedule, new_event_start, new_event_end):
        return False
    schedule.append(validate_interval(new_event_start, new_event_end))
    # Keeping the schedule sorted keeps later reports tidy.
    schedule.sort()
    return True


