    schedule = [(1, 5), (10, 15)]
    requests = [(3, 7), (6, 8), (5, 10), (14, 20), (2, 3)]
    for start, end in requests:
        print(describe_request(schedule, start, end))
    print("---")
    # The same requests are now actually booked, so earlier ones block later ones.
    calendar = [(1, 5), (10, 15)]
    for start, end in requests:
        accepted = book(calendar, start, end)
        print("{}-{} booked: {}".format(start, end, accepted))
    print("final schedule:", calendar)


