def count_uppercase(text):
    # Reject non-string input early, since iterating a number would fail cryptically.
    if not isinstance(text, str):
        raise TypeError("count_uppercase() expects a str, got %s" % type(text).__name__)
    count = 0
    for char in text:
        # Only cased characters can be uppercase, so isupper() is the exact test.
        if char.isupper():
            count += 1
    return count


def uppercase_positions(text):
    """Return the indexes at which uppercase letters occur."""
    # Enumerate gives us the index alongside the character in one pass.
    return [index for index, char in enumerate(text) if char.isupper()]


def uppercase_ratio(text):
    """Fraction of the characters in text that are uppercase."""
    if not text:
        # An empty string has no characters, so the ratio is defined as zero.
        return 0.0
    return count_uppercase(text) / len(text)


def summarize(text):
    """Build a small dictionary describing the uppercase content of text."""
    positions = uppercase_positions(text)
    return {
        "text": text,
        "count": len(positions),
        "positions": positions,
        "ratio": uppercase_ratio(text),
    }


def format_summary(summary):
    """Render one summary dictionary as a single readable line."""
    pieces = ["%r -> %d uppercase" % (summary["text"], summary["count"])]
    if summary["positions"]:
        # Positions are only worth printing when at least one was found.
        joined = ", ".join(str(pos) for pos in summary["positions"])
        pieces.append("at [%s]" % joined)
    pieces.append("(%.1f%% of the string)" % (100.0 * summary["ratio"]))
    return " ".join(pieces)


def report(samples):
    """Print a formatted summary for every sample and return the total count."""
    total = 0
    for sample in samples:
        summary = summarize(sample)
        print(format_summary(summary))
        total += summary["count"]
    return total


def main():
    samples = [
        "Hello World",
        "python is fun",
        "ALL CAPS, no lowercase!",
        "",
        "MiXeD CaSe 123",
    ]
    total = report(samples)
    # The grand total lets a caller sanity-check the per-sample lines above.
    print("Total uppercase letters across %d samples: %d" % (len(samples), total))

    # Verify the two documented examples so the driver doubles as a check.
    assert count_uppercase("Hello World") == 2
    assert count_uppercase("python is fun") == 0


