"""Utilities for extracting the odd integers from a list of numbers."""

import sys
from typing import Iterable, List


def parse_numbers(text: str) -> List[int]:
    # Commas are treated as plain separators so "1, 2 3" parses cleanly.
    normalized = text.replace(",", " ")
    values = []
    for token in normalized.split():
        try:
            values.append(int(token))
        except ValueError:
            # A non-numeric token is a caller error, so report it precisely.
            raise ValueError(f"not an integer: {token!r}") from None
    return values


def validate_numbers(numbers: Iterable[int]) -> List[int]:
    checked = []
    for index, value in enumerate(numbers):
        # Booleans are ints in Python but are not meaningful numbers here.
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"element {index} is not an integer: {value!r}")
        checked.append(value)
    return checked


def filter_odd(numbers):
    checked = validate_numbers(numbers)
    # Testing the remainder against zero keeps negative odds like -3 included.
    odd_numbers = [value for value in checked if value % 2 != 0]
    return odd_numbers


def format_report(numbers: List[int], odd_numbers: List[int]) -> str:
    if not odd_numbers:
        # An empty result deserves words rather than an empty bracket pair.
        tail = "no odd numbers"
    else:
        tail = ", ".join(str(value) for value in odd_numbers)
    return f"{numbers} -> {tail}"


def main(argv: List[int]) -> int:
    if argv:
        # Every argument is a batch of numbers, e.g. "1,2,3" or "4 5".
        batches = [parse_numbers(argument) for argument in argv]
    else:
        batches = [[1, 2, 3, 4, 5], [2, 4, 6], parse_numbers("-7, -2, 0, 9, 11")]

    for batch in batches:
        odd_numbers = filter_odd(batch)
        print(format_report(batch, odd_numbers))
    return 0


if __name__ == "__main__":
    try:
        status = main(sys.argv[1:])
    except (TypeError, ValueError) as error:
        print(f"rejected: {error}", file=sys.stderr)
        status = 1
    sys.exit(status)

