def char_frequency(text):
    """Count how often each character occurs in text, ignoring case."""
    # Reject non-string input early so the loop below cannot fail obscurely.
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)

    frequency_map = {}
    for char in text.lower():
        # Dict insertion order preserves first appearance of each character.
        frequency_map[char] = frequency_map.get(char, 0) + 1
    return frequency_map


def letters_only(frequency_map):
    """Keep the entries whose key is an alphabetic character."""
    return {char: count for char, count in frequency_map.items() if char.isalpha()}


def most_common(frequency_map, limit=3):
    """Return the `limit` most frequent (char, count) pairs."""
    # Sort by descending count, then alphabetically to break ties deterministically.
    ordered = sorted(frequency_map.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def format_char(char):
    """Give whitespace and other invisible characters a readable name."""
    names = {" ": "<space>", "\t": "<tab>", "\n": "<newline>"}
    if char in names:
        return names[char]
    return repr(char)


def format_report(text, limit=3):
    """Build a human readable summary of the character frequencies in text."""
    frequency_map = char_frequency(text)
    lines = ["Text: %r" % text]

    # An empty string has nothing to report beyond the header.
    if not frequency_map:
        lines.append("  (no characters)")
        return "\n".join(lines)

    lines.append("  distinct characters: %d" % len(frequency_map))
    for char, count in sorted(frequency_map.items()):
        lines.append("  %-10s %d" % (format_char(char), count))

    letters = letters_only(frequency_map)
    # Punctuation-only input leaves no letters to rank.
    if letters:
        top = most_common(letters, limit)
        ranked = ", ".join("%s=%d" % (char, count) for char, count in top)
        lines.append("  top letters: %s" % ranked)
    return "\n".join(lines)


def main():
    samples = ["hello", "Python", "Mississippi River", "!!!", ""]
    for sample in samples:
        print(format_report(sample))
        print()

    # Verify the two documented examples of char_frequency.
    assert char_frequency("hello") == {"h": 1, "e": 1, "l": 2, "o": 1}
    assert char_frequency("Python") == {
        "p": 1,
        "y": 1,
        "t": 1,
        "h": 1,
        "o": 1,
        "n": 1,
    }


if __name__ == "__main__":
    main()

