from datetime import date


def parse_date(date_str):
    """Convert a 'YYYY-MM-DD' string into a date object."""
    # Reject non-string input early so the error message stays meaningful.
    if not isinstance(date_str, str):
        raise TypeError("date must be given as a string in 'YYYY-MM-DD' format")

    parts = date_str.strip().split('-')
    # A valid ISO date has exactly three dash-separated components.
    if len(parts) != 3:
        raise ValueError("malformed date: %r" % date_str)

    year_str, month_str, day_str = parts
    # Enforce the fixed field widths; '2023-1-5' is not an ISO date.
    if len(year_str) != 4 or len(month_str) != 2 or len(day_str) != 2:
        raise ValueError("malformed date: %r" % date_str)

    if not (year_str + month_str + day_str).isdigit():
        raise ValueError("date contains non-digit characters: %r" % date_str)

    # The date constructor performs the calendar checks (leap years, month lengths).
    return date(int(year_str), int(month_str), int(day_str))


def days_remaining(start_date_str, end_date_str):
    """Return the number of days between the start date and the end date."""
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return (end - start).days


def describe_remaining(start_date_str, end_date_str):
    """Build a human-readable sentence about the gap between two dates."""
    days = days_remaining(start_date_str, end_date_str)

    # A negative difference means the target date is already in the past.
    if days < 0:
        return "%s passed %d day(s) ago (as of %s)" % (
            end_date_str, -days, start_date_str)

    if days == 0:
        return "%s is today" % end_date_str

    weeks, extra = divmod(days, 7)
    # Only mention weeks once there is at least one full week to report.
    if weeks:
        breakdown = " = %d week(s) and %d day(s)" % (weeks, extra)
    else:
        breakdown = ""

    return "%d day(s) remaining until %s%s" % (days, end_date_str, breakdown)


def main():
    schedule = [
        ('2023-01-01', '2023-01-05'),
        ('2023-12-31', '2024-01-01'),
        ('2024-02-28', '2024-03-01'),
        ('2024-06-01', '2024-05-01'),
        ('2025-03-10', '2025-03-10'),
    ]

    for start_str, end_str in schedule:
        # Bad rows should not abort the whole report, so handle them per pair.
        try:
            print(describe_remaining(start_str, end_str))
        except (TypeError, ValueError) as exc:
            print("skipping (%s, %s): %s" % (start_str, end_str, exc))

    total = sum(days_remaining(s, e) for s, e in schedule)
    # The net total can cancel out when past dates are mixed with future ones.
    print("net day balance across the schedule: %d" % total)


if __name__ == '__main__':
    main()

