def simulate_stack(stack, operation, item=None):
    """Perform a single push/pop operation on stack and return the result."""
    # The stack is mutated in place so the caller sees the new state.
    if not isinstance(stack, list):
        raise TypeError("stack must be a list")
    op = operation.strip().lower() if isinstance(operation, str) else operation
    if op == "push":
        stack.append(item)
        return stack
    if op == "pop":
        # Popping an empty stack is not an error, it simply yields None.
        if not stack:
            return None
        return stack.pop()
    raise ValueError("unknown operation: %r" % (operation,))


def parse_command(line):
    """Turn a text command such as 'push 3' into an (operation, item) pair."""
    # Commands are split once so that pushed text may contain spaces.
    parts = line.split(None, 1)
    if not parts:
        raise ValueError("empty command")
    op = parts[0].lower()
    if op == "pop":
        # A pop command carries no payload, anything extra is a mistake.
        if len(parts) > 1:
            raise ValueError("pop takes no argument")
        return op, None
    if op == "push":
        if len(parts) == 1:
            raise ValueError("push needs an item")
        return op, coerce_item(parts[1].strip())
    raise ValueError("unknown operation: %r" % (op,))


def coerce_item(text):
    """Convert a textual item to int or float when possible."""
    try:
        return int(text)
    except ValueError:
        pass
    # Floats are accepted too, everything else stays a plain string.
    try:
        return float(text)
    except ValueError:
        return text


def run_script(stack, commands):
    """Apply every command in order and collect a report of the results."""
    report = []
    for line in commands:
        op, item = parse_command(line)
        result = simulate_stack(stack, op, item)
        report.append(describe(op, item, result, stack))
    return report


def describe(op, item, result, stack):
    """Build a one line human readable summary of a completed operation."""
    if op == "push":
        return "push %r -> stack %r" % (item, result)
    # A None result after a pop means the stack had been exhausted.
    if result is None:
        return "pop from empty stack -> None"
    return "pop -> %r, stack %r" % (result, stack)


def main():
    stack = [1, 2]
    script = ["push 3", "pop", "push hello", "push 2.5", "pop", "pop", "pop", "pop"]
    for line in run_script(stack, script):
        print(line)
    # The final state shows that the caller's list was mutated in place.
    print("final stack:", stack)


if __name__ == "__main__":
    main()

