import random
from collections import Counter

# The two possible outcomes of a fair coin flip.
FACES = ('Heads', 'Tails')


def simulate_coin_flip():
    """Flip a fair coin once and return 'Heads' or 'Tails'."""
    # Random choice over the two faces gives each a 50% chance.
    result = random.choice(FACES)
    return result


def flip_many(n):
    """Return a list of n independent coin flip results."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError('n must be an integer')
    # A negative number of flips has no meaning here.
    if n < 0:
        raise ValueError('n must be non-negative')
    return [simulate_coin_flip() for _ in range(n)]


def tally(flips):
    """Count how often each face appeared in a sequence of flips."""
    counts = Counter(flips)
    # Faces that never came up should still be reported as zero.
    for face in FACES:
        counts.setdefault(face, 0)
    return counts


def longest_streak(flips):
    """Return (face, length) of the longest run of identical results."""
    if not flips:
        return (None, 0)
    best_face, best_len = flips[0], 1
    current_len = 1
    for previous, current in zip(flips, flips[1:]):
        # Extend the current run, or start a new one on a change.
        if current == previous:
            current_len += 1
        else:
            current_len = 1
        if current_len > best_len:
            best_face, best_len = current, current_len
    return (best_face, best_len)


def format_report(flips):
    """Build a human-readable summary of a series of flips."""
    counts = tally(flips)
    total = len(flips)
    lines = ['Flips: {}'.format(total)]
    for face in FACES:
        # Percentages are only meaningful when at least one flip happened.
        share = (100.0 * counts[face] / total) if total else 0.0
        lines.append('{:<6} {:>4}  ({:5.1f}%)'.format(face, counts[face], share))
    face, length = longest_streak(flips)
    if face is not None:
        lines.append('Longest streak: {} x {}'.format(length, face))
    return '\n'.join(lines)


def main():
    # A single flip answers the original question directly.
    print('One flip:', simulate_coin_flip())
    flips = flip_many(20)
    print('Sequence:', ', '.join(flips))
    print(format_report(flips))


if __name__ == '__main__':
    main()

