def matrix_shape(matrix):
    """Return (rows, cols) for a rectangular matrix, raising on bad input."""
    # A matrix must be a non-empty sequence of rows.
    if not isinstance(matrix, (list, tuple)) or not matrix:
        raise ValueError("matrix must be a non-empty list of rows")
    rows = len(matrix)
    cols = None
    for index, row in enumerate(matrix):
        if not isinstance(row, (list, tuple)):
            raise ValueError("row %d is not a list" % index)
        if cols is None:
            cols = len(row)
        # Ragged rows would make element-wise work ambiguous.
        elif len(row) != cols:
            raise ValueError("row %d has length %d, expected %d" % (index, len(row), cols))
    if cols == 0:
        raise ValueError("matrix rows must contain at least one value")
    return rows, cols


def check_numeric(matrix, name):
    """Verify every entry of the matrix is a real number."""
    for i, row in enumerate(matrix):
        for j, value in enumerate(row):
            # Booleans are ints in Python, but they are not meaningful here.
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("%s[%d][%d] is not numeric: %r" % (name, i, j, value))


def matrix_subtract(matrix1, matrix2):
    """Return the element-wise difference matrix1 - matrix2."""
    shape1 = matrix_shape(matrix1)
    shape2 = matrix_shape(matrix2)
    # Dimensions have to agree for element-wise subtraction.
    if shape1 != shape2:
        raise ValueError("shape mismatch: %s vs %s" % (shape1, shape2))
    check_numeric(matrix1, "matrix1")
    check_numeric(matrix2, "matrix2")
    result_matrix = []
    for row1, row2 in zip(matrix1, matrix2):
        result_matrix.append([a - b for a, b in zip(row1, row2)])
    return result_matrix


def format_matrix(matrix):
    """Render a matrix as right-aligned columns of text."""
    cells = [[format_number(v) for v in row] for row in matrix]
    widths = []
    for col in range(len(cells[0])):
        # Each column is padded to its own widest entry.
        widths.append(max(len(row[col]) for row in cells))
    lines = []
    for row in cells:
        lines.append("  ".join(text.rjust(widths[k]) for k, text in enumerate(row)))
    return "\n".join(lines)


def format_number(value):
    """Print floats without a trailing '.0' so output stays compact."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def main():
    pairs = [
        ([[1, 2], [3, 4]], [[1, 1], [1, 1]]),
        ([[5, 0]], [[1, -1]]),
        ([[2.5, -3.0], [0.0, 7.25]], [[0.5, 1.0], [-2.0, 7.25]]),
    ]
    for matrix1, matrix2 in pairs:
        difference = matrix_subtract(matrix1, matrix2)
        print("matrix1 - matrix2 =", difference)
        # The aligned form is easier to read for larger matrices.
        print(format_matrix(difference))
        print()


if __name__ == "__main__":
    main()

