def _validate(nested_dict, separator):
    """Reject inputs that cannot be flattened into unambiguous string keys."""
    if not isinstance(nested_dict, dict):
        raise TypeError("nested_dict must be a dict")
    if not isinstance(separator, str) or not separator:
        raise ValueError("separator must be a non-empty string")
    for key, value in nested_dict.items():
        # Outer keys become prefixes, so they must be text.
        if not isinstance(key, str):
            raise TypeError("outer keys must be strings, got %r" % (key,))
        if isinstance(value, dict):
            for inner in value:
                # Inner keys are concatenated after the separator.
                if not isinstance(inner, str):
                    raise TypeError("inner keys must be strings, got %r" % (inner,))


def flatten_dict(nested_dict, separator):
    """Flatten a dict with at most one level of nesting."""
    _validate(nested_dict, separator)
    flattened_dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            # Empty sub-dictionaries contribute no keys at all.
            for inner_key, inner_value in value.items():
                flattened_dict[key + separator + inner_key] = inner_value
        else:
            # Scalars are copied across unchanged.
            flattened_dict[key] = value
    return flattened_dict


def find_collisions(nested_dict, separator):
    """Return composite keys that clash with another key in the result."""
    seen = set()
    collisions = set()
    for key, value in nested_dict.items():
        names = [key + separator + inner for inner in value] if isinstance(value, dict) else [key]
        for name in names:
            # A repeated name means one entry silently overwrites another.
            if name in seen:
                collisions.add(name)
            seen.add(name)
    return sorted(collisions)


def format_report(nested_dict, separator):
    """Build a human-readable listing of the flattened mapping."""
    flat = flatten_dict(nested_dict, separator)
    if not flat:
        return "(empty)"
    width = max(len(k) for k in flat)
    lines = []
    for key in sorted(flat):
        # Align the values so nested groups are easy to scan.
        lines.append("%-*s = %r" % (width, key, flat[key]))
    clashes = find_collisions(nested_dict, separator)
    if clashes:
        lines.append("WARNING: colliding keys -> " + ", ".join(clashes))
    return "\n".join(lines)


def main():
    samples = [
        ({'a': 1, 'b': {'c': 2, 'd': 3}}, '_'),
        ({'x': {'y': 10}}, '.'),
        ({'a_b': 0, 'a': {'b': 1}}, '_'),
    ]
    for nested_dict, separator in samples:
        print("input: %r  separator: %r" % (nested_dict, separator))
        print(format_report(nested_dict, separator))
        # Blank line keeps consecutive samples readable.
        print()


if __name__ == "__main__":
