"""Stock transaction profit/loss calculations and reporting."""


def validate_transaction(buy_price, sell_price, quantity):
    # Prices come from user input, so reject anything that is not numeric.
    for name, value in (("buy_price", buy_price), ("sell_price", sell_price)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("%s must be a number" % name)
        if value <= 0:
            raise ValueError("%s must be positive" % name)
    # Quantity is a share count, so fractional shares are not accepted here.
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise TypeError("quantity must be an integer")
    if quantity <= 0:
        raise ValueError("quantity must be positive")


def calculate_stock_profit(buy_price, sell_price, quantity):
    """Return the total profit (positive) or loss (negative) of one trade."""
    validate_transaction(buy_price, sell_price, quantity)
    profit_loss = (sell_price - buy_price) * quantity
    # Floating point multiplication leaves noise like 199.99999999999997.
    return round(profit_loss, 2)


def return_percentage(buy_price, sell_price):
    """Return the percentage change between buy and sell price."""
    change = (sell_price - buy_price) / buy_price * 100.0
    return round(change, 2)


def break_even_price(buy_price, quantity, fee):
    """Return the sell price needed to cover the buy cost plus a flat fee."""
    # The fee applies to the whole order, so spread it over every share.
    return round(buy_price + fee / quantity, 4)


def format_transaction(buy_price, sell_price, quantity):
    """Build a one-line human readable summary of a trade."""
    profit_loss = calculate_stock_profit(buy_price, sell_price, quantity)
    pct = return_percentage(buy_price, sell_price)
    # A zero result is neither a profit nor a loss, so label it separately.
    if profit_loss > 0:
        label = "PROFIT"
    elif profit_loss < 0:
        label = "LOSS"
    else:
        label = "BREAK EVEN"
    return "%4d shares @ %7.2f -> %7.2f | %-11s %+10.2f (%+.2f%%)" % (
        quantity, buy_price, sell_price, label, profit_loss, pct)


def portfolio_report(trades, fee=0.0):
    """Print a report for every trade and return the aggregated result."""
    total = 0.0
    for buy_price, sell_price, quantity in trades:
        print(format_transaction(buy_price, sell_price, quantity))
        total += calculate_stock_profit(buy_price, sell_price, quantity)
        # Show the exit price that would have cancelled out the trading fee.
        if fee:
            print("     break-even sell price: %.4f"
                  % break_even_price(buy_price, quantity, fee))
    total = round(total - fee * len(trades), 2)
    print("-" * 66)
    print("Net result after fees: %+.2f" % total)
    return total


def main():
    trades = [
        (10.0, 12.0, 100),
        (15.0, 13.0, 50),
        (7.25, 7.25, 400),
        (120.0, 133.5, 12),
    ]
    portfolio_report(trades, fee=4.95)


if __name__ == "__main__":
    main()

