# Find the single duplicated value in a list holding 1..N plus one repeat.


def validate(numbers):
    # Two entries are the minimum needed to hold a duplicate.
    if len(numbers) < 2:
        raise ValueError("need at least two numbers")

    n = len(numbers) - 1
    for value in numbers:
        # Booleans are integers in Python, but they are not valid data here.
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("all entries must be plain integers")
        # Every entry has to fall inside 1..N for the sum identity to hold.
        if value < 1 or value > n:
            raise ValueError("value %d outside range 1..%d" % (value, n))

    # Exactly one repeat means the count of distinct values is N.
    if len(set(numbers)) != n:
        raise ValueError("input must contain exactly one duplicated number")

    return n


def find_duplicate(numbers):
    n = validate(numbers)
    # The excess over the triangular number 1+2+...+N is the repeated value.
    expected = n * (n + 1) // 2
    duplicate_num = sum(numbers) - expected
    return duplicate_num


def parse_line(line):
    # Commas are treated as plain separators alongside whitespace.
    cleaned = line.replace(",", " ")
    return [int(token) for token in cleaned.split()]


def describe(numbers):
    shown = ", ".join(str(value) for value in numbers)
    try:
        duplicate_num = find_duplicate(numbers)
    except (TypeError, ValueError) as error:
        # Bad data is reported instead of stopping the whole report.
        return "[%s] -> rejected: %s" % (shown, error)
    return "[%s] -> duplicate is %d" % (shown, duplicate_num)


def main():
    raw_inputs = [
        "1, 2, 3, 2",
        "5 1 3 4 2 5",
        "4 4 1 2 3",
        "1 2 3 4",
    ]

    for raw in raw_inputs:
        # Parsing happens before solving so malformed text fails loudly here.
        numbers = parse_line(raw)
        print(describe(numbers))


if __name__ == "__main__":
    main()

