def validate_image(image_matrix):
    # Reject anything that is not a rectangular matrix of RGB triples.
    if not isinstance(image_matrix, list):
        raise TypeError("image_matrix must be a list of rows")
    width = None
    for row in image_matrix:
        if not isinstance(row, list):
            raise TypeError("each row must be a list of pixels")
        # All rows of an image share the same width.
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("rows have inconsistent widths")
        for pixel in row:
            if not isinstance(pixel, (list, tuple)) or len(pixel) != 3:
                raise ValueError("each pixel must have exactly three channels")
            for channel in pixel:
                if not isinstance(channel, int) or isinstance(channel, bool):
                    raise TypeError("channel values must be plain integers")
                # Channel values outside 0..255 cannot come from an 8-bit image.
                if channel < 0 or channel > 255:
                    raise ValueError("channel values must be in 0..255")
    return width if width is not None else 0


def average_channels(pixel):
    # Integer division matches the truncated averages in the examples.
    red, green, blue = pixel
    return (red + green + blue) // 3


def to_grayscale(image_matrix):
    validate_image(image_matrix)
    grayscale_image = []
    for row in image_matrix:
        grayscale_image.append([average_channels(pixel) for pixel in row])
    return grayscale_image


def histogram(grayscale_image, buckets=4):
    # Split the 0..255 range into equally sized buckets.
    span = 256 // buckets
    counts = [0] * buckets
    for row in grayscale_image:
        for value in row:
            index = value // span
            # The top value 255 would otherwise fall past the last bucket.
            if index >= buckets:
                index = buckets - 1
            counts[index] += 1
    return counts


def render(grayscale_image):
    ramp = " .:-=+*#%@"
    lines = []
    for row in grayscale_image:
        # Map each intensity onto a character of the ASCII ramp.
        chars = [ramp[value * (len(ramp) - 1) // 255] for value in row]
        lines.append("".join(chars))
    return "\n".join(lines)


def main():
    samples = [
        [[[255, 0, 0], [0, 255, 0]]],
        [[[10, 20, 30]]],
        [[[0, 0, 0], [128, 128, 128], [255, 255, 255]],
         [[200, 100, 50], [30, 60, 90], [12, 34, 56]]],
    ]
    for number, image in enumerate(samples, start=1):
        gray = to_grayscale(image)
        print("Image {0}: {1}".format(number, gray))
        print(render(gray))
        print("Histogram: {0}".format(histogram(gray)))


if __name__ == "__main__":
    main()

