    combined = "".join(extract_numbers(sample) for sample in samples)
    print("combined:", combined)
    print("total digits:", len(combined))

    all_runs = [run for sample in samples for run in split_numbers(sample)]
    if all_runs:
        # Compare runs by numeric value, ignoring leading zeros.
        largest = max(all_runs, key=int)
        print("largest run:", largest, "->", int(largest))


if __name__ == "__main__":
