def normalize_rectangle(x1, y1, x2, y2):
    """Return the rectangle corners ordered as (left, bottom, right, top)."""
    # Corners may arrive in any order, so each axis is sorted separately.
    left, right = min(x1, x2), max(x1, x2)
    bottom, top = min(y1, y2), max(y1, y2)
    return left, bottom, right, top


def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    """True if (px, py) lies inside or on the border of the rectangle."""
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    # Both coordinates must fall inside their respective closed interval.
    return left <= px <= right and bottom <= py <= top


def is_point_on_border(px, py, x1, y1, x2, y2):
    """True if the point touches one of the four rectangle edges."""
    if not is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return False
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    # A contained point lies on an edge exactly when it reaches an extreme.
    return px in (left, right) or py in (bottom, top)


def classify_point(px, py, x1, y1, x2, y2):
    """Return 'outside', 'border' or 'interior' for the given point."""
    if not is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return "outside"
    if is_point_on_border(px, py, x1, y1, x2, y2):
        return "border"
    return "interior"


def parse_case(text):
    """Turn a line of six whitespace separated integers into a tuple."""
    fields = text.split()
    # Anything but six values cannot describe a point and a rectangle.
    if len(fields) != 6:
        raise ValueError("expected 6 integers, got {0}".format(len(fields)))
    return tuple(int(field) for field in fields)


def format_report(px, py, x1, y1, x2, y2):
    """Build a one-line human readable report about the point."""
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    verdict = is_point_in_rectangle(px, py, x1, y1, x2, y2)
    kind = classify_point(px, py, x1, y1, x2, y2)
    return "({0},{1}) in [{2},{3}]x[{4},{5}]: {6} ({7})".format(
        px, py, left, right, bottom, top, verdict, kind
    )


def main():
    import sys

    inside_count = 0
    total = 0
    for line in sys.stdin:
        # Blank separators in the input stream carry no case to evaluate.
        if not line.strip():
            continue
        px, py, x1, y1, x2, y2 = parse_case(line)
        print(format_report(px, py, x1, y1, x2, y2))
        total += 1
        if is_point_in_rectangle(px, py, x1, y1, x2, y2):
            inside_count += 1
    print("{0} of {1} points were inside".format(inside_count, total))


if __name__ == "__main__":
