def _is_hashable(value):
    # Sets only accept hashable members, so probe the value before using one.
    try:
        hash(value)
    except TypeError:
        return False
    return True


def find_common_elements(list1, list2):
    """Return the elements that appear in both list1 and list2, without duplicates."""
    # Reject non-list inputs early: indexing errors later would be much harder to read.
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise TypeError("find_common_elements expects two lists")

    if all(_is_hashable(item) for item in list1 + list2):
        # Set intersection is O(n + m) for hashable elements.
        return list(set(list1) & set(list2))

    # Fallback for unhashable elements such as inner lists or dicts.
    common = []
    for item in list1:
        if item in list2 and item not in common:
            common.append(item)
    return common


def sort_key(value):
    # Mixed types cannot be compared directly, so group by type name first.
    return (type(value).__name__, repr(value))


def format_result(list1, list2, common):
    """Build a single human-readable line describing one comparison."""
    # Sorting keeps the printed report stable even though the order is irrelevant.
    ordered = sorted(common, key=sort_key)
    return "{} & {} -> {}".format(list1, list2, ordered)


def report(pairs):
    """Run find_common_elements over several (list1, list2) pairs and return the lines."""
    lines = []
    for list1, list2 in pairs:
        common = find_common_elements(list1, list2)
        lines.append(format_result(list1, list2, common))
    return lines


def main():
    pairs = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        ([1, 1, 2, 2, 3], [2, 3, 3, 9]),
        ([[1, 2], [3]], [[3], [4]]),
        ([], [1, 2, 3]),
    ]

    for line in report(pairs):
        print(line)


if __name__ == "__main__":
    main()

