"""Utilities for filtering dictionaries by a numeric value threshold."""

from numbers import Real


def _validate_inputs(input_dict, threshold):
    """Reject inputs that cannot be compared numerically."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict, got %s" % type(input_dict).__name__)
    # Booleans are instances of int but make a nonsensical threshold, so refuse them.
    if isinstance(threshold, bool) or not isinstance(threshold, Real):
        raise TypeError("threshold must be an int or float")
    for key, value in input_dict.items():
        # Only real numbers support the ">" comparison the filter relies on.
        if isinstance(value, bool) or not isinstance(value, Real):
            raise TypeError("value for key %r is not numeric: %r" % (key, value))


def filter_dict_by_value(input_dict, threshold):
    """Return a new dict with only the pairs whose value exceeds threshold."""
    _validate_inputs(input_dict, threshold)
    # Strict comparison: a value equal to the threshold is not included.
    return {key: value for key, value in input_dict.items() if value > threshold}


def partition_dict_by_value(input_dict, threshold):
    """Split a dict into the kept pairs and the discarded pairs."""
    kept = filter_dict_by_value(input_dict, threshold)
    # The complement is derived from the kept keys so the two halves always agree.
    dropped = {key: value for key, value in input_dict.items() if key not in kept}
    return kept, dropped


def format_report(input_dict, threshold):
    """Build a human readable summary of one filtering operation."""
    kept, dropped = partition_dict_by_value(input_dict, threshold)
    lines = ["threshold = %g" % threshold]
    if kept:
        # Sorting by descending value makes the strongest matches easy to spot.
        for key, value in sorted(kept.items(), key=lambda item: -item[1]):
            lines.append("  keep  %-6s %g" % (key, value))
    else:
        lines.append("  keep  (nothing passed the threshold)")
    for key, value in sorted(dropped.items()):
        lines.append("  drop  %-6s %g" % (key, value))
    # A percentage gives a quick feel for how aggressive the threshold was.
    total = len(input_dict)
    ratio = (100.0 * len(kept) / total) if total else 0.0
    lines.append("  %d of %d kept (%.1f%%)" % (len(kept), total, ratio))
    return "\n".join(lines)


def main():
    scores = {"a": 10, "b": 20, "c": 5}
    tiny = {"x": 1, "y": 2}
    print(filter_dict_by_value(scores, 15))
    print(filter_dict_by_value(tiny, 5))
    print(format_report(scores, 15))
    print(format_report(tiny, 5))
    # Floating point thresholds work exactly the same way.
    temperatures = {"mon": 18.5, "tue": 22.0, "wed": 22.0, "thu": 15.25}
    print(format_report(temperatures, 20.5))


if __name__ == "__main__":
    main()

