VOWELS = frozenset("aeiou")


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, ignoring case."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    total = 0
    # Lower-casing once keeps the comparison case-insensitive.
    for char in text.lower():
        if char in VOWELS:
            total += 1
    return total


def vowel_histogram(text):
    """Map each vowel to how often it occurs in text."""
    counts = {vowel: 0 for vowel in "aeiou"}
    for char in text.lower():
        # Only the five plain vowels get a bucket; everything else is skipped.
        if char in counts:
            counts[char] += 1
    return counts


def vowel_ratio(text):
    """Return the share of letters in text that are vowels."""
    letters = sum(1 for char in text if char.isalpha())
    # An empty string (or one without letters) has no meaningful ratio.
    if letters == 0:
        return 0.0
    return count_vowels(text) / letters


def most_common_vowel(text):
    """Return the most frequent vowel in text, or None if there is none."""
    counts = vowel_histogram(text)
    best = None
    for vowel in "aeiou":
        # Ties are resolved alphabetically because the comparison is strict.
        if counts[vowel] > 0 and (best is None or counts[vowel] > counts[best]):
            best = vowel
    return best


def describe(text):
    """Build a one-line human readable summary for a single input string."""
    counts = vowel_histogram(text)
    present = [vowel for vowel in "aeiou" if counts[vowel] > 0]
    # Texts such as "rhythm" have no vowels at all to break down.
    if present:
        breakdown = ", ".join("%s=%d" % (v, counts[v]) for v in present)
    else:
        breakdown = "none"
    top = most_common_vowel(text)
    return "%-16r vowels=%d (%s) ratio=%.2f top=%s" % (
        text,
        count_vowels(text),
        breakdown,
        vowel_ratio(text),
        top if top is not None else "-",
    )


def main():
    samples = ["Hello World", "Python", "rhythm", "AEIOU aeiou", ""]
    for sample in samples:
        print(describe(sample))
    grand_total = sum(count_vowels(sample) for sample in samples)
    print("Total vowels in %d samples: %d" % (len(samples), grand_total))


if __name__ == "__main__":
    main()

