def first_unique_char(s: str) -> int:
    # A dictionary to store character counts.
    char_counts = {}
    # Iterate through the string to populate character counts.
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1

    # An index to track the position of characters.
    for i, char in enumerate(s):
        # Check if the character count is 1, indicating uniqueness.
        if char_counts[char] == 1:
            # Return the index of the first unique character.
            return i
    # If no unique character is found after checking all characters.
    return -1 # Return -1 as specified by the problem.

