def convert_length(value, from_unit, to_unit):
    # Constant for conversion from meters to feet.
    METERS_TO_FEET = 3.28084

    # Handle conversion from meters.
    if from_unit == 'm':
        # Convert meters to feet if requested.
        if to_unit == 'ft':
            return value * METERS_TO_FEET
        # Return value unchanged if converting meters to meters.
        elif to_unit == 'm':
            return value
        # Raise an error for invalid target unit.
        else:
            raise ValueError("Invalid 'to_unit'. Use 'm' or 'ft'.")
    # Handle conversion from feet.
    elif from_unit == 'ft':
        # Convert feet to meters if requested.
        if to_unit == 'm':
            return value / METERS_TO_FEET
        # Return value unchanged if converting feet to feet.
        elif to_unit == 'ft':
            return value
        # Raise an error for invalid target unit.
        else:
            raise ValueError("Invalid 'to_unit'. Use 'm' or 'ft'.")
    # Raise an error for invalid source unit.
    else:
        raise ValueError("Invalid 'from_unit'. Use 'm' or 'ft'.")

