"""Utilities for selecting strings by minimum length."""


def _validate_inputs(string_list, min_length):
    """Check the arguments before any filtering happens."""
    # The function contract requires a genuine list of strings.
    if not isinstance(string_list, list):
        raise TypeError("string_list must be a list")
    for index, item in enumerate(string_list):
        if not isinstance(item, str):
            raise TypeError(f"element {index} is not a string: {item!r}")
    # Booleans are integers in Python, so reject them explicitly.
    if isinstance(min_length, bool) or not isinstance(min_length, int):
        raise TypeError("min_length must be an int")
    if min_length < 0:
        raise ValueError("min_length must be non-negative")


def filter_by_length(string_list, min_length):
    """Return the strings from string_list longer than min_length."""
    _validate_inputs(string_list, min_length)
    # Strict comparison: a string of exactly min_length characters is dropped.
    return [text for text in string_list if len(text) > min_length]


def length_histogram(string_list):
    """Map each string length to how many strings share that length."""
    histogram = {}
    for text in string_list:
        histogram[len(text)] = histogram.get(len(text), 0) + 1
    return histogram


def format_report(string_list, min_length):
    """Build a human readable summary of one filtering operation."""
    kept = filter_by_length(string_list, min_length)
    lines = [f"Input ({len(string_list)}): {', '.join(string_list) or '<empty>'}"]
    lines.append(f"Minimum length: {min_length}")
    # Show the kept strings, or a marker when everything was filtered out.
    if kept:
        lines.append(f"Kept ({len(kept)}): {', '.join(kept)}")
    else:
        lines.append("Kept (0): <none>")
    histogram = length_histogram(string_list)
    for length in sorted(histogram):
        count = histogram[length]
        # Mark the length buckets that survived the filter.
        marker = "+" if length > min_length else "-"
        lines.append(f"  {marker} length {length}: {count}")
    return "\n".join(lines)


def main():
    cases = [
        (["apple", "cat", "banana"], 4),
        (["a", "b", "c"], 2),
        (["kiwi", "plum", "strawberry", "fig"], 3),
    ]
    for string_list, min_length in cases:
        print(format_report(string_list, min_length))
        print()

    # Invalid input should surface as an exception rather than a wrong answer.
    try:
        filter_by_length(["ok", 7], 1)
    except TypeError as error:
        print(f"Rejected bad input: {error}")


if __name__ == "__main__":
    main()

