def parse_csv_line(line):
    """Split a single CSV row into a list of field strings."""
    if line is None:
        raise TypeError("line must be a string")
    # Strip a trailing newline so the last field is not polluted by it.
    line = line.rstrip("\r\n")
    fields = []
    current = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # A doubled quote inside a quoted field means a literal quote.
                if i + 1 < len(line) and line[i + 1] == '"':
                    current.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                current.append(ch)
        elif ch == '"':
            in_quotes = True
        elif ch == ',':
            # Comma outside quotes closes the current field, empty or not.
            fields.append("".join(current))
            current = []
        else:
            current.append(ch)
        i += 1
    # The text after the final comma is always a field, even if it is empty.
    fields.append("".join(current))
    return fields


def parse_csv_text(text):
    """Parse a multi-line CSV document into a list of rows."""
    rows = []
    for raw in text.splitlines():
        # Skip blank lines; they carry no fields worth reporting.
        if not raw.strip():
            continue
        rows.append(parse_csv_line(raw))
    return rows


def format_row(fields, width=12):
    """Render one parsed row as fixed-width columns."""
    cells = []
    for field in fields:
        # Show empty fields explicitly so they stay visible in the table.
        cells.append(field if field else "(empty)")
    return " | ".join(cell.ljust(width) for cell in cells)


def column_widths(rows):
    """Return the maximum field count and widest field across all rows."""
    max_cols = 0
    max_len = 0
    for fields in rows:
        max_cols = max(max_cols, len(fields))
        for field in fields:
            max_len = max(max_len, len(field))
    return max_cols, max_len


def main():
    sample = (
        "name,fruit,note\n"
        "apple,banana,cherry\n"
        "one,,three\n"
        '"Doe, Jane",pear,"say ""hi"""\n'
        "trailing,comma,\n"
    )
    rows = parse_csv_text(sample)
    max_cols, max_len = column_widths(rows)
    # Pad the column width a little so "(empty)" also fits.
    width = max(max_len, len("(empty)"))
    print("rows: {0}, columns: {1}".format(len(rows), max_cols))
    for fields in rows:
        print(format_row(fields, width))


if __name__ == "__main__":
    main()

