import random

LOW, HIGH = 1, 100


def validate_inputs(target, max_guesses):
    # Target must sit inside the range the guesses are drawn from,
    # Otherwise the game can never be won and the input is bogus.
    if not LOW <= target <= HIGH:
        raise ValueError(f"target must be between {LOW} and {HIGH}, got {target}")
    # A game with no guesses at all is meaningless rather than simply lost.
    if max_guesses < 1:
        raise ValueError(f"max_guesses must be positive, got {max_guesses}")


def play_guessing_game(target, max_guesses):
    validate_inputs(target, max_guesses)
    for attempt in range(1, max_guesses + 1):
        guess = random.randint(LOW, HIGH)
        # A hit ends the game immediately and the attempt count is the score.
        if guess == target:
            return attempt
    # Ran out of guesses without ever matching the target.
    return -1


def run_trials(target, max_guesses, trials):
    """Play the same game many times and collect the raw results."""
    return [play_guessing_game(target, max_guesses) for _ in range(trials)]


def summarize(results):
    """Turn a list of game results into win-rate and average-length stats."""
    wins = [r for r in results if r != -1]
    # Guard the division: a run where nothing was ever found has no average.
    if wins:
        average = sum(wins) / len(wins)
    else:
        average = None
    return {
        "trials": len(results),
        "wins": len(wins),
        "win_rate": len(wins) / len(results),
        "average_guesses": average,
    }


def format_summary(target, max_guesses, stats):
    header = f"target={target:<3} max_guesses={max_guesses:<4}"
    rate = f"win rate {stats['win_rate'] * 100:5.1f}%"
    # Only report an average when at least one game was actually won.
    if stats["average_guesses"] is None:
        detail = "no wins recorded"
    else:
        detail = f"avg {stats['average_guesses']:.2f} guesses to win"
    return f"{header} | {rate} | {detail} | {stats['wins']}/{stats['trials']}"


def main():
    random.seed(2026)
    trials = 2000
    # More allowed guesses should visibly push the win rate upward.
    for target, max_guesses in [(50, 1), (50, 10), (50, 50), (99, 1), (99, 200)]:
        results = run_trials(target, max_guesses, trials)
        stats = summarize(results)
        print(format_summary(target, max_guesses, stats))

    single = play_guessing_game(50, 10)
    # A single game either reports the winning attempt number or -1.
    if single == -1:
        print("Single demo game: 50 was not guessed within 10 tries")
    else:
        print(f"Single demo game: 50 was guessed on try {single}")


if __name__ == "__main__":
    main()

