def _validate(values, name):
    """Check that the argument is a sorted sequence of numbers."""
    # Strings are iterable but never valid input here.
    if isinstance(values, (str, bytes)) or not isinstance(values, (list, tuple)):
        raise TypeError(name + " must be a list or tuple of numbers")
    for item in values:
        # Booleans are ints in Python, but treating them as numbers is confusing.
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(name + " contains a non-numeric element: " + repr(item))
    for left, right in zip(values, values[1:]):
        # The merge only works if each input is already ordered.
        if left > right:
            raise ValueError(name + " is not sorted at " + repr((left, right)))
    return list(values)


def merge_sorted_lists(list1, list2):
    """Merge two sorted lists of numbers into one new sorted list."""
    first = _validate(list1, "list1")
    second = _validate(list2, "list2")
    merged = []
    i = 0
    j = 0
    # Walk both lists together, always taking the smaller head.
    while i < len(first) and j < len(second):
        if first[i] <= second[j]:
            merged.append(first[i])
            i += 1
        else:
            merged.append(second[j])
            j += 1
    # Whatever remains is already sorted, so it can be appended as-is.
    merged.extend(first[i:])
    merged.extend(second[j:])
    return merged


def merge_many(lists):
    """Merge any number of sorted lists by folding merge_sorted_lists over them."""
    result = []
    for chunk in lists:
        result = merge_sorted_lists(result, chunk)
    return result


def format_merge(list1, list2):
    """Build a readable one-line report of a single merge."""
    try:
        merged = merge_sorted_lists(list1, list2)
    except (TypeError, ValueError) as exc:
        # Report bad input instead of crashing the whole run.
        return "{0!r} + {1!r} -> error: {2}".format(list1, list2, exc)
    return "{0!r} + {1!r} -> {2!r}".format(list1, list2, merged)


def main():
    cases = [
        ([1, 3, 5], [2, 4, 6]),
        ([10], []),
        ([], []),
        ([-5, -1, 0], [-3, 2]),
        ([1.5, 2.5], [1, 2, 3]),
        ([3, 1], [2]),
        ([1, 2], "34"),
    ]
    for left, right in cases:
        print(format_merge(left, right))

    groups = [[1, 4, 9], [2, 3], [], [0, 10]]
    # The folded merge must agree with sorting everything at once.
    combined = merge_many(groups)
    print("merge_many ->", combined)
    flat = sorted(value for group in groups for value in group)
    if combined != flat:
        raise AssertionError("merge_many disagrees with sorted(): " + repr(combined))


if __name__ == "__main__":
    main()

