import re
import sys

# Punctuation that is treated as "attached" to the word it touches.
PUNCTUATION = ".,!?;:\"'()[]{}-—…"

TOKEN_PATTERN = re.compile(
    r"^(?P<prefix>[{p}]*)(?P<core>.*?)(?P<suffix>[{p}]*)$".format(
        p=re.escape(PUNCTUATION)
    )
)


def split_token(token):
    """Split a token into (leading punctuation, core word, trailing punctuation)."""
    match = TOKEN_PATTERN.match(token)
    prefix, core, suffix = match.group("prefix", "core", "suffix")
    # A token made only of punctuation has no core, so it is kept whole.
    if not core:
        return "", token, ""
    return prefix, core, suffix


def reverse_words_with_punctuation(sentence):
    """Reverse the word order of `sentence`, keeping punctuation attached."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")

    tokens = sentence.split()
    # An empty or whitespace-only sentence has nothing to reverse.
    if not tokens:
        return ""

    parts = [split_token(token) for token in tokens]
    reordered = parts[::-1]

    pieces = []
    last_slot = len(parts) - 1
    for slot, (prefix, core, suffix) in enumerate(reordered):
        piece = prefix + core + suffix
        # Every slot keeps the mark that punctuated the sentence at that position.
        slot_suffix = parts[slot][2]
        # The mark arriving with the moved word already ends the last slot.
        if slot < last_slot and slot_suffix and slot_suffix != suffix:
            piece += slot_suffix
        pieces.append(piece)

    return " ".join(pieces)


def format_report(sentences):
    """Build a human-readable before/after report for several sentences."""
    lines = []
    for sentence in sentences:
        reversed_sentence = reverse_words_with_punctuation(sentence)
        lines.append("{!r} -> {!r}".format(sentence, reversed_sentence))
    return "\n".join(lines)


def main(argv):
    # Sentences may be passed as arguments; otherwise they are read from stdin.
    if len(argv) > 1:
        sentences = argv[1:]
    else:
        sentences = [line.strip() for line in sys.stdin if line.strip()]

    # Without any input there is no report to print, which is not an error.
    if not sentences:
        return 0

    print(format_report(sentences))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

