import os
import re
import tempfile

# Words are maximal runs of letters and digits; everything else separates them.
WORD_PATTERN = re.compile(r"[A-Za-z0-9]+")


def extract_words(text):
    """Return every alphanumeric token of text, in order of appearance."""
    return WORD_PATTERN.findall(text)


def read_text(filepath):
    """Read a whole file, returning an empty string when it cannot be read."""
    try:
        with open(filepath, "r", encoding="utf-8") as handle:
            return handle.read()
    except (OSError, UnicodeDecodeError):
        # A missing or undecodable file is treated exactly like an empty one.
        return ""


def find_longest_word_in_file(filepath):
    """Return the longest alphanumeric word in the file, or '' if there is none."""
    longest = ""
    for word in extract_words(read_text(filepath)):
        # Strictly greater keeps the first word when several share the maximum length.
        if len(word) > len(longest):
            longest = word
    return longest


def summarize(filepath):
    """Build a one-line report about the longest word found in filepath."""
    longest = find_longest_word_in_file(filepath)
    # Reports name the file only, so they stay readable for temporary directories.
    name = os.path.basename(filepath)
    if not longest:
        return "{}: no words found".format(name)
    return "{}: {!r} ({} characters)".format(name, longest, len(longest))


def report_lines(paths):
    """Summarize every path, longest find first."""
    results = [(find_longest_word_in_file(path), path) for path in paths]
    # Ties in length fall back to the file name to keep the order deterministic.
    results.sort(key=lambda item: (-len(item[0]), os.path.basename(item[1])))
    return [summarize(path) for _word, path in results]


def build_sample_files(directory):
    """Write the sample inputs into directory and return their paths."""
    samples = {
        "dummy_file.txt": "apple banana a",
        "empty.txt": "",
        "punctuated.txt": "Hello, world! Extraordinarily-long_words: counted42 separately.",
    }
    paths = []
    for name, content in samples.items():
        path = os.path.join(directory, name)
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(content)
        paths.append(path)
    return paths


def main():
    with tempfile.TemporaryDirectory() as directory:
        paths = build_sample_files(directory)
        # The extra path never exists inside a fresh temporary directory.
        paths.append(os.path.join(directory, "not_there.txt"))
        for line in report_lines(paths):
            print(line)


if __name__ == "__main__":
    main()

