def calculate_factorial(n):
    """Return n! for a non-negative integer n, computed iteratively."""
    # Reject booleans explicitly, since bool is a subclass of int
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer, got %r" % (n,))
    if n < 0:
        raise ValueError("factorial is undefined for negative numbers")
    result = 1
    # Zero and one fall through with the initial value of 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def binomial(n, k):
    """Return the number of ways to choose k items out of n."""
    if k < 0 or k > n:
        # Outside the valid range there are no possible selections
        return 0
    return calculate_factorial(n) // (calculate_factorial(k) * calculate_factorial(n - k))


def trailing_zeros(n):
    """Count trailing zeros of n! without building the whole number."""
    count = 0
    power = 5
    # Each power of five contributes one more factor of ten
    while power <= n:
        count += n // power
        power *= 5
    return count


def format_factorial(n):
    """Build a readable one-line report about n!."""
    value = calculate_factorial(n)
    text = str(value)
    if len(text) > 30:
        # Abbreviate very long results so the report stays on one line
        text = text[:15] + "..." + text[-12:]
    return "{}! = {} ({} digits, {} trailing zeros)".format(
        n, text, len(str(value)), trailing_zeros(n)
    )


def parse_argument(token):
    """Convert a command-line token into a non-negative integer."""
    token = token.strip()
    if not token.isdigit():
        raise ValueError("expected a non-negative integer, got %r" % (token,))
    return int(token)


def main(argv):
    if len(argv) > 1:
        numbers = [parse_argument(token) for token in argv[1:]]
    else:
        # Without arguments show a small default sample
        numbers = [0, 1, 5, 10, 25]
    for n in numbers:
        print(format_factorial(n))
    # The poker-hand count is a familiar sanity check on binomial()
    print("C(52, 5) =", binomial(52, 5))
    print("C(5, 7) =", binomial(5, 7))
    return 0


if __name__ == "__main__":
    import sys

    try:
        exit_code = main(sys.argv)
    except (TypeError, ValueError) as error:
        # Report bad input on stderr and signal failure to the shell
        print("error:", error, file=sys.stderr)
        exit_code = 1
    sys.exit(exit_code)

