import sys


def integer_sqrt(n):
    """Return the floor of the square root of n using Newton's method."""
    # Small values would break the initial guess below, so handle them directly.
    if n < 2:
        return n

    # Start from a power-of-two estimate derived from the bit length of n.
    guess = 1 << ((n.bit_length() + 1) // 2)
    while True:
        better = (guess + n // guess) // 2
        # Newton's iteration for square roots never oscillates once it stops shrinking.
        if better >= guess:
            return guess
        guess = better


def is_perfect_square(n):
    """Return True if the non-negative integer n is a perfect square."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    # The last hexadecimal digit of a square is always 0, 1, 4 or 9.
    if n & 0xF not in (0, 1, 4, 9):
        return False

    root = integer_sqrt(n)
    return root * root == n


def parse_arguments(argv):
    """Convert command line words into non-negative integers."""
    numbers = []
    for word in argv:
        try:
            value = int(word)
        except ValueError:
            # Anything that is not an integer literal is reported and skipped.
            print("skipping {!r}: not an integer".format(word), file=sys.stderr)
            continue
        if value < 0:
            print("skipping {}: negative".format(value), file=sys.stderr)
            continue
        numbers.append(value)
    return numbers


def format_report(numbers):
    """Build one text line per number describing its square status."""
    lines = []
    for value in numbers:
        if is_perfect_square(value):
            root = integer_sqrt(value)
            lines.append("{} is a perfect square ({}^2)".format(value, root))
        else:
            # Showing the neighbouring square makes the negative answer easier to trust.
            root = integer_sqrt(value)
            lines.append(
                "{} is not a perfect square (between {}^2 and {}^2)".format(
                    value, root, root + 1
                )
            )
    return lines


def main(argv):
    numbers = parse_arguments(argv[1:])
    # Without arguments, fall back to a range that exercises both outcomes.
    if not numbers:
        numbers = list(range(0, 17))

    for line in format_report(numbers):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

